INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(915, 'koKR', 'Lody, lody dla ochłody...', 'LODY! Och, proszę, proszę, proszę, zdobędziesz dla mnie lody?! Truskawkowe to mój ulubiony smak, a na świecie nie ma lepszych lodów truskawkowych niż truskawkowe lody Tigule\'a i Forora! To moje ulubione lody na całym wielkim świecie!$B$BJadłem je raz, dawno temu, kiedy byłem na torze wyścigowym na Migoczących Równinach, ale słyszałem, że teraz mogą je sprzedawać w mieście! Proszę? Ślicznie proszę? Z truskawkowymi lodami Tigule\'a i Forora na czubku??!?!', 'Zdobądź lody truskawkowe dla swojego podopiecznego. Chłopak najwyraźniej woli lody marki Tigule\'a i Forora.', '', 'Wróć do orczej sieroty.', '', '', '', '', 0),
(925, 'koKR', 'Odcisk kopyta Kairna', 'Mówią, że Kairn Krwawe Kopyto to jeden z największych bohaterów, jakich kiedykolwiek widziała Horda. Jak dorosnę, też chcę być bohaterem Hordy!$B$BZnasz Kairna, $N? Zrobisz coś dla mnie, proszę? Zdobędziesz dla mnie odcisk jego kopyta? Nie wiem, jak go o to poprosić, a on pewnie byłby zbyt zajęty dla kogoś takiego jak ja... ale ty! Jesteś $gposzukiwaczem:poszukiwaczką; przygód, tak jak on! Założę się, że da ci odcisk kopyta bez problemu!$B$BProszę?', 'Udaj się do Gromowych Urwisk i spróbuj zdobyć odcisk kopyta Kairna Krwawego Kopyta dla swojego podopiecznego.', '', 'Wróć do orczej sieroty.', '', '', '', '', 0),
(12806, 'koKR', 'Na Wzniesienie, z należytym pośpiechem!', 'Niektórzy twierdzą, że naszą najważniejszą misją nie jest walka z Królem Liszem, lecz całkowite zniszczenie Szkarłatnego Szturmu. Ja uważam to za głupotę, ale kimże jestem, by osądzać?$B$BWzniesienie Śmierci leży daleko na południowym zachodzie, nad morzem, wzdłuż ściany klifu. Znajdziesz tam lorda-dowódcę Arete, który osobiście nadzoruje niszczenie Szturmu.$B$B<Baron odchrząkuje.>$B$BZechciej zameldować się u niego z należytym pośpiechem. Prosił o ciebie osobiście.', 'Zamelduj się u lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', '', '', '', '', '', '', 0),
(12807, 'koKR', 'Dotychczasowe dzieje...', 'Mamy wiele do zrobienia, ale najpierw przyda się krótkie przypomnienie.$B$BMy, rycerze śmierci, mamy barwną przeszłość z naszymi szkarłatnymi przyjaciółmi, którzy idiotycznie rozgościli się w porcie pod nami, na północnym zachodzie.$B$BGdy będziesz $ggotów:gotowa; nadstawić uszu, porozmawiaj ze mną ponownie, a oświecę cię.', 'Wysłuchaj opowieści lorda-dowódcy Arete na Wzniesieniu Śmierci.', 'Wysłuchano opowieści lorda-dowódcy Arete.', 'Porozmawiaj z lordem-dowódcą Arete na Wzniesieniu Śmierci w Lodowej Koronie.', '', '', '', '', 0),
(12810, 'koKR', 'Krew w wodzie', 'Siły w Porcie Szturmu mają silne wsparcie jeźdźców gryfów. Potrzebujesz wierzchowca, który pozwoli ci ich strącić. Najpierw jednak potrzebujemy składników do rytuału, który to wszystko umożliwi.$B$BDo odprawienia rytuału potrzeba mnóstwo krwi.$B$B<Lord-dowódca wskazuje w dół, na północny zachód.>$B$BTam na dole, w porcie, jest jej pod dostatkiem... rekiny. Nie wracaj do mnie, dopóki nie napełnisz tego pęcherza ich krwią.', 'Lord-dowódca Arete na Wzniesieniu Śmierci chce, żebyś $gnapełnił:napełniła; pęcherz z juchą krwią 10 żarłocznych szczęk.', '', 'Wróć do lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', 'Krew zebrana z żarłocznych szczęk', '', '', '', 0),
(12813, 'koKR', 'Powstańcie z ich trupów!', 'Jakże uprzejmy... jakże hojny jest nasz lord-dowódca. On jest samymi kwiatkami i słońcem, a mnie wypełnia jedynie nienawiść.$B$BNie wystarczy zakończyć ich nędzny żywot... Chcę ich upokorzyć... poniżyć!$B$BCóż może być bardziej haniebnego niż zmienić się w to, czego się nienawidzi? Poświęcić istnienie tępieniu czegoś, by w końcu samemu się tym stać?$B$BJakie to smutne.$B$BZanieś tę nalewkę na północny zachód, do Portu Szturmu. Nanieś ją na ich nieruchome zwłoki i patrz, co się stanie, ale trzymaj się z dala od katedry.', 'Setaal Mroczna Uzdrowicielka na Wzniesieniu Śmierci dała ci nalewkę Mrocznego Uzdrowiciela. Nanieś ją na zwłoki 10 dowolnych członków Szkarłatnego Szturmu w Porcie Szturmu.', '', 'Wróć do Setaal Mrocznej Uzdrowicielki na Wzniesieniu Śmierci w Lodowej Koronie.', 'Przemienione zwłoki członków Szkarłatnego Szturmu', '', '', '', 0),
(12814, 'koKR', 'Potrzebny ci gryf', 'Cóż mogłoby być stosowniejsze niż zabrać im jednego z ich gryfów i użyć go przeciwko nim? Udaj się do Portu Szturmu i wyjmij wodze jednego z gryfów z martwych rąk jego jeźdźca.$B$BWróć z gryfem i dostarcz go Uzo Wzywającemu Śmierć. Zadba o jego właściwą przemianę i przekaże ci dalsze instrukcje.', 'Dostarcz gryfa Szturmu Uzo Wzywającemu Śmierć na Wzniesieniu Śmierci.', '', 'Wróć do Uzo Wzywającego Śmierć na Wzniesieniu Śmierci w Lodowej Koronie.', 'Gryf Szturmu dostarczony Uzo Wzywającemu Śmierć', '', '', '', 0),
(12815, 'koKR', 'Strefa zakazu lotów', 'Teraz, kiedy masz już kościanego gryfa, leć nim tam na dół codziennie i zrób strefę zakazu lotów nad Portem Szturmu.$B$BMuszę przyznać, mon, że mało mnie obchodzi, czy użyjesz kościanego gryfa do zabijania tych jeźdźców gryfów, czy nie. Ale zgaduję, że jak użyjesz, to dużo łatwiej się do nich dobierzesz.$B$BPoza tym gryf zna mnóstwo fajnych sztuczek, których możesz użyć.', 'Uzo Wzywający Śmierć na Wzniesieniu Śmierci chce, żebyś $gzabił:zabiła; 10 jeźdźców gryfów Szturmu.', '', 'Wróć do Uzo Wzywającego Śmierć na Wzniesieniu Śmierci w Lodowej Koronie.', '', '', '', '', 0),
(12838, 'koKR', 'Zbieranie informacji', 'Muszę wiedzieć, co Szkarłatny Szturm planuje na dziś. Będziesz moim narzędziem w tym zadaniu.$B$BLeć do Portu Szturmu i przeszukaj ich kufry bagażowe w poszukiwaniu dokumentów. Kufry będą zamknięte, więc musisz zdobyć klucze od członków Szkarłatnego Szturmu – wszelkimi sposobami.', 'Aurochs Ponura Zguba na Wzniesieniu Śmierci chce, żebyś $gzebrał:zebrała; 5 dokumentów wywiadowczych Szturmu.', '', 'Wróć do Aurochsa Ponurej Zguby na Wzniesieniu Śmierci w Lodowej Koronie.', '', '', '', '', 0),
(12839, 'koKR', 'Wielki (admiralski) plan', 'Na pierwszy rzut oka ten list wygląda jak wszystkie inne dokumenty wywiadowcze, których szukasz. Jednak szybka lektura wyprowadza cię z błędu.$B$BZ listu wynika, że wielki admirał Zachodni Wiatr przebywa gdzieś na wyspie, ale na razie trzyma się w ukryciu. Pisze o chwalebnym dniu, który wkrótce nadejdzie – dniu, w którym Szkarłatny Szturm zmiecie najpierw Króla Lisza, a potem resztę świata, by wreszcie zaprowadzić porządek w Azeroth.$B$BLord-dowódca musi to zobaczyć!', 'Dostarcz list od wielkiego admirała lordowi-dowódcy Arete na Wzniesieniu Śmierci.', '', 'Wróć do lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', '', '', '', '', 0),
(12840, 'koKR', 'Ściśle poufne', 'Jeśli ktoś wie, gdzie jest admirał, to na pewno jego kapitanowie na okrętach w Porcie Szturmu.$B$B<Lord-dowódca zaciera ręce.>$B$BJeśli pamięć mnie nie myli, nazywają się Welsington i Hartford. Wybij z nich te informacje, a potem zakończ ich nędzny żywot.$B$BChcę wiedzieć, gdzie ukrywa się wielki admirał!', 'Lord-dowódca Arete na Wzniesieniu Śmierci chce, żebyś $gwydobył:wydobyła; siłą informacje od kapitanów Welsingtona i Hartforda.', '', 'Wróć do lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', 'Kapitan Welsington przesłuchany siłą i zabity', 'Kapitan Hartford przesłuchany siłą i zabity', '', '', 0),
(12847, 'koKR', 'Druga szansa', 'Słyszałem, że mają w katedrze arcybiskupa, ale nie miałem pojęcia, że wskrzesili Landgrena i jeszcze go awansowali! Karmazynowa Katedra jest silnie strzeżona i ma tylko jedno wejście, więc będziesz potrzebować pomocy.$B$BNadal musimy się dowiedzieć, gdzie jest wielki admirał, ale tym razem nie będziemy ryzykować!$B$BWeź to urządzenie. Gdy zabijesz arcybiskupa, przywołasz nim bramę, przez którą przejdę.$B$BOdpowiedzi wydobędę prosto z jego zniewolonej duszy! Znajdziemy wielkiego admirała Zachodniego Wiatra!', 'Zabij arcybiskupa Landgrena, a następnie przywołaj Bramę Arete przy jego zwłokach. Gdy lord-dowódca Arete skończy przesłuchiwać ducha arcybiskupa, porozmawiaj z nim w Karmazynowej Katedrze.', '', 'Wróć do lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', '', 'Brama Arete przywołana', '', '', 0),
(12852, 'koKR', 'Admirał zdemaskowany', 'Gdy w Nowym Żagiewiu doszło do starcia z najwyższą generał Abbendis, wielki admirał osłonił się nieprzeniknioną sferą magii, a potem uciekł.$B$BJestem szczególnie biegły w neutralizowaniu magii.$B$BUżyj tego przeciwko niemu w Ukrytej Kotlinie, gdy postawi sferę. Chciałbym móc tam być i zobaczyć jego minę, gdy to zrobisz.$B$BZałatw go.', 'Lord-dowódca Arete chce, żebyś $gzałatwił:załatwiła; wielkiego admirała Zachodniego Wiatra. Gdy to zrobisz, wróć do lorda-dowódcy na Wzniesienie Śmierci.', '', 'Wróć do lorda-dowódcy Arete na Wzniesieniu Śmierci w Lodowej Koronie.', 'Wielki admirał Zachodni Wiatr załatwiony', '', '', '', 0),
(12887, 'koKR', 'Zabawa, póki ktoś nie straci oka', 'Rycerze Hebanowego Miecza chcą zdobyć bazę Plagi zwaną Kryptą Cienia, na północnym zachodzie. Mam wśród nich kontakt, który poprosił o pomoc.$B$BPierwszym krokiem jest oślepienie Króla Lisza. Obserwuje okolicę za pomocą urządzenia zwanego Okularem, które unosi się nad iglicami krypty.$B$BNasze krasnoludy stworzyły coś, czego możesz przeciw niemu użyć. Gdy „oko” zostanie zniszczone, odszukaj barona Slivera na terenie krypty. Udaje, że wciąż podlega woli Króla Lisza.', 'Zniszcz Okular, a następnie zamelduj się u barona Slivera w Krypcie Cienia.', '', 'Wróć do barona Slivera w Krypcie Cienia w Lodowej Koronie.', 'Okular zniszczony', '', '', '', 0),
(12891, 'koKR', 'Mam pomysł, ale najpierw...', 'Gdy byłem – ekhm – na służbie u Króla Lisza, często używaliśmy urządzenia zwanego władczą różdżką, by trzymać w ryzach co inteligentniejsze sługi Plagi.$B$BPotrzebuję twojej pomocy przy budowie nowej.$B$BNa szczęście dla ciebie wszystkie potrzebne części są pod ręką: różdżka kultysty, hak plugastwa, lina fantoma i garść esencji Plagi.$B$BTo nie powinno być trudne, $N.', 'Baron Sliver w Krypcie Cienia poprosił cię o zdobycie różdżki kultysty, haka plugastwa, liny fantoma i 5 esencji Plagi.', '', 'Wróć do barona Slivera w Krypcie Cienia w Lodowej Koronie.', '', '', '', '', 0),
(12892, 'koKR', 'Zabawa, póki ktoś nie straci oka', 'Rycerze Hebanowego Miecza chcą zdobyć bazę Plagi zwaną Kryptą Cienia, na północnym zachodzie. Mam wśród nich kontakt, który poprosił o pomoc.$B$BPierwszym krokiem jest oślepienie Króla Lisza. Obserwuje okolicę za pomocą urządzenia zwanego Okularem, które unosi się nad iglicami krypty.$B$BNasze gobliny stworzyły coś, czego możesz przeciw niemu użyć. Gdy „oko” zostanie zniszczone, odszukaj barona Slivera na terenie krypty. Udaje, że wciąż podlega woli Króla Lisza.', 'Zniszcz Okular, a następnie zamelduj się u barona Slivera w Krypcie Cienia.', '', 'Wróć do barona Slivera w Krypcie Cienia w Lodowej Koronie.', 'Okular zniszczony', '', '', '', 0),
(12893, 'koKR', 'Uwolnij umysł', 'Wstręciuch, Lady Nightswood i Skoczek byliby doskonałą bronią w walce z Królem Liszem, gdyby udało się wyrwać ich spod jego woli. Do tego właśnie służy władcza różdżka.$B$BZnajdziesz ich na półkach skalnych na wschód i na zachód od krypty oraz na środkowym poziomie krypty nad nami. Różdżki należy użyć na zwłokach całej trójki.$B$BLeć już. Przeciągniemy ich na naszą stronę!', 'Baron Sliver w Krypcie Cienia chce, żebyś $gużył:użyła; władczej różdżki na zwłokach Wstręciucha, Lady Nightswood i Skoczka.', '', 'Wróć do barona Slivera w Krypcie Cienia w Lodowej Koronie.', 'Wstręciuch przeciągnięty na naszą stronę', 'Lady Nightswood przeciągnięta na naszą stronę', 'Skoczek przeciągnięty na naszą stronę', '', 0),
(12896, 'koKR', 'Jeśli nie da się go przeciągnąć', 'Rycerze śmierci, tacy jak generał Zguba Światła, są trzymani na zbyt krótkiej smyczy, by dało się ich wyrwać spod woli Króla Lisza – chyba że w najbardziej niezwykłych okolicznościach.$B$BGenerał przebywa w krypcie i nadzoruje wytwarzanie nowej broni. Narób zamieszania przy jednym z jego stojaków na broń w północnej kuźni, a zapewniam cię, że się zjawi. Wyślę ci na pomoc Wstręciucha, Lady Nightswood i Skoczka.$B$BJeśli Krypta Cienia ma wreszcie należeć do nas, generał Zguba Światła musi zginąć!', 'Pokonaj generała Zgubę Światła, a następnie zamelduj o sukcesie Thassarianowi na pokładzie kanonierki Niebołamacz.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(12897, 'koKR', 'Jeśli nie da się go przeciągnąć', 'Rycerze śmierci, tacy jak generał Zguba Światła, są trzymani na zbyt krótkiej smyczy, by dało się ich wyrwać spod woli Króla Lisza – chyba że w najbardziej niezwykłych okolicznościach.$B$BGenerał przebywa w krypcie i nadzoruje wytwarzanie nowej broni. Narób zamieszania przy jednym z jego stojaków na broń w północnej kuźni, a zapewniam cię, że się zjawi. Wyślę ci na pomoc Wstręciucha, Lady Nightswood i Skoczka.$B$BJeśli Krypta Cienia ma wreszcie należeć do nas, generał Zguba Światła musi zginąć!', 'Pokonaj generała Zgubę Światła, a następnie zamelduj o sukcesie Koltirze Tkaczowi Śmierci na pokładzie kanonierki Młot Orgrima.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(12898, 'koKR', 'Krypta Cienia', 'Wygląda na to, że $gspisałeś:spisałaś; się znakomicie. A przy okazji $gzdobyłeś:zdobyłaś; dla Rycerzy Hebanowego Miecza trzech bardzo ważnych sojuszników.$B$B<Thassarian spogląda w stronę horyzontu.>$B$BWracaj tam. Baron Sliver i pozostali rycerze śmierci walczą już pewnie zębami i pazurami, by utrzymać Kryptę Cienia pod naporem Plagi.$B$BNa pewno przyda im się twoja pomoc.', 'Zamelduj się u barona Slivera w Krypcie Cienia.', '', '', '', '', '', '', 0),
(12899, 'koKR', 'Krypta Cienia', 'Wygląda na to, że $gspisałeś:spisałaś; się znakomicie. A przy okazji $gzdobyłeś:zdobyłaś; dla Rycerzy Hebanowego Miecza trzech bardzo ważnych sojuszników.$B$B<Koltira spogląda na mapę rozłożoną na podłodze.>$B$BWracaj tam. Baron Sliver i pozostali rycerze śmierci walczą już pewnie zębami i pazurami, by utrzymać Kryptę Cienia pod naporem Plagi.$B$BNa pewno przyda im się twoja pomoc.', 'Zamelduj się u barona Slivera w Krypcie Cienia.', '', '', '', '', '', '', 0),
(12938, 'koKR', 'Książę', 'Musisz się skupić, $N. Ledwo utrzymujemy Kryptę Cienia. Jak widzisz, bardzo rozgniewaliśmy Króla Lisza.$B$B<Baron chichocze.>$B$BPorozmawiaj z księciem Lankralem. To on tu teraz dowodzi. Znajdziesz go w głównym budynku krypty.$B$BNa twoim miejscu nie kazałbym mu czekać.', 'Porozmawiaj z księciem Lankralem w Krypcie Cienia.', '', '', '', '', '', '', 0),
(12939, 'koKR', 'Wyzwanie honorowe', 'Pierwszy krok zrobimy w miejscu w Jotunheim zwanym Dzikim Występem. Leży tuż za górami na zachodzie.$B$BNa występie wrykulscy wojownicy nieustannie ćwiczą walkę, a ludzie ich thana uczą ich subtelniejszych arkanów boju.$B$BWeź tę flagę i rzuć wyzwanie kilku z nich. Zdemoralizujmy ich „marnymi” umiejętnościami kogoś z twojej rasy, dobrze?$B$B<Książę uśmiecha się szeroko, a jego gnijące zęby błyskają w słabym świetle krypty.>', 'Książę Lankral w Krypcie Cienia poprosił cię, żebyś za pomocą flagi wyzwania $gwyzwał:wyzwała; i $gpokonał:pokonała; 6 wojowników Mjordinów.', '', 'Wróć do księcia Lankrala w Krypcie Cienia w Lodowej Koronie.', 'Wojownicy Mjordinów wyzwani i pokonani', '', '', '', 0),
(12943, 'koKR', 'Dekret Krypty Cienia', 'Than Ufrang Potężny zasiada w swojej sali, górującej nad Dzikim Występem. Przestudiowałem go. Than to cierpliwy wrykul, obeznany ze strategią i sztuką wojenną. Wykazał też skłonność do czekania na właściwy moment i niechęć do odkrywania wszystkich kart w trwającej bitwie.$B$BChcę jego śmierci!$B$BSpisałem dekret. Stań przed thanem i odczytaj go na głos.$B$B<Książę unosi brew z rozbawieniem.>$B$BPowinno go to co najmniej... wytrącić z równowagi.', 'Książę Lankral w Krypcie Cienia rozkazał ci odczytać Dekret Krypty Cienia w obecności thana Ufranga Potężnego, a następnie go zabić.', '', 'Wróć do księcia Lankrala w Krypcie Cienia w Lodowej Koronie.', '', '', '', '', 0),
(12949, 'koKR', 'Zdobądź klucz', '$N, klucz do moich kajdan wisi na szyi instruktora Hroegara, tam na zewnątrz.$B$BMoże zdobędziesz go, oddzielając mu głowę od ramion?', 'Vaelen Oskórowany w Sali Ufranga poprosił cię o zdobycie klucza do łańcuchów Vaelena.', '', 'Wróć do Vaelena Oskórowanego w Krypcie Cienia w Lodowej Koronie.', '', '', '', '', 0),
(12951, 'koKR', 'Powiadom barona', 'Najważniejsze, co możesz teraz zrobić, to wrócić do Krypty Cienia i powiadomić barona Slivera, że zawiodłem.$B$BWidzisz, nie tylko mnie schwytały te wrykulskie diabły. Pojmały też cały mój oddział rycerzy śmierci.$B$BPowinienem był dostrzec pułapkę, zanim się zatrzasnęła, ale nie ma co płakać nad rozlanym mlekiem, prawda?$B$BIdź, zanim i ciebie złapią! Zobaczymy się w krypcie.', 'Porozmawiaj z baronem Sliverem w Krypcie Cienia.', '', '', '', '', '', '', 0),
(12955, 'koKR', 'Wyeliminuj konkurencję', 'Mrrfrmrfrrmrrr...$B$B<Skoczek odchrząkuje.>$B$BPrzepraszam. Czasem trudno zrozumieć, co mówię. Wiesz, jak to jest.$B$BChciałem się upewnić, że jeśli trafisz na Dziki Występ, za górami na zachodzie, wyeliminujesz tam konkurencję.$B$BKonkretnie chciałbym, żebyś $gwyzwał:wyzwała; na pojedynek i $gupokorzył:upokorzyła; na oczach wrykulów Sigrid Zrodzoną z Lodu, Efrema Wiernego, Onu\'zuna i Tinky Knotogwizd.', 'Skoczek w Krypcie Cienia chce, żebyś $gpokonał:pokonała; w pojedynkach Sigrid Zrodzoną z Lodu, Efrema Wiernego, Onu\'zuna i Tinky Knotogwizd.', '', 'Wróć do Skoczka w Krypcie Cienia w Lodowej Koronie.', 'Sigrid Zrodzona z Lodu pokonana', 'Efrem Wierny pokonany', 'Onu\'zun pokonany', 'Tinky Knotogwizd pokonana', 0),
(12982, 'koKR', 'Więźniowie Hebanowego Miecza', 'Skoro już wróciłem, baron na pewno zechce, żebym odzyskał swoich ludzi. Widzę, że ledwo się tu trzymamy. Siły Króla Lisza zaraz się przebiją, a bez moich pojmanych rycerzy śmierci nie utrzymamy pozycji.$B$BPomożesz mi jeszcze raz, $N?$B$BWróć do Jotunheim i wypuść ich z tych klatek. Rozwal te przeklęte zamki, nie obchodzi mnie, co musisz zrobić. Klucze mają pewnie wrykule.$B$BPo prostu uwolnij moich ludzi!', 'Vaelen Oskórowany w Krypcie Cienia chce, żebyś $guwolnił:uwolniła; 8 więźniów Hebanowego Miecza. Znajdziesz ich w klatkach w całym rejonie Jotunheim.', '', 'Wróć do Vaelena Oskórowanego w Krypcie Cienia w Lodowej Koronie.', 'Więźniowie Hebanowego Miecza uwolnieni', '', '', '', 0),
(12992, 'koKR', 'Zgniatać wrykule!', 'Te wrykule w Jotunheim trzeba zgniatać!$B$B$N zgniatać je dobrze!', 'Wstręciuch w Krypcie Cienia chce, żebyś $gzabił:zabiła; 15 dowolnych wrykulów w rejonie Jotunheim.', '', 'Wróć do Wstręciucha w Krypcie Cienia w Lodowej Koronie.', 'Zabite wrykule z Jotunheim', '', '', '', 0),
(12995, 'koKR', 'Zostawmy nasz znak', 'Musimy atakować wrykule z Jotunheim na wielu płaszczyznach. Brutalna siła jest oczywiście dobra, ale ja wolę podejście bardziej wyrafinowane.$B$BTwoim zadaniem będzie ich zdemoralizować.$B$BMoi ludzie wykuli dla ciebie sporo sztandarów. Weź je i zatknij przy zwłokach poległych wrykulów.$B$BNiech te sztandary nieustannie im przypominają, że grozi im coś bardziej bezpośredniego niż gniew Króla Lisza.', 'Baron Sliver w Krypcie Cienia chce, żebyś $gzatknął:zatknęła; 15 sztandarów Hebanowego Miecza przy zwłokach wrykulów w rejonie Jotunheim.', '', 'Wróć do barona Slivera w Krypcie Cienia w Lodowej Koronie.', 'Sztandar Hebanowego Miecza zatknięty przy zwłokach wrykula', '', '', '', 0),
(12999, 'koKR', 'Kościana Wiedźma', 'Pamiętasz Lady Nightswood, prawda? Ona na pewno pamięta ciebie. To ta zrozpaczona i bardzo rozgniewana banshee, którą „$guratowałeś:uratowałaś;”, kiedy $gwyrwałeś:wyrwałaś; też Wstręciucha i mnie spod władzy Króla Lisza.$B$BLady udała się do Jotunheim i opętała ich kościaną wiedźmę. Zamierza siać spustoszenie wśród wrykulów od środka.$B$BProsi, żebyś ją $godnalazł:odnalazła;. Znajdziesz ją w jaskini po południowej stronie Wioski Njorndar, na południowym zachodzie Jotunheim.', 'Porozmawiaj z Kościaną Wiedźmą w jaskini w Wiosce Njorndar.', '', '', '', '', '', '', 0),
(13008, 'koKR', 'Taktyka Plagi', 'Mieliśmy po swojej stronie element zaskoczenia! Wysadziliśmy dziurę w zboczu góry i ruszyliśmy do szarży na Plagoholm. Opór Plagi był zażarty i wkrótce nas przytłoczyli. Wycofaliśmy się do doliny i zaczęliśmy zasypywać ogniem artylerii Plagę, która ruszyła za nami. To powstrzymywało ich przez jakiś czas, aż... te potwory zaczęły używać krzyżowców jako żywych tarcz. Musieliśmy przerwać ostrzał, żeby nie pozabijać własnych żołnierzy.$B$BUwolnij naszych krzyżowców uwięzionych na polu przed bazą, $N!', 'Dowódca krucjaty Entari w Awangardzie Argentu w Lodowej Koronie poprosił cię o uwolnienie 8 krzyżowców oplątanych siecią.', '', 'Wróć do dowódcy krucjaty Entariego w Awangardzie Argentu w Lodowej Koronie.', 'Krzyżowiec oplątany siecią uwolniony', '', '', '', 0),
(13036, 'koKR', 'Honor ponad wszystko', 'Długa była droga do naszego zbawienia, $gmłody przyjacielu:młoda przyjaciółko;. Walczyliśmy na wielu kontynentach, a nawet w innych światach, by dotrzeć do tej chwili. Teraz stoimy przed największym wyzwaniem: zniszczeniem Króla Lisza i jego Plagi.$B$BNiestety, toczymy tę bitwę podzieleni. Horda i Przymierze są pogrążone w wojnie i nie udzielą nam wsparcia. Musimy trwać niezłomnie przy naszej sprawie! Bo czyż mamy inny wybór?$B$BCzy przyłączysz się do nas? Użycz nam swej siły, $N! Mój dowódca, Entari, czeka na ciebie na swoim posterunku.', 'Zamelduj się u dowódcy krucjaty Entariego w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13039, 'koKR', 'Obrona Awangardy', 'Nie wytrzymamy długo tego tempa, $gchłopcze:dziewczyno;. Odkąd wysadzono wyłom, puściły wszystkie tamy. Plaga wlewa się przez niego od tamtej pory i końca nie widać!$B$BPotrzebujemy każdego zdolnego do walki mężczyzny i każdej kobiety, żeby powstrzymać falę zła. Ruszaj tam i zrób, co do ciebie należy, $gprzyjacielu:przyjaciółko;. Zabij tyle tych potworów, ile zdołasz!', 'Lord krzyżowców Dalfors w Awangardzie Argentu w Lodowej Koronie poprosił cię o zabicie 15 nerubian z Zapomnianych Głębin.', '', 'Wróć do lorda krzyżowców Dalforsa w Awangardzie Argentu w Lodowej Koronie.', 'Zabici nerubianie z Zapomnianych Głębin', '', '', '', 0),
(13040, 'koKR', 'Leczenie nieuleczalnego', 'Liczba rannych żołnierzy rośnie z każdym dniem. Zatruwa ich jakaś toksyna, jakiej nigdy wcześniej nie widzieliśmy. Cokolwiek ci nerubianie noszą w gruczołach jadowych, jest śmiertelne i nieuleczalne! Jak dotąd udało nam się jedynie spowolnić krążenie trucizny w ciałach ofiar. Musimy opracować lekarstwo!$B$BUdaj się na północny zachód, do doliny za Awangardą, i zabijaj nerubian z Zapomnianych Głębin. Zdobądź ich gruczoły jadowe i przynieś mi je.', 'Ojciec Gustav w Awangardzie Argentu w Lodowej Koronie poprosił cię o przyniesienie 10 gruczołów jadowych z Zapomnianych Głębin.', '', 'Wróć do ojca Gustava w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13042, 'koKR', 'Głęboko w trzewiach Podziemnych Sal', 'Głęboko w trzewiach Podziemnych Sal, na północnym wschodzie, szalony naukowiec zwany doktorem Okropnym knuje coś godnego swojego imienia.$B$BKról Lisz pozwolił doktorowi przeprowadzać eksperymenty na wargulach – wrykulach, którzy polegli w bitwie, zostali uznani za niegodnych, a potem zmienieni w sługi Plagi.$B$BMusimy położyć kres jego pracy, ale moje wróżby nie zdołały go odnaleźć. Ma on jednak asystenta.$B$BWybij informacje z jego ucznia, a potem pozbądź się ciała.', 'Kościana Wiedźma w Wiosce Njorndar poprosiła cię, żebyś $gwydobył:wydobyła; siłą od ucznia Osterkilgra informacje o tym, co naprawdę knuje doktor Okropny.$B$BNastępnie masz zabić ucznia.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', 'Informacje wydobyte siłą od ucznia Osterkilgra', '', '', '', 0),
(13043, 'koKR', 'Całość to więcej niż suma części', 'Otwierając księgę, dostrzegasz najrozmaitsze obrzydliwe ilustracje przedstawiające budowę czegoś, co doktor nazywa „ostateczną bronią”!$B$BNajwyraźniej prototypem jest Nergeld, ogromny mięsny olbrzym stojący bez ruchu na końcu pobliskiej Sali Okropności.$B$BGdyby zbudowano armię takich stworów, oznaczałoby to zagładę. Jedynym sposobem, by temu zapobiec, jest zabicie doktora Okropnego!$B$BMoże jeśli przejmiesz kontrolę nad tym konstruktem, doktor się ujawni?', 'Dosiądź Nergelda i przejmij nad nim kontrolę. Broń go przed mieszkańcami Sali Okropności, dopóki nie pojawi się doktor Okropny.$B$BZabij doktora przy pomocy Nergelda, a następnie wróć do Kościanej Wiedźmy w Wiosce Njorndar.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', '', '', '', '', 0),
(13044, 'koKR', 'Jeśli są ocaleni...', 'Za Doliną Ech, na zachód stąd, i dalej przez Wyłom leży pierwsze obozowisko Plagi w Lodowej Koronie, zwane Plagoholmem. Stoczyliśmy w Plagoholmie dobrą walkę i wybiliśmy wielu sług Plagi, ale w końcu musieliśmy się wycofać. Wielu żołnierzy zostało na miejscu – ich los jest nieznany.$B$BJeśli są ocaleni, musimy spróbować ich uratować. Tą ścieżką prosto na południowy wschód znajdziesz Penumbriusa, sojusznika Brązowego Stada i opiekuna protosmoczego lęgu. Odszukaj go i poproś o pomoc.', 'Porozmawiaj z Penumbriusem w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13045, 'koKR', 'W dziką, zieloną dal', 'Zrobimy wszystko, co w naszej mocy, by ci pomóc, $N. Protosmoczy lęg zgłosił się na ochotnika, by przenieść cię nad Wyłomem do Plagoholmu. Ratuj wszystkich pojmanych krzyżowców Argentu, jakich znajdziesz. Natychmiast odstawiaj ich do Lazaretu Awangardy, w samym środku tej bazy.$B$BWybierz jednego ze srebrnych szponów niebios w zagrodzie za mną i ruszaj!$B$BPlagoholm leży na północnym zachodzie, za Doliną Ech, po drugiej stronie wielkiego Wyłomu.', 'Uratuj 3 pojmanych krzyżowców Argentu z Plagoholmu i odstaw ich do Lazaretu Awangardy w samym środku Awangardy Argentu. Jeśli ci się uda, zamelduj się u najwyższego lorda Tiriona Fordringa.', '', 'Wróć do najwyższego lorda Tiriona Fordringa w Awangardzie Argentu w Lodowej Koronie.', 'Pojmany krzyżowiec uratowany', '', '', '', 0),
(13059, 'koKR', 'Zemsta za wargula', 'Modliłem się do Pani Miecza, by zesłała kogoś, kto powali mojego wroga. Than Illskar musi zapłacić za to, co mi zrobił!$B$BByłem czempionem thana Ufranga Potężnego. Podczas mojej walki o wyniesienie w Valhalas Illskar podstępnie użył przeciwko mnie mrocznej magii, przez co przegrałem i stałem się tym czymś.$B$BThana i jego czempionów znajdziesz na dole, w Kręgu Cierpienia. Wyzwij go w moim imieniu. Pokonaj go.$B$BNiech pozna cierpienie, które ja znam!', 'Bethod Feigr w Podziemnych Salach chce, żebyś $grzucił:rzuciła; na ziemię jego miecz, wyzywając thana Illskara, a potem $gzabił:zabiła; go w Kręgu Cierpienia.', '', 'Wróć do Bethoda Feigra w Podziemnych Salach w Lodowej Koronie.', 'Wyzwanie rzucone mieczem Bethoda', '', '', '', 0),
(13068, 'koKR', 'Opowieść o męstwie', 'Może dotarły do ciebie pochwały na cześć naszego zaginionego bohatera?$B$BKrzyżowiec Bridenbrad walczył na Złamanym Froncie, wspierając atak na Plagę, gdy spadła na nich armia nieumarłych. Liczni żołnierze tych sprzymierzonych sił rozproszyli się, ale Bridenbrad sam jeden zawrócił i wyciągnął w bezpieczne miejsce ponad tuzin ludzi, jednego po drugim, z samego środka rzezi.$B$B$N, od tamtej pory nie wrócił. Widziano, jak zmierzał daleko na północny wschód, w stronę Cichego Czuwania. Sprowadź go do mnie, abym mógł uhonorować go za męstwo.', 'Najwyższy lord Tirion Fordring na Szczycie Krzyżowców poprosił cię o odnalezienie bohatera, krzyżowca Bridenbrada, przy Cichym Czuwaniu w północno-wschodniej części Lodowej Korony. Z powietrza najłatwiej będzie go pewnie wypatrzyć po ognisku.', '', '', '', '', '', '', 0),
(13069, 'koKR', 'Zestrzel ich wszystkich!', 'Jotunheim ma obronę powietrzną – zarówno jeźdźców protosmoków, jak i działa harpunowe. Skupili ją od północy i zachodu, gdzie są najbardziej narażeni.$B$BObróćmy ich obronę przeciwko nim!$B$B<Skoczek przeszywa cię spojrzeniem swojego jedynego oka i chichocze jak szaleniec.>$B$BPrzejmij kontrolę nad działem harpunowym na platformach wystających nad klifami po obu stronach Valhalas, na południowym zachodzie. Zestrzel protosmoki i ich jeźdźców. Zestrzel ich wszystkich!', 'Skoczek w Krypcie Cienia chce, żebyś za pomocą szybkostrzelnego harpuna z Jotunheim $gzestrzelił:zestrzeliła; 15 protosmoków z Jotunheim wraz z jeźdźcami.', '', 'Wróć do Skoczka w Krypcie Cienia w Lodowej Koronie.', 'Zestrzelone protosmoki z Jotunheim i ich jeźdźcy', '', '', '', 0),
(13070, 'koKR', 'Nadciąga chłodny front', 'Na zachodzie budzi się chłód śmierci, który grozi, że przymrozi nasze serca i dusze do tego pustkowia i przykuje nas do jego mrocznego pana. Stawimy opór i będziemy walczyć!$B$BPrzygotowania już się rozpoczęły. Zamelduj się po przydział u mistrza oblężeń Fezzika przy głównej bramie.', 'Zamelduj się u mistrza oblężeń Fezzika w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13071, 'koKR', 'Wstręciuch lubić ogień!', 'Wstręciuch lubić ogień! Wstręciuch lubić protosmoki!$B$B<Plugastwo z podnieceniem klaszcze w dłonie.>$B$B$GMały:Mała; $N iść do Jotunheim i ukraść ładny protosmok w Wiosce Njorndar. Zrobić, że protosmok robi ładne ognie na budynki w Jotunheim!', 'Wstręciuch w Krypcie Cienia chce, żebyś $gukradł:ukradła; protosmoka z Njorndar i $gpodpalił:podpaliła; nim 8 budynków wrykulów w rejonie Jotunheim.$B$BFortecy Balargarde, z racji jej natury, nie da się podpalić.', '', 'Wróć do Wstręciucha w Krypcie Cienia w Lodowej Koronie.', 'Podpalone budynki wrykulów', '', '', '', 0),
(13072, 'koKR', 'Bohater zostaje', 'Wiem, po co $gprzyszedłeś:przyszłaś;... przysłano cię, żeby mnie sprowadzić z powrotem, ale do tego nie może dojść. Noszę w sobie zarazę nieżycia, $N, i nie podzielę się swoim losem z tymi, którzy są blisko mnie. Nie, zostanę tutaj.$B$BŻałuję jedynie tego, czym mogę się stać, gdy dopadnie mnie śmierć. Nie boję się samej śmierci, ale wzdragam się na myśl o służbie zdrajcy, Arthasowi.$B$BZostaw mnie... i dopilnuj, żeby nikt inny mnie nie szukał. $GWyrządziłbyś:Wyrządziłabyś; mi wielką krzywdę, gdybyś $gnaraził:naraziła; kogokolwiek na zarazę, którą noszę.', 'Zanieś wieści o losie krzyżowca Bridenbrada najwyższemu lordowi Tirionowi Fordringowi na Szczycie Krzyżowców.', '', '', '', '', '', '', 0),
(13076, 'koKR', 'Jest jeszcze czas', 'Czuję się pokrzepiony... odnowiony... ale zaraza wciąż mnie trzyma. Nie martw się, i tak jestem ci dozgonnie wdzięczny, że $gzadałeś:zadałaś; sobie tyle trudu dla mnie, zupełnie obcego człowieka. Jeśli nic więcej, to przynajmniej $gzyskałeś:zyskałaś; dla mnie kilka cennych godzin, w których nie roznoszę zarazy po świecie jako ohydny nieumarły.$B$BDziękuję, $N. Przekaż, proszę, moje podziękowania także Tirionowi i powiedz mu, że służba u jego boku była dla mnie zaszczytem.', 'Wróć do najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców z wieściami o działaniu szmaragdowego żołędzia.', '', '', '', '', '', '', 0),
(13080, 'koKR', 'Nadzieja wciąż żyje', '<Bridenbrad unosi ku tobie dłoń, łapiąc oddech.>$B$BBolało prawie tak, jak to wyglądało, ale czułem, jakby część zepsucia wypalała się z mojego ciała. Wygląda jednak na to, że zarazy nie da się tak łatwo pokonać.$B$B$N, dziękuję ci za wszystko, co $gzrobiłeś:zrobiłaś;. Twoja bezinteresowność odnowiła moją nadzieję, że na tym świecie wciąż zostało wiele dobra – mogę odejść bez obawy, że pod moją nieobecność zwycięży ciemność.$B$BIdź już i niczego nie żałuj.', 'Wróć do najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców z wieściami o działaniu Oddechu Alexstrazy.', '', '', '', '', '', '', 0),
(13083, 'koKR', 'Światło w ciemności', '<Na dnie skrzyni leży tabard krzyżowca Bridenbrada, poruszający się lekko, gdy do środka wdziera się wyjący wiatr.>$B$BTirion na pewno zechce otrzymać tę ostatnią pamiątkę po wielkim krzyżowcu.', 'Zanieś tabard krzyżowca Bridenbrada najwyższemu lordowi Tirionowi Fordringowi na Szczycie Krzyżowców.', '', 'Wróć do najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców w Lodowej Koronie.', '', '', '', '', 0),
(13084, 'koKR', 'Wandalizm w Jotunheim', 'Zobaczmy, czy uda się jeszcze bardziej osłabić determinację wrykulów, $N.$B$BKażdego dnia udawaj się do Jotunheim i podpalaj ich sztandary. Może się to wydawać drobnostką, ale widok codziennie niszczonego rodowego domu zdemoralizuje ich bardziej niż jakakolwiek kara cielesna, którą możesz im wymierzyć.$B$BA przynajmniej... nie zaszkodzi.', 'Książę Lankral w Krypcie Cienia chce, żebyś $gspalił:spaliła; 10 sztandarów wrykulów.', '', 'Wróć do księcia Lankrala w Krypcie Cienia w Lodowej Koronie.', 'Spalone sztandary wrykulów', '', '', '', 0),
(13085, 'koKR', 'Vaelen powrócił', 'Właśnie widziałem, jak ten nieudolny głupiec, Vaelen Oskórowany, zakradł się do budynku krypty.$B$BIdź i dopilnuj, żeby naprawił swój błąd i oddał mi moich rycerzy śmierci!', 'Porozmawiaj z Vaelenem Oskórowanym w Krypcie Cienia.', '', '', '', '', '', '', 0),
(13086, 'koKR', 'Ostatnia linia obrony', 'Uruchomiłem obronę bazy, $N! Na szczycie każdej z czterech wież Awangardy stoi wysuwane działo Krucjaty Argentu, pobłogosławione przez samego ojca Gustava. Musisz polecieć na jedną z tych wież i obsadzić działo. Użyj go, by zniszczyć nawałę Plagi, którą wysłał Król Lisz.$B$BJedno ostrzeżenie: Plaga z pewnością wyśle swoje żmije mrozu, by oblegały wieże. Zestrzel je z nieba! Jeśli zniszczą mury i wieże tej bazy, jesteśmy skończeni!', 'Za pomocą działa Argentu zniszcz 100 napastników Plagi. Musisz też zabić 3 niszczycieli Mroźnego Pomiotu.$B$BJeśli ci się uda, wróć do mistrza oblężeń Fezzika.', '', 'Wróć do mistrza oblężeń Fezzika w Awangardzie Argentu w Lodowej Koronie.', 'Zabici napastnicy Plagi', '', '', '', 0),
(13091, 'koKR', 'Sztuka bycia wodnym postrachem', 'Śluza przed moją jaskinią roi się od żywiołaków, których wrykulscy magowie jeszcze nie oswoili. Nauczę cię sztuczki, dzięki której na krótko opętasz te stworzenia, a ty użyjesz ich, by siać spustoszenie w Jotunheim!$B$B<Opętana przez banshee wrykulka kreśli w powietrzu magiczne znaki i dotyka dużym palcem twojego czoła.>$B$BIdź teraz i otwórz bramę śluzy. Wypadnie z niej wodny postrach, a ty go opętasz i zniszczysz naszych wrogów!', 'Kościana Wiedźma w Wiosce Njorndar chce, żebyś $gopętał:opętała; wodnego postrachu i $gzabił:zabiła; nim 10 wrykulów w rejonie Jotunheim.$B$BLiczą się: strażnicy snu z Jotunheim, wojownicy z Jotunheim, magowie wody Mjordinów, siostry włóczni z Njorndar i wargule z Valhalas.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', 'Wrykule z Jotunheim zabici w ciele wodnego postrachu', '', '', '', 0),
(13092, 'koKR', 'Wróżenie z kości', 'Jedną z korzyści opętania tej istoty jest to, że mam dostęp do wszystkich jej mocy. Jako kościana wiedźma i odczytywaczka run potrafi rzucać kości i przepowiadać czyjś los.$B$B<Kościana Wiedźma uśmiecha się drwiąco.>$B$BNa szczęście dla nas obojga mam moc wpływania na te wróżby.$B$BPrzynieś mi kości wrykulów, których zabijesz tu, w Jotunheim, a rzucę je, pozwalając ci wybrać własny los.', 'Kościana Wiedźma w Wiosce Njorndar poleciła ci zebrać 15 kości wrykulów.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', '', '', '', '', 0),
(13093, 'koKR', 'Wróżenie z kości', '', '', '', 'Wróć do Kościanej Wiedźmy w Lodowej Koronie.', '', '', '', '', 0),
(13104, 'koKR', 'Jeszcze raz do Wyłomu, bohaterze', 'Awangarda jest bezpieczna, $gsojuszniku:sojuszniczko;. Odbiliśmy Dolinę Ech i zerwaliśmy pajęcze ściany blokujące wejście do Wyłomu. Nadszedł czas, by uderzyć na Plagoholm i zadomowić się w Lodowej Koronie. Front przesuwa się naprzód!$B$BPoprosiłem Hebanowego Wartownika o pomoc w natarciu na Plagoholm. Jego dogłębna znajomość Plagi okaże się bezcenna.$B$BIdź teraz i zamelduj się u niego w namiocie przed Wyłomem, na północny zachód stąd.', 'Zamelduj się u Hebanowego Wartownika w Dolinie Ech, tuż przed Wyłomem.', '', '', '', '', '', '', 0),
(13105, 'koKR', 'Jeszcze raz do Wyłomu, bohaterze', 'Awangarda jest bezpieczna, $gsojuszniku:sojuszniczko;. Odbiliśmy Dolinę Ech i zerwaliśmy pajęcze ściany blokujące wejście do Wyłomu. Nadszedł czas, by uderzyć na Plagoholm i zadomowić się w Lodowej Koronie. Front przesuwa się naprzód!$B$BPoprosiłem Hebanowego Wartownika o pomoc w natarciu na Plagoholm. Jego dogłębna znajomość Plagi okaże się bezcenna.$B$BIdź teraz i zamelduj się u niego w namiocie przed Wyłomem, na północny zachód stąd.', 'Zamelduj się u Hebanowego Wartownika w Dolinie Ech, tuż przed Wyłomem.', '', '', '', '', '', '', 0),
(13106, 'koKR', 'Czarna Straż', 'Plaga ma wielki zakład zwany Mięsarnią, gdzie wytwarza plugastwa i mięsne olbrzymy. Jeśli zdołamy go unieruchomić, pozbawimy Króla Lisza dużej części jego armii.$B$BWysłałem w ten rejon mroczną jeźdźczynię Arly. Ma niewielką bazę, Czarną Straż, na grani górującej nad Mięsarnią, na zachód od Corp\'rethar. Podobno Krucjata Argentu wysyła kogoś, kto ma koordynować tam jej działania, ale mroczna jeźdźczyni będzie wiedziała, co robić. Odszukaj ją i pomóż jej.', 'Porozmawiaj z mroczną jeźdźczynią Arly w Czarnej Straży w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13110, 'koKR', 'Niespokojni zmarli', 'Nie wszyscy nasi żołnierze wydostali się z Plagoholmu. Wielu poległo i zostało przemienionych w wypaczone odbicia samych siebie. Taka jest droga Plagi. Dla tych potępionych dusz nie ma wiecznego spoczynku. Musimy zapewnić im odpoczynek.$B$BPrzejdź przez Wyłom do Plagoholmu i zabijaj ożywionych szkieletowych krzyżowców. Pokrop ich kości tą wodą święconą, by ich duchy mogły zostać uwolnione.', 'Ojciec Gustav w Dolinie Ech w Lodowej Koronie chce, żebyś $gużył:użyła; wody święconej na zwłokach ożywionych krzyżowców i $guwolnił:uwolniła; 10 niespokojnych dusz.', '', 'Wróć do ojca Gustava w Dolinie Ech w Lodowej Koronie.', 'Niespokojna dusza uwolniona', '', '', '', 0),
(13117, 'koKR', 'Skąd one się biorą?', 'Niestrudzeni słudzy Króla Lisza pracują dniem i nocą, by składać tam w dole, w Mięsarni, całe zastępy plugastw i mięsnych olbrzymów.$B$BA jednak to nie wystarcza. Pojawia się coraz więcej szkieletowych konstruktorów, żeby przyspieszyć pracę.$B$BJeśli nie odkryjemy, skąd przychodzą i jak udaje im się pracować tak szybko, zostaniemy zmiażdżeni, zanim zdążymy uderzyć z pełną siłą. Przeszukaj teren na południowym wschodzie i sprawdź, czy uda ci się znaleźć źródło tych szkieletów.', 'Zbadaj ołtarz przywołań we wschodniej części Mięsarni, a następnie złóż raport mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Ołtarz przywołań zbadany', '', '', '', 0),
(13118, 'koKR', 'Oczyszczenie Plagoholmu', 'Plaga rzuciła swoje armie na Krucjatę Argentu i została odparta. To, co robią teraz, nazywa się „spaloną ziemią”. Wszyscy więźniowie, których trzymają w Plagoholmie, zostaną straceni i wskrzeszeni jako słudzy Króla Lisza.$B$BKrucjata Argentu z pewnością poprosi cię o godne pożegnanie ich żołnierzy. Ja nie będę cię o nic takiego prosił. Aby odnieść sukces, musimy zabijać sługi Plagi bez wyjątku.$B$BUdaj się do Plagoholmu, na północny zachód przez Wyłom, i zniszcz wszystko, co stanie ci na drodze.', 'Hebanowy Wartownik w Dolinie Ech w Lodowej Koronie chce, żebyś $gzabił:zabiła; 3 arcykapłanów Zapomnianych Głębin, 3 władców podziemi Zapomnianych Głębin i 8 ożywionych krzyżowców.', '', 'Wróć do Hebanowego Wartownika w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13119, 'koKR', 'Zniszczenie ołtarzy', 'Więc przywołują swoich robotników i wojowników przy tych ołtarzach?$B$BTrzeba się ich pozbyć w pierwszej kolejności. Mistrz przywoływania powinien mieć laskę, którą uruchamia portal. Jeśli zabijesz mistrza przywoływania i zabierzesz laskę, możesz jej użyć, by przeciążyć portal przywołań i zniszczyć jego ołtarz.$B$BZrób to przy wszystkich czterech ołtarzach i wróć do mnie, gdy zostaną zniszczone.', 'Zabij mistrza przywoływania Zaroda i jego laską przywołań zniszcz pierwszy, drugi, trzeci i czwarty ołtarz przywołań. Gdy to zrobisz, zamelduj się u mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Pierwszy ołtarz przywołań zniszczony', 'Drugi ołtarz przywołań zniszczony', 'Trzeci ołtarz przywołań zniszczony', 'Czwarty ołtarz przywołań zniszczony', 0),
(13120, 'koKR', 'Spojrzenie Śmierci', 'Mięsarnia to ogromne przedsięwzięcie i trudno będzie mieć oko na wszystko, co się tam dzieje. Na szczęście mam plan.$B$B<Arly wyjmuje kulę z fałd płaszcza i pokazuje ci ją.>$B$BTo kula spojrzenia śmierci. Dzięki niej możemy obserwować poczynania Plagi i zdecydować, jak najlepiej uderzyć.$B$BUmieść te kule na stojakach w trzech kluczowych miejscach – w pracowni plugastw i pracowni mięsnych olbrzymów na południowym zachodzie oraz w okolicy zielonego kotła daleko na zachodzie.', 'Za pomocą Kuli Spojrzenia Śmierci umieść kule na stojaku w pracowni plugastw, stojaku w pracowni mięsnych olbrzymów i stojaku przy kotłach, a następnie wróć do mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Kula umieszczona w pracowni plugastw', 'Kula umieszczona w pracowni mięsnych olbrzymów', 'Kula umieszczona przy kotłach', '', 0),
(13121, 'koKR', 'Przez Oko', 'Musimy użyć narzędzi Króla Lisza przeciwko niemu, jeśli mamy zdecydować o następnym kroku.$B$BZa górą na południowym zachodzie leży Twierdza Kul\'galar. Mieszkają w niej wyrocznie z Jotunheim, które otrzymują rozkazy od swojego pana i szpiegują innych za pomocą Oka Króla Lisza.$B$BTo do oka musisz się przebić. Choć nie da się nim przeniknąć zasłony nad Cytadelą Lodowej Korony, powinno pozwolić ci dostrzec coś cennego, byśmy wiedzieli, jak najlepiej postąpić.', 'Kościana Wiedźma w Wiosce Njorndar poleciła ci zdobyć informacje za pomocą Oka Króla Lisza.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', 'Informacje dla Kościanej Wiedźmy zdobyte', '', '', '', 0),
(13122, 'koKR', 'Kamień Plagi', 'Kamień Plagi to przedmiot, który każdy sługa Plagi otrzymuje w chwili narodzin lub stworzenia. Daje posiadaczowi pewne korzyści, ale co ważniejsze, pozwala przywódcom Plagi widzieć położenie i ruchy wszystkich ich oddziałów.$B$BMając dość kamieni Plagi, może zdołam śledzić ruchy innych oddziałów Plagi w całej Lodowej Koronie.$B$BZabijając sługi Plagi w Plagoholmie, zbieraj wszystkie kamienie Plagi, jakie znajdziesz. Wróć do mnie, gdy twoje torby będą pełne.', 'Hebanowy Wartownik w Dolinie Ech w Lodowej Koronie chce, żebyś $gprzyniósł:przyniosła; mu 15 kamieni Plagi.', '', 'Wróć do Hebanowego Wartownika w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13125, 'koKR', 'Powietrze zamiera', 'Musisz pokonać władców Plagoholmu, jeśli to miejsce ma się wyrwać z uścisku Plagi.$B$BSalranax Rozdzieracz Ciał włada świątynią na pierwszym poziomie Plagoholmu. Niedaleko Salranaxa znajdziesz arcykapłana Yath\'amona, który głosi kazania przy wieży duchów na drugim poziomie. Władca podziemi Talonox urzęduje w Czeluści Biesów, wyżej, przy górnej drodze.$B$BTo groźni przeciwnicy, trzeba się do nich zbliżać ostrożnie. Jeśli będziesz potrzebować pomocy, użyj tego rogu wojennego. Przybędą rycerze śmierci z Acherusu.', 'Hebanowy Wartownik w Dolinie Ech w Lodowej Koronie chce, żebyś $gzabił:zabiła; Salranaxa Rozdzieracza Ciał, władcę podziemi Talonoxa i arcykapłana Yath\'amona.', '', 'Wróć do Hebanowego Wartownika w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13130, 'koKR', 'Kamień, od którego zaczęła się rewolucja', 'Możesz teraz patrzeć na Plagoholm i widzieć zjełczałą jamę rozkładu, ale pewnego dnia będzie to miejsce chwały i honoru. Najwyższy lord Fordring nazwał je „Twierdzą Sprawiedliwości”.$B$BCóż, nawet tak niezdobyta forteca jak Cytadela Lodowej Korony zaczęła się od jednego kamienia. Tak oto zaczynamy poszukiwania kamienia, który rozpocznie rewolucję.$B$BUdaj się do Lasu Kryształowej Pieśni, na południe stąd, i odszukaj Wyzwolony Gąszcz na wschodzie. Tam zbierz krystaliczną twardziel z dna gąszczu i elfi kamień ciosany z Ruin Shandaral.', 'Architekt krucjaty Silas w Dolinie Ech w Lodowej Koronie chce, żebyś $gzdobył:zdobyła; 10 pni krystalicznej twardzieli i 10 kawałków pradawnego elfiego kamienia ciosanego.', '', 'Wróć do architekta krucjaty Silasa w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13133, 'koKR', 'Odnajdź pradawnego bohatera', 'Szybko, $N, ruszaj na południowy zachód, do Sal Przodków!$B$BW środku znajdziesz śpiących Mjordinów. Budź ich, aż znajdziesz Iskaldera. Gdy go znajdziesz, użyj na nim tego amuletu i przyprowadź go do mnie.$B$BA teraz idź. Nie ma czasu do stracenia!', 'Kościana Wiedźma w Wiosce Njorndar chce, żebyś $gwrócił:wróciła; z Iskalderem.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', 'Iskalder dostarczony Kościanej Wiedźmie', '', '', '', 0),
(13134, 'koKR', 'Przelej ich krew', 'Plaga nie stworzy swoich potworów z ciała bez krwi i płynu do balsamowania, który konserwuje części i utrzymuje je w działaniu. Jeśli pozbawimy ją tych materiałów, jej armia się rozpadnie, a my z łatwością zniszczymy jej twory.$B$BW pracowniach, w których skleca się mięsne olbrzymy i plugastwa, znajdziesz kadzie z płynem do balsamowania i wielkie kule wypełnione krwią. Zniszcz je i nieś śmierć każdemu, kto spróbuje cię powstrzymać!', 'Mroczna jeźdźczyni Arly w Czarnej Straży chce, żebyś $gzniszczył:zniszczyła; 5 kadzi z płynem do balsamowania i 5 kul krwi.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Rozbite kule krwi', 'Zniszczone kadzie z płynem do balsamowania', '', '', 0),
(13135, 'koKR', 'To może nas wszystkich zabić', 'Na południowy wschód stąd, na wschodnich krańcach Lasu Kryształowej Pieśni, leży obszar zwany Wyzwolonym Gąszczem. W tym gąszczu pełza wszelkiego rodzaju życie. Wszystkie odmienione stworzenia z gąszczu łączy jedno: ciągnie je do magicznej energii. Każde z nich zawiera czystą, skrystalizowaną energię. Dość, by zabić nas wszystkich, gdyby kiedykolwiek się zdestabilizowała!$B$BUdaj się do Wyzwolonego Gąszczu i zabijaj jego mieszkańców dla skrystalizowanej energii. My potrzebujemy paliwa, a oni muszą zginąć. Nazywamy to „podwójną wygraną”.', 'Inżynier krucjaty Spitzpatrick w Dolinie Ech w Lodowej Koronie chce, żebyś $gzdobył:zdobyła; 8 porcji skrystalizowanej energii.', '', 'Wróć do inżyniera krucjaty Spitzpatricka w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13136, 'koKR', 'Poszarpane odłamki', 'Wyciągasz ten poszarpany, ciemny i kruchy odłamek z ciała ghula. Metalowe ostrze nie ma gładkiej krawędzi, co sugeruje, że wykuła je niewprawna ręka albo że zostało odłamane z większego kawałka.$B$BPrzypominasz sobie, że podobne odłamki tkwiły w ciałach wszystkich ghuli, które $gnapotkałeś:napotkałaś; w Mięsarni, i zastanawiasz się, po co ich twórcy w ogóle zadali sobie trud umieszczania w nich metalu. Może krzyżowiec Olakin Sainrith coś by na ten temat wiedział, gdybyś $gprzyniósł:przyniosła; mu odłamki z kilku ghuli.', 'Przynieś 10 poszarpanych odłamków krzyżowcowi Olakinowi Sainrithowi w Czarnej Straży.', '', 'Wróć do krzyżowca Olakina Sainritha w Czarnej Straży w Lodowej Koronie.', '', '', '', '', 0),
(13137, 'koKR', 'Niezbyt honorowa walka', 'Na szczycie najwyższej góry na południowym zachodzie, górującej nad Jotunheim, stoi Iglica Bitewnej Blizny. To miejsce czczone przez wrykulów – po Valhalas najchętniej toczą tam honorowe walki.$B$BMy stoczymy tam walkę niezbyt honorową.$B$BZbierz towarzyszy i leć na iglicę. Gdy będziesz $ggotów:gotowa;, rozpal ognisko sygnałowe, a ja pojawię się w ciele Iskaldera.$B$BBędziemy walczyć, ty wygrasz, a Vardmadra na pewno przybędzie, by obejrzeć bitwę!', 'Kościana Wiedźma w Wiosce Njorndar chce, żebyś $gpokonał:pokonała; Iskaldera na Iglicy Bitewnej Blizny.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', 'Iskalder pokonany w walce', '', '', '', 0),
(13138, 'koKR', 'Topię się... przetapiam!', '<Olakin obraca jeden z odłamków w opancerzonej pięści.>$B$BPrzy odpowiedniej sile mogłyby przebić pancerz. Musimy się dowiedzieć, z czego są zrobione i do czego Król Lisz zamierza ich użyć.$B$BNa wschodzie, tuż przy samej Cytadeli Lodowej Korony, leży Malykriss. Z nielicznych raportów, które mamy, wynika, że pełno tam sprzętu do wytapiania i kucia. Zanieś tam te odłamki i przetop je w jednym z otwartych pieców na najniższym poziomie Malykriss. Gdy metal zostanie przetopiony, będziemy mogli go zidentyfikować.', 'Użyj worka poszarpanych odłamków przy jednym z pieców na najniższym poziomie Malykriss. Wróć z wytopioną sztabką metalu do krzyżowca Olakina Sainritha w Czarnej Straży.', '', 'Wróć do krzyżowca Olakina Sainritha w Czarnej Straży w Lodowej Koronie.', '', '', '', '', 0),
(13139, 'koKR', 'W zamarznięte serce Północnej Grani', 'Silas i Spitzpatrick zatwierdzili materiały i paliwo potrzebne do rozpoczęcia budowy Twierdzy Sprawiedliwości. Dzięki tobie i Hebanowemu Mieczowi siły Plagi w Plagoholmie zostały zdziesiątkowane, a jej porucznicy – pokonani.$B$BWybrałem miejsce, w którym rozpoczniemy budowę, ale najpierw musisz dostarczyć mój raport najwyższemu lordowi Tirionowi Fordringowi. Na jego rozkaz rozpoczniemy marsz w głąb Lodowej Korony.$B', 'Dostarcz raport ojca Gustava najwyższemu lordowi Tirionowi Fordringowi w Awangardzie Argentu w Lodowej Koronie.$B', '', 'Wróć do najwyższego lorda Tiriona Fordringa w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13140, 'koKR', 'Kowale run z Malykriss', 'Odłamki, które $gzdobyłeś:zdobyłaś;, mogły pochodzić tylko z jednego miejsca – z Malykriss. To ośrodek obróbki metalu Króla Lisza, na wschód od Corp\'rethar.$B$BZastanawiające jest to, że metal nie jest potrzebny do zszywania plugastw czy mięsnych olbrzymów ani do przywoływania szkieletowych sług. Znajdź szkieletowych kowali run pracujących na najniższym poziomie Malykriss i zdobądź płyty, nad którymi pracują. Musimy się dowiedzieć, czemu ten metal trafia do Mięsarni.', 'Przynieś 5 runicznych płyt z saronitu krzyżowcowi Olakinowi Sainrithowi w Czarnej Straży.', '', 'Wróć do krzyżowca Olakina Sainritha w Czarnej Straży w Lodowej Koronie.', '', '', '', '', 0),
(13141, 'koKR', 'Bitwa o Szczyt Krzyżowców', '<Najwyższy lord Fordring trzyma sztandar Krucjaty Argentu.>$B$BTen sztandar nie ma sobie równych, $N. Niesie potężne błogosławieństwo, zdolne uświęcić rozległe połacie skażonej ziemi.$B$BMusisz zanieść go na północny zachód, przez Wyłom, w miejsce, które Plaga szyderczo nazwała Szczytem Krzyżowców. Zatknij sztandar na czaszkach naszych poległych braci na Szczycie Krzyżowców i broń go przed atakiem. Gdy ziemia zostanie uświęcona, wróć do ojca Gustava.$B$BIdź teraz, $N. Nie noś w sercu strachu.', 'Udaj się na Szczyt Krzyżowców i użyj błogosławionego sztandaru Krucjaty na stosie czaszek krzyżowców. Broń sztandaru przed atakiem Plagi, dopóki ziemia na szczycie nie zostanie uświęcona, a następnie wróć do ojca Gustava w Dolinie Ech w Lodowej Koronie.', 'Bitwa o Szczyt Krzyżowców', 'Wróć do ojca Gustava w Dolinie Ech w Lodowej Koronie.', '', '', '', '', 0),
(13142, 'koKR', 'Zemsta banshee', 'Nadszedł czas, $N. Ty i twoi przyjaciele musicie wyzwać pana Fortecy Balargarde, władcę Jotunheim, nadthana Balargarde.$B$BNa szczycie fortecy, która leży na południowo-zachodnim skraju Jotunheim, znajdziesz róg. Zadmij w niego. Niech twoje wyzwanie rozbrzmi w całej warowni.$B$BBalargarde nie będzie miał wyboru i będzie musiał stanąć do walki. A ja... wybacz, Vardmadra będzie tam, by rozstrzygnąć wyzwanie.$B$B<Opętana przez banshee wrykulka wybucha grzmiącym rechotem.>', 'Kościana Wiedźma w Wiosce Njorndar poprosiła cię, żebyś $gpomścił:pomściła; ją, wyzywając i pokonując nadthana Balargarde.', '', 'Wróć do Kościanej Wiedźmy w Wiosce Njorndar w Lodowej Koronie.', '', '', '', '', 0),
(13143, 'koKR', 'Nowy rekrut', 'Najpierw najważniejsze. Widziałem kilka zwinnych czyhaczy na blankach tuż na wschód od nas. Służyły nam, zanim zerwaliśmy z Arthasem, i to niemal idealni zwiadowcy... jeśli trochę ich przycisnąć okiem panowania.$B$BLeć tam, znajdź jednego z czyhaczy, trochę go obij, a potem użyj tego symbolu Hebanowego Miecza, by zmusić go do posłuszeństwa. Rozpozna symbol, gwarantuję. Zaprowadź go na szczyt skał na północny wschód stąd, a sam znajdzie drogę do mnie.', 'Vereth Przebiegły na Wzniesieniu Cierpienia poprosił cię, żebyś $gprzyprowadził:przyprowadziła; ujarzmionego zwinnego czyhacza na szczyt skał na północny wschód od Wzniesienia Cierpienia.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', 'Ujarzmiony zwinny czyhacz przyprowadzony', '', '', '', 0),
(13144, 'koKR', 'Dwie pieczenie przy jednym szkielecie', 'Robotnicy w pracowni plugastw w Mięsarni ukończyli już kilka swoich tworów. Na razie te stwory są przykute łańcuchami do filarów na skraju pracowni, ale jeśli nic nie zrobimy, wyruszą z armiami Króla Lisza.$B$BZ kupek kości rozrzuconych po całej Mięsarni wystają chwytające ramiona. Należą do szkieletów zaklętych mocą ognia. Znajdź i uwolnij te szkielety, a potem zaprowadź je do ukończonych plugastw i podziwiaj przedstawienie!', 'Mroczna jeźdźczyni Arly w Czarnej Straży chce, żebyś za pomocą płonących szkieletów $gzniszczył:zniszczyła; 3 skute plugastwa.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Spalone skute plugastwa', '', '', '', 0),
(13145, 'koKR', 'Plugawa Warownia', 'Musimy wiedzieć, z czym się mierzymy.$B$BUżyj oka panowania, by przejąć kontrolę nad zwinnym czyhaczem i przeszpiegować okolicę. Lecąc tutaj, dostrzegłem kilka miejsc, którym masz się przyjrzeć z bliska: punkt obserwacyjny na północnym wschodzie, strefę robót na południowym wschodzie, wielką kuźnię pośrodku i miejsce rytuałów na południowym zachodzie.$B$BCzyhacz potrafi daleko skakać, a upadki z dużej wysokości nie robią mu krzywdy – wykorzystaj to, by wspinać się na blanki i z nich zeskakiwać.', 'Vereth Przebiegły na Wzniesieniu Cierpienia poprosił cię, żebyś za pomocą zwinnego czyhacza $gprzeszpiegował:przeszpiegowała; Malykriss.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', 'Ołtarz Ofiarny zbadany', 'Krwawa Kuźnia zbadana', 'Lodowa Strażnica zbadana', 'Warsztat Run zbadany', 0),
(13146, 'koKR', 'Hojność bez granic', 'Musimy narobić trochę zamieszania... czegokolwiek, co odciągnie tych rycerzy śmierci od przywódców. Jeśli zdziesiątkujemy ich sługi na dole, podejrzewam, że będą musieli poświęcić więcej uwagi pilnowaniu robót.$B$BPlugastwa to łatwa zdobycz – powolne, przewidywalne, a przede wszystkim głupie. Wykorzystaj to, że ufają czyhaczom, i przyciągnij im kilka bomb Plagi rozrzuconych po terenie budowy. Zdążysz podpalić bomby na długo, zanim się zorientują, co się dzieje.', 'Vereth Przebiegły chce, żebyś za pomocą żelaznego łańcucha zwinnego czyhacza $gprzyciągnął:przyciągnęła; bomby Plagi do 4 ociężałych okropności w Malykriss.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', 'Prezent w postaci bomby Plagi dostarczony', '', '', '', 0),
(13147, 'koKR', 'Swat', 'Główna różnica między wargulami a pomniejszymi nieumarłymi sługami polega na tym, że wargule zachowali dość rozumu, by nienawidzić pracy, do której się ich zmusza. Wargul nigdy nie będzie zadowolony z pracy u boku szkieletów czy ghuli.$B$BWykorzystajmy tę nieuniknioną wrogość i wywołajmy kilka bójek między mrocznymi osiłkami a innymi nieumarłymi w Malykriss. To powinno spowolnić produkcję i ściągnąć rycerzy śmierci na dół, żeby niańczyli towarzystwo.$B$BTo powinno być proste – rzucaj kamieniami w osiłki, gdy zbliżą się do pomniejszych nieumarłych.', 'Vereth Przebiegły na Wzniesieniu Cierpienia chce, żebyś za pomocą zwinnego czyhacza $grzucał:rzucała; kamieniami w mroczne osiłki, gdy zbliżą się do pomniejszych nieumarłych w Malykriss. Wróć, gdy wywołasz 5 bójek.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', 'Bójka robotników wywołana', '', '', '', 0),
(13152, 'koKR', 'Wizyta u doktora', 'Więc w Sanktuarium Reanimacji wszczepiają tym ghulom połamane odłamki saronitu? Musimy to powstrzymać, zanim te ghule zostaną rzucone przeciwko naszym oddziałom.$B$BZnajdź wejście do Sanktuarium Reanimacji w tej części Mięsarni, gdzie stoi pracownia mięsnych olbrzymów. Tam ghul i zbrodniczy geniusz, doktor Sabnok, trzyma najstraszliwsze ze swoich dzieł – Łatka. Uwolnij Łatka z łańcuchów i pomóż mu zemścić się na doktorze. Niech zgubi go własne dzieło.', 'Mroczna jeźdźczyni Arly w Czarnej Straży chce, żebyś $gzniszczył:zniszczyła; metalowy pal więżący Łatka w Sanktuarium Reanimacji i $gpomógł:pomogła; mu zemścić się na doktorze Sabnoku.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Łatek uwolniony', 'Pomóż Łatkowi zabić doktora Sabnoka', '', '', 0),
(13155, 'koKR', 'Vereth Przebiegły', 'Słyszałem już pogłoski o Malykriss i nowym zakonie rycerzy śmierci Arthasa, ale sądziłem, że chodzi tylko o zapełnienie luki. Te liczby sugerują jednak, że Arthas próbuje pójść o krok dalej.$B$BNiedawno wysłaliśmy do Malykriss jednego z naszych najlepszych – Veretha Przebiegłego. Znajdziesz go na Wzniesieniu Cierpienia, tuż na zachód od Malykriss, w obrębie Dziedzińca Kości.$B$BStaraj się nie zwracać na siebie zbytniej uwagi po drodze.', 'Zamelduj się u Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13157, 'koKR', 'Szczyt Krzyżowców', 'Bądź $gdumny:dumna; – to ty $gpomogłeś:pomogłaś; Krucjacie Argentu zadomowić się w murach Lodowej Korony, $N. Szczyt Krzyżowców stoi teraz na przekór Królowi Liszowi i jego wypaczonym sługom.$B$BNajwyższy lord Fordring i krzyżowcy, którzy przeżyli, czekają na ciebie na Szczycie Krzyżowców. Przejdź raz jeszcze przez Wyłom i odszukaj najwyższego lorda!', 'Odszukaj najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13160, 'koKR', 'Oszałamiający widok', 'Gargulce to skuteczni zwiadowcy i potrafią być zabójcze, jeśli pozwoli się im atakować z powietrza, ale mają bardzo oczywistą słabość. Większość z nich musi długo odpoczywać w postaci kamienia, by zachować energię potrzebną do noszenia ciężkich cielsk w powietrzu.$B$BGdy patrzyłem przez oko, którego $gużywałeś:używałaś;, zauważyłem dziesiątki wartowników lodowej skóry odpoczywających w środku, na wschodnich i południowych murach. Użyj czyhacza, by wskoczyć na ich półki, i zmiażdż ich, gdy śpią.', 'Vereth Przebiegły na Wzniesieniu Cierpienia chce, żebyś za pomocą zdolności Dźwignięcie zwinnego czyhacza $gzniszczył:zniszczyła; 12 śpiących wartowników lodowej skóry.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', 'Wartownik lodowej skóry zniszczony', '', '', '', 0),
(13161, 'koKR', 'Jeździec Bezbożności', 'Czas zacząć ścinać łby bestii.$B$BSłużyłem u boku Rokira przez dość długi czas. Zna bezbożne sztuki lepiej niż niemal każdy inny rycerz śmierci, jakiego spotkałem, i jest równie bezwzględny.$B$BSiła Rokira ujawnia się najbardziej, gdy walczysz z nim na jego terenie. Niestety, nie mamy tu dużego wyboru, ale nie stój w miejscu, unikaj jego nieumarłych sług, a wyjdziesz z tego zwycięsko.$B$BBądź $gzwinny:zwinna;, $N, i nie lekceważ go.', 'Vereth Przebiegły na Wzniesieniu Cierpienia chce, żebyś $gzabił:zabiła; Rokira, Jeźdźca Bezbożności.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', '', '', '', '', 0),
(13162, 'koKR', 'Jeźdźczyni Mrozu', 'Sapph... Sapph to rycerz śmierci jak żaden inny. Obsypie cię słodkimi słówkami i $gprzysiągłbyś:przysięgłabyś;, że w jej sercu nie ma ani krzty zła, a potem przebije cię na wylot, nawet nie przestając się uśmiechać.$B$BNie obawiam się, że nie zdołasz pokonać Sapph, ale nie popadaj w zbytnią pewność siebie. Jej siła polega na usypianiu czujności ofiar, tuż zanim roztrzaska je gwałtownym gradem mroźnych ataków.$B$BNie trać czujności i nie lekceważ jej.', 'Vereth Przebiegły na Wzniesieniu Cierpienia chce, żebyś $gzabił:zabiła; Sapph, Jeźdźczynię Mrozu.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', '', '', '', '', 0),
(13163, 'koKR', 'Jeździec Krwi', 'Baelok to jeden z nielicznych wrykulów, jakich widziałem, którzy awansowali w szeregach, a osiągnął to głównie dzięki czystej brutalności. Kiedy konkurencja kończy martwa, rywali jest znacznie mniej.$B$BGdy staniesz z nim do walki, rozproszcie się z towarzyszami i trzymaj się od niego tak daleko, jak to rozsądnie możliwe. Nie zawaha się ukraść twojej siły życiowej, więc musisz jak najbardziej mu to utrudnić.$B$BUfam ci. Dopilnuj, żeby zginął.', 'Vereth Przebiegły na Wzniesieniu Cierpienia chce, żebyś $gzabił:zabiła; Baeloka, Jeźdźca Krwi.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', '', '', '', '', 0),
(13164, 'koKR', 'Los Krwawej Zguby', 'Skoro jeźdźcy Zastępu Męki nie żyją, czas położyć kres ich prawdziwemu przywódcy: Orbazowi Krwawej Zgubie.$B$BGdy cię nie było, dogonił mnie Mograine i powiedział, że odkrył, gdzie ukrywa się Orbaz. Pod samą Cytadelą Lodowej Korony jest ogromna czeluść – Orbaza znajdziesz tuż przy jej krawędzi.$B$BWysłano już kilku najsilniejszych agentów Hebanowego Miecza – zbierz pomoc i dołącz do walki. Czas, by Krwawa Zguba zginął.', 'Vereth na Wzniesieniu Cierpienia wysłał cię, żebyś $gzabił:zabiła; Orbaza Krwawą Zgubę.', '', 'Wróć do Veretha Przebiegłego na Wzniesieniu Cierpienia w Lodowej Koronie.', '', '', '', '', 0),
(13168, 'koKR', 'Prezenty na pożegnanie', 'Spójrz, co tu mamy... oczy panowania. Kult zwykle zadaje sobie wiele trudu, żeby trzymać je w bezpiecznym miejscu, ale chyba nie mają gdzie się wycofać, skoro wyrzynamy ich we własnym domu.$B$BOczy pozwalają istocie o choćby umiarkowanej mocy precyzyjnie kierować poczynaniami nieumarłego sługi. Jak się domyślasz, to niezwykle przydatne w przypadku typowego niezdarnego ghula czy szkieletu.$B$BChcesz spróbować? Użyj jednego z oczu, żeby przejąć kontrolę nad schwytanym cieniem.', 'Keritose Krwawe Ostrze w Krypcie Cienia chce, żebyś $gużył:użyła; Oka Panowania, by przejąć kontrolę nad schwytanym strażnikiem eidolonów.', 'Przejmij kontrolę nad strażnikiem eidolonów', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', '', '', '', '', 0),
(13169, 'koKR', 'Najlepszy przyjaciel nieumarłego', 'Nieumarli w kamieniołomie saronitu na południowym zachodzie, jak to mają w zwyczaju, głodzą plagowe ogary, żeby były jeszcze bardziej agresywne. Użyj cienia, by podejść blisko i nakarmić kilka tych ogarów, a obiecuję ci, że chętnie zostawią cię w spokoju, jeśli nie staną po stronie ręki, która je karmiła.$B$BTylko nie podchodź do tych bestii za blisko, zanim ich nie nakarmisz. Ich nosów nie zmyli nieuchwytność twojego cienia.', 'Keritose Krwawe Ostrze w Krypcie Cienia chce, żebyś za pomocą strażnika eidolonów $gnakarmił:nakarmiła; 18 nienasyconych plagowych ogarów.', '', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', 'Nakarmione nienasycone plagowe ogary', '', '', '', 0),
(13170, 'koKR', 'Honor jest dla słabych', 'Ghule to w gruncie rzeczy kruche stwory i czujki w kamieniołomie saronitu w dole ścieżki na południowym zachodzie nie są wyjątkiem. Nie wątpię, że z pomocą jednego z cieni zdołasz się do nich podkraść i bezgłośnie je wykończyć.$B$BUsuń tyle czujek, do ilu zdołasz dotrzeć w rozsądnym czasie... przed naszym szturmem chcemy przerzedzić ich szeregi.', 'Keritose Krwawe Ostrze w Krypcie Cienia chce, żebyś $gzabił:zabiła; skrytobójczo 20 niespokojnych czujek.', '', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', 'Niespokojne czujki zabite skrytobójczo', '', '', '', 0),
(13171, 'koKR', 'Skąd przybyli', 'Najbardziej niepokoi mnie kamieniołom saronitu w dole ścieżki na południowym zachodzie. Wydobywają z niego ogromne ilości rudy i chciałbym wiedzieć, co z niej budują. W tym celu zaczniemy od osłabienia ich obrony.$B$BZauważyłem kryształy rozrzucone po całej bazie i zakładam, że to jakieś konstrukcje obronne, podobne do zigguratów. Użyj strażnika eidolonów, żeby zniszczyć wszystkie kryształy, jakie znajdziesz.', 'Keritose Krwawe Ostrze w Krypcie Cienia wysłał cię, żebyś $gwygnał:wygnała; 10 kryształów izolujących Plagi.', '', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', 'Wygnane kryształy Plagi', '', '', '', 0),
(13172, 'koKR', 'Ziarna chaosu', 'Skuteczne narzędzie, prawda? Świetnie ci poszło osłabianie ich obrony, $N. Teraz możemy ruszyć do głównego szturmu.$B$BPlan jest prosty – niszczymy wszystko, co się rusza, a w ogólnym zamęcie wchodzimy do środka i wykradamy trochę informacji.$B$BDaj znać, kiedy będziesz $ggotów:gotowa;, a załatwię ci szkieletowego gryfa.', 'Keritose Krwawe Ostrze w Krypcie Cienia wysłał cię, żebyś $gwyrżnął:wyrżnęła; 80 nieumarłych w Płaczącym Kamieniołomie. Porozmawiaj z nim, żeby dostać szkieletowego gryfa do szturmu.', '', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', 'Wyrżnięci nieumarli z Płaczącego Kamieniołomu', '', '', '', 0),
(13173, 'koKR', 'W ogólnym zamęcie', 'Dorwaliśmy sporo robotników. Doskonale się nadadzą.$B$BChcę, żebyś za pomocą oka $gzaprowadził:zaprowadziła; jednego z nich z powrotem do kamieniołomu. Skoro w całym obozie panuje chaos, nie ma mowy, żeby odróżnili cię od innych robotników rozproszonych przez szturm.$B$BZnajdź tego, kto kieruje robotami, i bierz się do pracy. Przy odrobinie szczęścia szybko się dowiemy, dokąd wysyłają ten saronit. Będę ci zaglądał przez ramię przez oko.', '', '', '', '', '', '', '', 0),
(13174, 'koKR', 'W ogólnym zamęcie', 'Wstrzymanie ich robót to tylko połowa planu. Drugim ważnym celem jest ustalenie, dokąd trafia cały ten saronit. Znamy kilka miejsc, do których dociera, ale ilości, które wydobywają, podpowiadają mi, że szykuje się jakiś większy projekt.$B$BKiedy już znajdziesz się w kamieniołomie, zdobądź wszystkie ich dokumenty, jakie znajdziesz. Jeśli atakujesz to miejsce na jednym z gryfów, możesz z niego zeskoczyć, gdy tylko brudna robota będzie skończona.', 'Keritose Krwawe Ostrze w Krypcie Cienia poprosił o dokument z Płaczącego Kamieniołomu, księgę rachunkową Płaczącego Kamieniołomu, mapę Płaczącego Kamieniołomu i harmonogram Płaczącego Kamieniołomu.', '', 'Wróć do Keritose\'a Krwawego Ostrza w Krypcie Cienia w Lodowej Koronie.', '', '', '', '', 0),
(13175, 'koKR', 'Odzyskanie kontroli', '', '', '', '', '', '', '', '', 0),
(13176, 'koKR', 'Przygotowanie dostawy', '', '', '', '', '', '', '', '', 0),
(13184, 'koKR', 'Przydatność się skończyła', '', '', '', '', '', '', '', '', 0),
(13211, 'koKR', 'Niech oczyści ich ogień', 'Plaga wykorzystuje przeciwko nam naszych własnych poległych – wskrzesza ich jako ghule lub szkielety albo ćwiartuje ich zwłoki i z części składa plugastwa. To musi się skończyć!$B$BZmarli to bohaterowie, którzy polegli w obronie wszystkich żywych, i nie wolno skazywać ich na tak makabryczny los. Co więcej, nie możemy sobie pozwolić na to, by znów stanąć z nimi na polu bitwy, gdy zostaną użyci przeciwko nam jako broń. Zabierz tę pochodnię do Mięsarni i spal wszystkie zwłoki, jakie znajdziesz w Sanktuarium Reanimacji albo w pracowni plugastw.', 'Krzyżowiec Olakin Sainrith w Czarnej Straży chce, żebyś za pomocą pochodni Olakina $gspalił:spaliła; 7 ropiejących zwłok.', '', 'Wróć do krzyżowca Olakina Sainritha w Czarnej Straży w Lodowej Koronie.', 'Spalone ropiejące zwłoki', '', '', '', 0),
(13212, 'koKR', 'Rozsypał się', 'Po porwaniu krzyżowca Olakina siły Krucjaty Argentu nie będą miały dowódcy w ostatecznym szturmie na Mięsarnię. Dla mnie jeden krzyżowiec jest wart tyle co inny, ale argentczycy nie spojrzą na to w ten sposób.$B$BNie znoszę marnować czasu na takie pościgi, ale nie mam wyboru. Nasz dzielny krzyżowiec został już pewnie poćwiartowany, a jego szczątki posłużyły do budowy plugastw. Zejdź do Mięsarni, zabij korpulentne poczwary walczące z naszymi siłami i odzyskaj części ciała Olakina.', 'Odzyskaj tors Olakina, nogi Olakina, lewą rękę Olakina i prawą rękę Olakina, a następnie przynieś je mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', '', '', '', '', 0),
(13213, 'koKR', 'Bitwa w Valhalas', 'Widzę i słyszę wiele rzeczy, $N, a od czasu, gdy $gpokonałeś:pokonałaś; nadthana Balargarde, wydarzyło się coś bardzo ważnego: wzywają cię do walki w Valhalas!$B$BArenę znajdziesz na północy. Idź teraz z przyjaciółmi i porozmawiaj z val\'kyrią Geirrvif. Przeciwnicy, których wystawi wam w Valhalas, z pewnością będą wymagali ich pomocy.$B$BPowodzenia.', 'Porozmawiaj z Geirrvif w Valhalas.', '', '', '', '', '', '', 0),
(13214, 'koKR', 'Bitwa w Valhalas: Polegli bohaterowie', 'Jeśli uważasz, że możesz zaczynać, mam dla ciebie w sam raz walkę na początek.$B$BInna grupa obcych sądziła, że jest gotowa na trudy Valhalas. Mieli w sobie mnóstwo pychy, ale w końcu padli jak wszyscy inni.$B$BJeśli uważacie, że jesteście inni – jeśli sądzicie, że macie umiejętności i doświadczenie, by walczyć tu pośród tak sławnych wojowników – przyjmijcie wyzwanie.', 'Geirrvif w Valhalas wyzwała cię, żebyś w jednej walce $gpokonał:pokonała; wszystkich sześciu poległych bohaterów: Eldretha, Genessa Półduszę, Jhadrasa, Masuda, Ritha i Tallę.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Polegli bohaterowie pokonani', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13215, 'koKR', 'Bitwa w Valhalas: Khit\'rix Mroczny Mistrz', 'Do Valhalas przybywają z całego świata najróżniejsze istoty, by się wykazać. Niektóre przychodzą nawet spod ziemi.$B$BJedną z nich jest Khit\'rix Mroczny Mistrz.$B$BKhit\'rix pochodzi z głębin, gdzie panuje obłęd, i zażądał na ringu jakiegoś egzotycznego przeciwnika. Nadasz się.$B$BOdważysz się stanąć do walki z tym nerubiańskim koszmarem, $N?', 'Geirrvif w Valhalas wyzwała cię, żebyś $gpokonał:pokonała; Khit\'rixa Mrocznego Mistrza.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Khit\'rix Mroczny Mistrz pokonany', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13216, 'koKR', 'Bitwa w Valhalas: Powrót Sigrid Zrodzonej z Lodu', 'Wrócił twój dawny wróg: Sigrid Zrodzona z Lodu. Może pamiętasz, jak $gpokonałeś:pokonałaś; ją w pojedynku na Dzikim Występie?$B$BNieważne, ona z pewnością pamięta ciebie. Domaga się szansy, by raz jeszcze się wykazać.$B$BMoim zdaniem to raczej szansa na zemstę, ale i to może się w tym miejscu przydać.$B$BZostawiam to tobie, $N. Zmierzysz się jeszcze raz z Sigrid Zrodzoną z Lodu?', 'Geirrvif w Valhalas wyzwała cię, żebyś $gpokonał:pokonała; Sigrid Zrodzoną z Lodu.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Sigrid Zrodzona z Lodu pokonana', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13217, 'koKR', 'Bitwa w Valhalas: Jatka!', 'Do tej pory odnosisz sukcesy, $N, ale żeby dalej walczyć w Valhalas, musisz stawić czoła gigantycznej grozie, która przekracza wszelkie wyobrażenie.$B$BMuszę cię ostrzec: zawróć teraz. Jatka to góra mięsa złożona przez najbardziej diabelskie umysły na usługach Króla Lisza.$B$BNie widzę, jak ty i twoi przyjaciele mielibyście ją pokonać. Wybór należy jednak do ciebie.', 'Geirrvif w Valhalas wyzwała cię, żebyś $gpokonał:pokonała; Jatkę.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Jatka pokonana', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13218, 'koKR', 'Bitwa w Valhalas: Than Cios Śmierci', 'Twoje umiejętności nie uszły uwagi wrykuli z Jotunheim, $N. Than Banahogg osobiście się tobą zainteresował i nalega, by to on był twoim następnym przeciwnikiem.$B$BJeśli Jatka wydawała ci się straszna, to może lepiej wracaj do domu. Than Banahogg nosi przydomek Cios Śmierci. Chyba się domyślasz, czym na niego zasłużył.$B$BPrzyjmujesz wyzwanie thana?', 'Geirrvif w Valhalas wyzwała cię, żebyś $gpokonał:pokonała; thana Banahogga, zwanego Ciosem Śmierci.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Than Banahogg pokonany', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13219, 'koKR', 'Bitwa w Valhalas: Ostateczne wyzwanie', 'Obawiam się, że twój sukces stanie się twoją zgubą, $N.$B$B<Gdyby val\'kyria mogła zblednąć jeszcze bardziej, z pewnością by to zrobiła.>$B$BWieści o twoich zwycięstwach w Valhalas dotarły w głąb Cytadeli Lodowej Korony i poruszyły kogoś, kogo wcale nie chcesz spotkać.$B$BSam książę Sandoval jest właśnie w drodze. Gjonner ostrzegał cię, że trzeba uciekać, i nie mogę się z nim nie zgodzić.$B$BCo zrobisz? On już nadchodzi. Staniesz do ostatecznej walki z księciem krwi?', 'Geirrvif w Valhalas wyzwała cię, żebyś $gpokonał:pokonała; księcia Sandovala.$B$BJeśli ci się uda, porozmawiaj z Gjonnerem Bezlitosnym, który spogląda z południowej krawędzi Valhalas.', 'Książę Sandoval pokonany', 'Wróć do Gjonnera Bezlitosnego w Valhalas w Lodowej Koronie.', '', '', '', '', 0),
(13220, 'koKR', 'Składanie Olakina do kupy', 'Nie możemy marnować czasu na składanie Olakina. Na szczęście Plaga zapewniła idealne miejsce, gdzie możesz go z powrotem pozszywać.$B$BW pobliżu pracowni mięsnych olbrzymów w Mięsarni znajduje się Sanktuarium Reanimacji. Przeszukaj okolicę i znajdź szpulkę nici oraz tasak doktora. Potem zanieś szczątki Olakina na dużą płytę pośrodku sanktuarium i bierz się do roboty.', 'Zdobądź szpulkę nici i tasak doktora, a następnie zanieś je do płyty w Sanktuarium Reanimacji i użyj szczątków Olakina, by spróbować przywrócić krzyżowca do życia. Gdy skończysz, wróć do mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', 'Krzyżowiec Olakin Sainrith przywrócony do życia', '', '', '', 0),
(13221, 'koKR', 'Jeszcze nie umarłem!', 'Światłość mi sprzyja. Jeszcze nie zginąłem w tym żywym koszmarze, ale jeśli nie zdołam uciec, Plaga mnie zabije i rozerwie moje ciało na części do swojej tutejszej „pracy”.$B$BSam nie dam rady, moje dziecko, ale z twoją pomocą może jeszcze dożyję dnia, gdy znów będę walczyć z Plagą.$B$BPomożesz mi uciec, zanim rzeźnicy Plagi przyjdą mnie dobić?', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce, a następnie złóż raport Absalanowi Pobożnemu na pokładzie Niebołamacza.', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce', 'Złóż raport Absalanowi Pobożnemu na pokładzie Niebołamacza w Lodowej Koronie.', '', '', '', '', 0),
(13224, 'koKR', 'Młot Orgrima', 'Krucjata Argentu wyciągnęła moje zmasakrowane ciało ze Złamanego Frontu. Co za wspaniała bitwa, $N. Mój topór śpiewał, siekąc i plugawe Przymierze, i Plagę.$B$BMój czas się skończył. To będzie dobra śmierć. Zanieś wiadomość ode mnie, żołnierzu.$B$BNasza baza lata poza zasięgiem Plagi – wysoko między Mord\'rethar i Aldur\'thar. Nazywa się „Młot Orgrima”.$B$B<Hork na próżno próbuje zasalutować.>$B$BLeć wysoko i omijaj kolosa Przymierza, Niebołamacz. Powiedz Kormowi... powiedz mu, że zginąłem... walcząc... Za Hordę.', 'Odszukaj podniebnego grabieżcę Korma Czarną Bliznę na pokładzie Młota Orgrima, który lata nad Lodową Koroną.', '', '', '', '', '', '', 0),
(13225, 'koKR', 'Niebołamacz', 'Tonęliśmy po szyję w Pladze i Hordzie. Krzyki umierających niosły się nad całym polem. To była męczarnia... bez chwili wytchnienia!$B$BW pewnej chwili moje ciało odmówiło posłuszeństwa. Upadłem, a ocknąłem się dopiero dzięki Krucjacie Argentu. Wyciągnęli mnie ze Złamanego Frontu i przynieśli tutaj. Nie przeżyję tego. Spełnisz ostatnie życzenie umierającego żołnierza, $N? Nasza baza, Niebołamacz, lata wysoko nad Lodową Koroną. Znajdziesz tam mojego dowódcę, wielkiego kapitana Bartletta. Powiedz mu, że zginąłem jako żołnierz Przymierza.', 'Odszukaj wielkiego kapitana Justina Bartletta na pokładzie Niebołamacza, który lata nad Lodową Koroną.', '', '', '', '', '', '', 0),
(13226, 'koKR', 'Nadchodzi dzień sądu!', 'Sami nie pokonamy Króla Lisza. Podzieleni wszyscy upadniemy!$B$BBłagam cię, odpowiedz na wezwanie, $gbracie:siostro;. Krucjata Argentu przyjmuje każdego, kto zechce wesprzeć wysiłek wojenny. Sam najwyższy lord Tirion Fordring czeka na ciebie w Awangardzie Argentu! Dosiądź wierzchowca i leć na południowo-wschodnie krańce Lodowej Korony. Tam znajdziesz lorda Fordringa i żołnierzy Krucjaty Argentu.$B$BIdź już, $N, bo nadchodzi dzień sądu!', 'Zgłoś się do najwyższego lorda Tiriona Fordringa w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13227, 'koKR', 'Nadchodzi dzień sądu!', 'Sami nie pokonamy Króla Lisza. Podzieleni wszyscy upadniemy!$B$BBłagam cię, odpowiedz na wezwanie, $gbracie:siostro;. Krucjata Argentu przyjmuje każdego, kto zechce wesprzeć wysiłek wojenny. Sam najwyższy lord Tirion Fordring czeka na ciebie w Awangardzie Argentu! Dosiądź wierzchowca i leć na południowo-wschodnie krańce Lodowej Korony. Tam znajdziesz lorda Fordringa i żołnierzy Krucjaty Argentu.$B$BIdź już, $N, bo nadchodzi dzień sądu!', 'Zgłoś się do najwyższego lorda Tiriona Fordringa w Awangardzie Argentu w Lodowej Koronie.', '', '', '', '', '', '', 0),
(13228, 'koKR', 'Złamany Front', 'Jaka bitwa?! Ci żołnierze byli na zwiadzie!$b$bI co to za gadanie o Przymierzu – na pewno powiedział „Przymierze”?$b$bSłuchaj mnie, $n! Muszę wiedzieć, co się dzieje, i to NATYCHMIAST!$b$bLeć tam na dół i zdobądź dla mnie jakieś odpowiedzi! Przeczesz pole bitwy i szukaj ocalałych – śladów – czegokolwiek!', 'Korm Czarna Blizna na Młocie Orgrima chce, żebyś $gudał:udała; się na Złamany Front i $gprzesłuchał:przesłuchała; umierającego berserkera, by ustalić, co się tam wydarzyło.', '', 'Wróć do podniebnego grabieżcy Korma Czarnej Blizny na Młocie Orgrima w Lodowej Koronie.', 'Umierający berserker przesłuchany', '', '', '', 0),
(13229, 'koKR', 'Jeszcze nie umarłem!', 'Światłość mi sprzyja. Jeszcze nie zginąłem w tym żywym koszmarze, ale jeśli nie zdołam uciec, Plaga mnie zabije i rozerwie moje ciało na części do swojej tutejszej „pracy”.$B$BSam nie dam rady, $N, ale z twoją pomocą może jeszcze dożyję dnia, gdy znów będę walczyć z Plagą.$B$BPomożesz mi uciec, zanim rzeźnicy Plagi przyjdą mnie dobić?', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce, a następnie złóż raport bratu Keltanowi na pokładzie Młota Orgrima.', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce', 'Złóż raport bratu Keltanowi na pokładzie Młota Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13230, 'koKR', 'Pomścij mnie!', 'Słyszę ich, $gbracie:siostro;...$b$bJęki rannych z Przymierza... drwią ze mnie...$b$bDokończ to, co tu zaczęliśmy, $N. Nie okazuj litości... niech żaden z nich nie przeżyje.$b$bZa... Hordę...', 'Umierający berserker poprosił, żebyś $gzabił:zabiła; 5 umierających żołnierzy na Złamanym Froncie. Gdy to zrobisz, złóż raport podniebnemu grabieżcy Kormowi Czarnej Bliźnie na Młocie Orgrima.', '', 'Wróć do podniebnego grabieżcy Korma Czarnej Blizny na Młocie Orgrima w Lodowej Koronie.', 'Zabici umierający żołnierze Przymierza', '', '', '', 0),
(13231, 'koKR', 'Złamany Front', 'Co?! Nieee!$b$bTak bardzo się staraliśmy, żeby utrzymać ten atak w tajemnicy. Skąd Horda mogła wiedzieć? Zasoby... ludzie... wszystko stracone? Nie do pojęcia!$b$bNasze plany tu, w Lodowej Koronie, zależały od tego, czy zdobędziemy tę bramę przed Hordą. Musimy szybko dojść do siebie i przygotować kolejną ofensywę.$b$bUdaj się na pole bitwy i poszukaj ocalałych. Sprawdź, czy z tej tragedii da się wyciągnąć jakąś naukę.$b$bI przygotuj się, $n, na wojnę – na dwóch frontach...', 'Wielki kapitan Justin Bartlett na pokładzie Niebołamacza chce, żebyś $gudał:udała; się na Złamany Front, $gprzesłuchał:przesłuchała; umierającego żołnierza, a następnie $gzłożył:złożyła; mu raport.', '', 'Wróć do wielkiego kapitana Justina Bartletta na Niebołamaczu w Lodowej Koronie.', 'Umierający żołnierz przesłuchany', '', '', '', 0),
(13232, 'koKR', 'Dobij mnie!', 'Drwią z nas – nawet gdy sami tu konają...$b$bProszę, $gbracie:panienko;... Nie pozwól, żeby ich szyderstwa były ostatnim, co usłyszę...$b$bDobij mnie... wybaw mnie od tej męki... ku... Światłości.$b$bOdszukaj moich towarzyszy... okaż im tę samą łaskę.$b$bNie zostawiaj Pladze nikogo do wskrzeszenia!$b$bBłagam cię...', 'Umierający żołnierz na Złamanym Froncie chce, żebyś $gzabił:zabiła; 5 umierających żołnierzy i $gzłożył:złożyła; raport wielkiemu kapitanowi Justinowi Bartlettowi na Niebołamaczu.', '', 'Wróć do wielkiego kapitana Justina Bartletta na Niebołamaczu w Lodowej Koronie.', 'Zabici umierający żołnierze', '', '', '', 0),
(13233, 'koKR', 'Bez litości!', 'Jest tak, jak ci mówiłem. To nie były czcze słowa rzucone w przypływie gniewu.$b$bHorda raz po raz okazywała pogardę dla wszystkiego, co jest nam drogie i święte. Za swoje występki przeciw Światłości muszą zapłacić życiem.$b$bWszyscy.$b$bWyobraź sobie świat wolny od ich skazy, $n. Wyobraź sobie radość, jaką poznają nasze dzieci. Pomyśl, z jaką czcią twoi potomkowie będą wspominać ciebie, wiedząc, że to tobie zawdzięczają swoje szczęście.$b$bA teraz idź i spraw, by ta wizja stała się rzeczywistością!', 'Wielki kapitan Justin Bartlett na pokładzie Niebołamacza chce, żebyś $gzabił:zabiła; 15 graczy Hordy w Lodowej Koronie.', '', 'Wróć do wielkiego kapitana Justina Bartletta na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13234, 'koKR', 'Niech zapłacą!', 'Nadszedł czas!$b$bZbyt długo znosiliśmy towarzystwo zadufanego Przymierza! Zbyt długo powstrzymywaliśmy rękę przed oczyszczeniem naszego świata ze słabych i zdesperowanych.$b$bTeraz kładziemy kres naszemu upokorzeniu! Teraz pokażemy im, czym jest prawdziwy strach! Teraz przyniesiemy Hordzie chwałę!$b$bTu, w Lodowej Koronie, złamiemy Przymierze!$b$bIdź, $N. Wytrop ich. Złam ich. Odbierz im wolę życia!', 'Podniebny grabieżca Korm Czarna Blizna chce, żebyś $gzabił:zabiła; 15 graczy Przymierza w Lodowej Koronie.', '', 'Wróć do podniebnego grabieżcy Korma Czarnej Blizny na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13235, 'koKR', 'Czempion mięsnych olbrzymów', 'Dobrze ci poszło niszczenie Mięsarni i wyrzynanie sług Króla Lisza. Teraz zostało już tylko pokonać największe osiągnięcie Mięsarni – mięsnego olbrzyma zwanego Morbidusem.$B$BTo nie będzie łatwa walka, ale Krypta Cienia wysłała margrabiego Dhakara z posiłkami. Spotkaj się z nim w najwyższym punkcie na zachodnim krańcu Mięsarni. Powiedz mu, kiedy będziesz $ggotów:gotowa; do ataku, a rozkaże swoim siłom ruszyć do boju.', 'Porozmawiaj z margrabią Dhakarem na zachodnim krańcu Mięsarni, by zaatakować Morbidusa. Gdy go pokonasz, złóż raport mrocznej jeźdźczyni Arly w Czarnej Straży.', '', 'Wróć do mrocznej jeźdźczyni Arly w Czarnej Straży w Lodowej Koronie.', '', '', '', '', 0),
(13236, 'koKR', 'Armia potępionych', 'Pewnie uważasz, że jesteś $gbardzo silny:bardzo silna; – walczysz z tymi nieumarłymi i miażdżysz ich kości swoimi machinami wojennymi.$B$BTo nic w porównaniu z siłą, jakiej trzeba było, by ich stworzyć.$B$BWidziałem, jak książę robił to osobiście. Mogę ci pokazać, jak to się stało... jeśli chcesz.', 'Matthias Lehner w Wysuniętym Obozie Pierwszego Legionu chce, żebyś $gwskrzesił:wskrzesiła; armię 100 ghulich sług.', '', 'Wróć do Matthiasa Lehnera w Dolinie Straconej Nadziei w Lodowej Koronie.', 'Wskrzeszone ghule sługi', '', '', '', 0),
(13237, 'koKR', 'Sondowanie obrony', 'Podczas gdy uwagę twojego dowódcy rozprasza nienawiść do waszych rywali z Przymierza, możesz liczyć na to, że ja skupię się wyłącznie na prawdziwym wrogu – Królu Liszu i jego sługach.$b$bJeśli twoi pobratymcy mają mieć jakąkolwiek nadzieję na pokonanie go w cytadeli, muszą zdobyć i utrzymać każdą z bram.$b$bNa razie skupmy się na pierwszej. Wróć na front i wybadaj ich obronę. Szukaj wszelkich oznak słabości, które moglibyśmy wykorzystać.$b$bCzekam na twój raport, $N.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gudał:udała; się na Złamany Front i $gpokonał:pokonała; 5 potężnych plugastw, 5 złowrogich nekromantów i 5 adeptów cienia.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Zabite potężne plugastwa', 'Zabici złowrodzy nekromanci', 'Zabici adepci cienia', '', 0),
(13238, 'koKR', 'Do czegoś się nada?', 'Gobliny! Nadpobudliwe małe wścibskie stworzonka...$b$bSłuchaj, $n. Miedziopazur, nasz pokładowy inżynier, upiera się, że ma mi do pokazania coś przydatnego.$b$bNie mam nastroju znosić jego piskliwego marudzenia. Ostatnim razem, gdy zwróciłem na niego uwagę, ćwierkał przez równą godzinę. Ledwo się powstrzymałem, żeby nie kopnąć go z wyskoku prosto w Upadek Sindragosy!$b$bIdź zamiast mnie i zrób mu przyjemność. Daj mi znać, jeśli rzeczywiście na coś wpadł.', 'Podniebny grabieżca Korm Czarna Blizna chce, żebyś $gporozmawiał:porozmawiała; z głównym inżynierem Miedziopazurem na pokładzie Młota Orgrima.', '', '', '', '', '', '', 0),
(13239, 'koKR', 'Lotność', 'Od czego by tu zacząć... no więc, musisz wiedzieć, że jako główny inżynier tego statku mam dostęp do wszystkich raportów wywiadu – tak, tak, to prawda – i ostatnio szczególnie zainteresowały mnie żmije mrozu, które widziano na południu, i chyba opracowałem plan, który może na nie zadziałać... wymaga to wprawdzie trochę biegania z twojej strony, ale w skrócie: budujesz kukłę ze zbroi, chlapiesz na nią trochę tego roztworu i uciekasz w bezpieczne miejsce!$b$b...Jeszcze tu jesteś, $N?', 'Główny inżynier Miedziopazur chce, żebyś na Złamanym Froncie $gużył:użyła; lotnego oleju Miedziopazura, by zwabić 3 szpony niebios Mroźnego Pomiotu.$b$bAby użyć oleju, musisz zebrać na tamtejszym polu bitwy stos kości, porzucony hełm i porzuconą zbroję.', '', 'Wróć do głównego inżyniera Miedziopazura na Młocie Orgrima w Lodowej Koronie.', 'Przeprowadzone testy w terenie', '', '', '', 0),
(13258, 'koKR', 'Sposobność', 'Niedawno wpadły nam w ręce plany, które wskazują słaby punkt Cytadeli Lodowej Korony. Lukę w jej obronie, w przenośni i dosłownie.$B$BZdobyte schematy pokazują otwór prowadzący kilkaset stóp w głąb ziemi. Nie wiemy, do czego służy, ale nasi zwiadowcy ustalili, że jest dla Plagi bardzo ważny.$B$BPorozmawiaj z sierżant Kreggą u podnóża Cytadeli Lodowej Korony – to ona dowodzi atakiem na to miejsce.', 'Porozmawiaj z sierżant Kreggą u podnóża Cytadeli Lodowej Korony.', '', '', '', '', '', '', 0),
(13259, 'koKR', 'Zdobycie przewagi', 'Mamy jedną szansę, żeby wyrządzić temu miejscu jakieś szkody – zadbajmy, żeby się udało.$B$BZdobyliśmy potężne saronitowe bomby wykonane przez Plagę. Ale zanim je odpalimy, musimy zabezpieczyć teren.$B$BTrzeba szybko opanować obronę Plagi, zanim nadciągną posiłki.$B$BPomóż moim ludziom i wróć, gdy będziesz $ggotów:gotowa; na fajerwerki.', 'Sierżant Kregga przy Cytadeli Lodowej Korony chce, żebyś $gzabił:zabiła; 10 potężnych poczwar.', '', 'Wróć do sierżant Kreggi przy Cytadeli Lodowej Korony w Lodowej Koronie.', '', '', '', '', 0),
(13260, 'koKR', 'Swój pozna swego', 'Choć nigdy nie powinniśmy przepuszczać okazji, by uderzyć w Przymierze, nie wolno nam zapominać o Pladze.$b$bJeszcze przez wiele tygodni nie będziemy tu mieć dość ludzi, by przeprowadzić porządny szturm na lodowiec, ale to nie przeszkodzi nam dowiedzieć się wszystkiego, co się da, o ich obronie.$b$bPoprosiłem naszego pokładowego rycerza śmierci, żeby doradzał ci w tym przedsięwzięciu. W końcu kto zna tego wroga lepiej niż oni?$b$bPozwól, że przedstawię ci Koltirę Tkacza Śmierci.$B', 'Podniebny grabieżca Korm chce, żebyś $gporozmawiał:porozmawiała; z Koltirą Tkaczem Śmierci na Młocie Orgrima.', '', '', '', '', '', '', 0),
(13261, 'koKR', 'Lotność', 'Juhuuu! Działa! Nie żebym wątpił w moją nadprzyrodzoną pomysłowość, tylko nie byłem do końca pewien, jakiego wybuchu się spodziewać – powiedzmy, że cieszę się, że nie $gosmaliłeś:osmaliłaś; sobie brwi. Teraz muszę tylko pokazać staremu Kormowi, jak się rozmraża takiego żmija. Będzie musiał awansować mnie na... na... na to, co jest wyżej niż główny inżynier! Masz, weź kolejną porcję tego specyfiku i wracaj na front, a ja pójdę po Korma...$b$bNo? Ruszaj się!', 'Główny inżynier Miedziopazur chce, żebyś na Złamanym Froncie $gużył:użyła; lotnego oleju Miedziopazura, by zwabić 3 szpony niebios Mroźnego Pomiotu.$b$bAby użyć oleju, musisz zebrać na tamtejszym polu bitwy stos kości, porzucony hełm i porzuconą zbroję.', '', 'Wróć do głównego inżyniera Miedziopazura na Młocie Orgrima w Lodowej Koronie.', 'Przeprowadzone testy w terenie', '', '', '', 0),
(13262, 'koKR', 'Wysadź to!', 'Lepiej nad tą sytuacją już nie zapanujemy. Do dzieła, $N.$B$BPotrzebuję kogoś, kto podpali lont przy tych bombach, i wygląda na to, że to będziesz ty.', 'Podejdź do pobliskiego stosu saronitowych bomb i podpal lont.', '', '', '', '', '', '', 0),
(13263, 'koKR', 'Krótki lont', 'Gdy podpalasz lont, zauważasz, że ogień trawi go znacznie szybciej, niż można by się spodziewać.$B$BBomby zaraz wybuchną, a twoją największą szansą na przeżycie jest rzucić się w stronę szybu i mieć nadzieję, że upadek cię nie zabije.', 'Szukaj wskazówek tam, gdzie zaprowadzi cię upadek.', '', '', '', '', '', '', 0),
(13264, 'koKR', 'To plugawe!', 'Plugastwa...$b$bPotrafią być bardzo groźnym wrogiem. Nieraz widziałem, jak odwracały losy bitwy. Mało kto jednak zdaje sobie sprawę, że potrafią też być bardzo użytecznymi sprzymierzeńcami.$b$bNie są zbyt bystre. Jeśli znasz tajniki ich tworzenia, możesz wydawać im proste rozkazy, których nie będą kwestionować.$b$bNa twoje szczęście ja znam te tajniki.$b$bTen zestaw ożywi szczątki plugastw, które pokonasz. Weź go i naucz się wykorzystywać je przeciwko Pladze przy Bramie Śmierci.', 'Koltira Tkacz Śmierci na Młocie Orgrima chce, żebyś za pomocą zestawu do reanimacji plugastwa $gstworzył:stworzyła; ożywione plugastwo i $gużył:użyła; go do zabicia 15 lodowych ghuli, 15 okrutnych fantomów i 15 wskrzeszonych żołnierzy Przymierza.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Wysadzone lodowe ghule', 'Wysadzone okrutne fantomy', 'Wysadzeni wskrzeszeni żołnierze Przymierza', '', 0),
(13271, 'koKR', 'Głos w ciemności', 'Ten przedmiot wcale nie jest kryształem, lecz jakimś organem zamkniętym w lodzie.$B$BGdy go dotykasz, przez twoją dłoń przeszywa straszliwy ból. Czujesz się, jakby ktoś rozciął ci rękę, a jednak nie widać żadnej rany.$B$BGdy zbierasz myśli, słyszysz w pobliżu głos małego chłopca.$B$B„Naprawdę nie trzeba było tego robić”.', 'Sprawdź, skąd dochodzi pobliski głos w Naz\'anak, w Zapomnianych Głębinach.', '', '', '', '', '', '', 0),
(13275, 'koKR', 'Czas się ukryć', 'Nie trzeba było tego dotykać. Ale skoro już to $gzrobiłeś:zrobiłaś;, on przyjdzie cię szukać.$B$BI znajdzie cię. Chyba że się przed nim ukryjesz.$B$BJeśli chcesz żyć, przynieś mi krew Beztwarzowych!', 'Matthias Lehner chce, żebyś $gzdobył:zdobyła; 3 porcje krwi Beztwarzowego.', '', 'Wróć do Matthiasa Lehnera w Naz\'anak: Zapomnianych Głębinach w Lodowej Koronie.', '', '', '', '', 0),
(13276, 'koKR', 'To plugawe!', 'Wiesz, co robić, $N.$b$bWeź ten zestaw i użyj wnętrzności ich plugastw, by stworzyć własne, a potem rozkaż mu zaatakować siły wroga przy bramie.$b$bDobrze zrobisz, jeśli dopracujesz tę taktykę przed naszym szturmem na bramę.', 'Koltira Tkacz Śmierci na Młocie Orgrima chce, żebyś za pomocą zestawu do reanimacji plugastwa $gstworzył:stworzyła; ożywione plugastwo i $gużył:użyła; go do zabicia 15 lodowych ghuli, 15 okrutnych fantomów i 15 wskrzeszonych żołnierzy Przymierza.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Wysadzone lodowe ghule', 'Wysadzone okrutne fantomy', 'Wysadzeni wskrzeszeni żołnierze Przymierza', '', 0),
(13277, 'koKR', 'Przeciw olbrzymom', 'Choć pokonanie Plagi na ziemi będzie kluczowe, nie wolno nam zaniedbać samej bramy.$b$bMięsne olbrzymy na blankach potrafią ciskać ogromnymi głazami i bryłami lodu, siejąc spustoszenie wśród piechoty wroga w dole.$b$bZbierz oddział i pokonaj te olbrzymy. Musimy wiedzieć, z jaką siłą mamy do czynienia.$b$bAch... i przynieś mi ich kręgosłupy. Jeśli dobrze pamiętam, mogę ci zdradzić pewną sztuczkę.', 'Koltira Tkacz Śmierci na Młocie Orgrima chce, żebyś $gprzyniósł:przyniosła; mu 5 ropiejących kręgosłupów z ropiejących poczwar w Mord\'rethar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13278, 'koKR', 'Coprous Splugawiony', 'Doszły mnie wieści o potężnym zombie przy Bramie Śmierci, $N.$b$bNie możemy zostawić bez odpowiedzi tak potencjalnie groźnego przeciwnika. Wszelkie informacje, które zdobędziesz, walcząc z nim, będą lepsze niż to, co wiemy teraz.$b$bUdaj się do zachodniej komnaty bramy i znajdź tego stwora. Walcz z nim i znajdź słabość, którą moglibyśmy wykorzystać.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; Coprousa Splugawionego w Mord\'rethar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Coprous Splugawiony pokonany', '', '', '', 0),
(13280, 'koKR', 'Król góry', 'Musisz natychmiast wprowadzić mój skokobot na sam czubek góry na północnym zachodzie, tu w Ymirheim, $N!$B$BTen podły, nic niewart Blast Gromobomba buduje własnego bota i boję się, że prawie go skończył. Ścigamy się o to, kto zostanie królem góry!$B$BKiedy już tam wskoczysz, wbij nasz sztandar bojowy w stos kości i pokaż wszystkim, że Przymierze – i moje inżynierskie umiejętności – są najlepsze!', 'Frazzle Zgrzytozębatka w Ymirheim chce, żebyś za pomocą jej skokobota Zgrzytozębatki $gwbił:wbiła; sztandar bojowy Przymierza w czaszki na szczycie góry.', '', 'Wróć do Frazzle Zgrzytozębatki w Ymirheim w Lodowej Koronie.', 'Sztandar bojowy Przymierza wbity', '', '', '', 0),
(13282, 'koKR', 'Powrót na powierzchnię', 'Musisz już iść. Za mną znajdziesz portal. Zabierze cię na powierzchnię.$B$BJeszcze się spotkamy. On będzie cię szukał.$B$BTo tylko kwestia czasu, aż cię znajdzie.', 'Wróć do Koltiry Tkacza Śmierci na pokładzie Młota Orgrima.', '', '', '', '', '', '', 0),
(13283, 'koKR', 'Król góry', 'Hej, $N, musisz wprowadzić mój skokobot na szczyt tej góry na południowym wschodzie, i to na wczoraj!$B$BTa dziewczyńska, zadufana Frazzle Zgrzytozębatka uważa, że jej skokobot jest lepszy od mojego. Ha! Ścigamy się o to, kto zostanie królem góry!$B$BKiedy już tam wskoczysz, wbij nasz sztandar bojowy w stos kości i pokaż wszystkim, że Horda – i moje odjechane inżynierskie umiejętności – są najlepsze!', 'Blast Gromobomba w Ymirheim chce, żebyś za pomocą jego skokobota Gromobomby $gwbił:wbiła; sztandar bojowy Hordy w czaszki na szczycie góry.', '', 'Wróć do Blasta Gromobomby w Ymirheim w Lodowej Koronie.', 'Sztandar bojowy Hordy wbity', '', '', '', 0),
(13284, 'koKR', 'Szturm lądem', 'Witaj, $N.$B$BNasze oddziały od jakiegoś czasu próbują szturmować Ymirheim, ale te wrykule są o wiele bardziej zajadłe niż wszyscy, z którymi dotąd walczyliśmy. Raz po raz urządzają nam zasadzki, gdy próbujemy przedostać się przez przełęcz, i straciliśmy wielu ludzi.$B$BJeśli chcesz wesprzeć walkę i pomóc mojej drużynie bezpiecznie dotrzeć do bram Ymirheim, chętnie wynagrodzimy twój trud. Gdy dotrzemy do bram, okopiemy się i zaczekamy, aż dogonią nas posiłki.', 'Odeskortuj żołnierzy z Niebołamacza do bram Ymirheim. Po wykonaniu zadania wróć po zapłatę do dowódcy sił lądowych Koupa na skraju lodowca na wschód od Ymirheim.', '', 'Wróć do dowódcy sił lądowych Koupa w Dolinie Straconej Nadziei w Lodowej Koronie.', 'Żołnierze Przymierza odeskortowani do Ymirheim', '', '', '', 0),
(13286, 'koKR', '...każda pomoc się przyda.', 'Desperackie czasy, $N...$b$bChoć jest mi z tym niewygodnie, jestem gotów przyjąć pomoc od każdego – nawet od naszego pokładowego rycerza śmierci.$b$bIdź do Thassariana i sprawdź, czy pomoże nam opracować taktykę przeciw Pladze, która zapewni zwycięstwo, gdy tylko będziemy w stanie przeprowadzić kolejną ofensywę.$b$bZaszliśmy tak daleko... nie możemy tu zawieść!', 'Wielki kapitan Justin Bartlett na pokładzie Niebołamacza chce, żebyś $gporozmawiał:porozmawiała; z Thassarianem.', '', '', '', '', '', '', 0),
(13287, 'koKR', 'Sondowanie obrony', 'Ktoś z twoim doświadczeniem z pewnością wie, że nie ma lepszego sposobu na poznanie wroga niż zmierzenie się z nim w walce.$b$bChoć bez wątpienia łakniesz chwały zdobycia Cytadeli Lodowej Korony, nie stanie się to bez zdobycia najpierw każdej z bram Króla Lisza. Na razie musisz skupić się na pierwszej z nich...$b$bWróć na Złamany Front. Wydaj wrogowi bitwę. Poszukaj słabości, którą moglibyśmy wykorzystać, i wróć do mnie ze szczegółowym raportem.', 'Thassarian na okręcie bojowym Przymierza, Niebołamaczu, chce, żebyś na Złamanym Froncie $gzabił:zabiła; 5 potężnych plugastw, 5 złowrogich nekromantów i 5 adeptów cienia.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Zabite potężne plugastwa', 'Zabici złowrodzy nekromanci', 'Zabici adepci cienia', '', 0),
(13288, 'koKR', 'To plugawe!', 'Plugastwa...$b$bPotrafią być bardzo groźnym wrogiem. Nieraz widziałem, jak odwracały losy bitwy. Mało kto jednak zdaje sobie sprawę, że potrafią też być bardzo użytecznymi sprzymierzeńcami.$b$bNie są zbyt bystre. Jeśli znasz tajniki ich tworzenia, możesz wydawać im proste rozkazy, których nie będą kwestionować.$b$bNa twoje szczęście ja znam te tajniki.$b$bTen zestaw ożywi szczątki plugastw, które pokonasz. Weź go i naucz się wykorzystywać je przeciwko Pladze przy Bramie Śmierci.', 'Thassarian na Niebołamaczu chce, żebyś za pomocą zestawu do reanimacji plugastwa $gstworzył:stworzyła; ożywione plugastwo i $gużył:użyła; go do zabicia 15 lodowych ghuli, 15 okrutnych fantomów i 15 wskrzeszonych żołnierzy Przymierza.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Wysadzone lodowe ghule', 'Wysadzone okrutne fantomy', 'Wysadzeni wskrzeszeni żołnierze Przymierza', '', 0),
(13289, 'koKR', 'To plugawe!', 'Wiesz, co robić, $N.$b$bWeź ten zestaw i użyj wnętrzności ich plugastw, by stworzyć własne, a potem rozkaż mu zaatakować siły wroga przy bramie.$b$bDobrze zrobisz, jeśli dopracujesz tę taktykę przed naszym kolejnym szturmem na bramę.', 'Thassarian na Niebołamaczu chce, żebyś za pomocą zestawu do reanimacji plugastwa $gstworzył:stworzyła; ożywione plugastwo i $gużył:użyła; go do zabicia 15 lodowych ghuli, 15 okrutnych fantomów i 15 wskrzeszonych żołnierzy Przymierza.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Wysadzone lodowe ghule', 'Wysadzone okrutne fantomy', 'Wysadzony wskrzeszony żołnierz Przymierza', '', 0),
(13290, 'koKR', 'Proszę o uwagę', 'Główny inżynier Kluczośrub okazał się bezcenny w służbie na pokładzie Niebołamacza. Gdyby nie jego pomysłowość, już kilka razy bylibyśmy rozsypani po połowie lodowca.$b$bRzecz w tym, że czuje się zobowiązany dzielić się każdym swoim drobnym wynalazkiem czy odkryciem – z których większości nawet nie rozumiem.$b$bMuszę się teraz skupić wyłącznie na naszych wrogach. Nie mogę sobie pozwolić na żadne rozpraszacze.$b$bOdwiedź go, proszę, w moim zastępstwie, $n. A jeśli możesz, pomóż mu. Znajdziesz go pod pokładem.', 'Wielki kapitan Bartlett chce, żebyś $gporozmawiał:porozmawiała; z głównym inżynierem Kluczośrubem na Niebołamaczu.', '', '', '', '', '', '', 0),
(13291, 'koKR', 'Pożyczona technologia', 'Rozumiem, rozumiem. Kapitanek jest zbyt zajęty, żeby obejrzeć to osobiście. Jego strata!$b$bWidzisz, udało mi się „pozyskać” pewną dostawę roztworu od wroga. I choć nie znoszę dłubać przy podrzędnej goblińskiej technologii, tym razem skłonny jestem zrobić wyjątek.$b$bWeź tę próbkę. Potrzebuję, żebyś $gprzeprowadził:przeprowadziła; kilka testów w terenie, tak tylko, żeby udowodnić jej przydatność, a ja w tym czasie spróbuję trochę inżynierii wstecznej, żeby powtórzyć proces wytwarzania.$b$bIdź na front i zbierz materiały na wabika, a potem użyj oleju.', 'Główny inżynier Kluczośrub na pokładzie Niebołamacza chce, żebyś $gużył:użyła; przemyconego roztworu na Złamanym Froncie.$b$bDo użycia roztworu potrzebne będą porzucony hełm, porzucona zbroja i stos kości – wszystko to znajdziesz na Złamanym Froncie.', '', 'Wróć do głównego inżyniera Kluczośruba na Niebołamaczu w Lodowej Koronie.', 'Przeprowadzone testy w terenie', '', '', '', 0),
(13292, 'koKR', 'Rozwiązanie w roztworze', 'Ach, tak, tak. Znowu tutaj, co? Praktyki nigdy dość, jak sądzę.$b$bProszę bardzo, oto rozwiązanie tego uciążliwego problemu z żmijami mrozu.$b$bPrzerzedź je, $N. Im więcej ich teraz wyeliminujesz, tym mniej spotkamy, gdy znów będziemy gotowi do marszu na cytadelę.$b$bNo to powodzenia. I koniecznie przynieś z powrotem wszystko, czego nie zużyjesz.', 'Główny inżynier Kluczośrub na pokładzie Niebołamacza chce, żebyś $gużył:użyła; przemyconego roztworu na Złamanym Froncie.$b$bDo użycia roztworu potrzebne będą porzucony hełm, porzucona zbroja i stos kości – wszystko to znajdziesz na Złamanym Froncie.', '', 'Wróć do głównego inżyniera Kluczośruba na Niebołamaczu w Lodowej Koronie.', 'Zniszczone szpony niebios Mroźnego Pomiotu', '', '', '', 0),
(13293, 'koKR', 'Do Ymirheim!', 'Musisz zejść do Ymirheim, tego wielkiego miasta mroźnych wrykuli w samym środku Lodowej Korony.$B$BNasz chłopak, Blast Gromobomba, jest tam, po zachodniej stronie miasta, i reprezentuje Ofensywę Wojennej Pieśni w zawodach przeciwko Przymierzu. Jego skokobot kontra ich skokobot w konkursie o tytuł króla góry!$B$BNie zawiedź nas, $N. Na szali jest duma goblińskiej inżynierii! Poza tym wszyscy chłopcy tu w ładowni na ciebie liczą.$B$BNo i postawiliśmy pieniądze na to, że skopiesz tym tchórzom tyłki!', 'Porozmawiaj z Blastem Gromobombą w Ymirheim.', '', '', '', '', '', '', 0),
(13294, 'koKR', 'Przeciw olbrzymom', 'Choć pokonanie Plagi na ziemi będzie kluczowe, nie wolno nam zaniedbać samej bramy.$b$bMięsne olbrzymy na blankach potrafią ciskać ogromnymi głazami i bryłami lodu, siejąc spustoszenie wśród piechoty wroga w dole.$b$bZbierz oddział i pokonaj te olbrzymy. Musimy wiedzieć, z jaką siłą mamy do czynienia.$b$bAch... i przynieś mi ich kręgosłupy. Jeśli dobrze pamiętam, mogę ci zdradzić pewną sztuczkę.', 'Thassarian na Niebołamaczu chce, żebyś $gprzyniósł:przyniosła; mu 5 ropiejących kręgosłupów z ropiejących poczwar w Mord\'rethar.$B', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13295, 'koKR', 'Podstawy chemii', '<Thassarian bierze ropiejące kręgosłupy i spuszcza z nich płyn do flaszki.>$b$bMało znana właściwość mięsnych olbrzymów...$b$bIch płyn rdzeniowy reaguje z zarazą w bardzo ciekawy sposób, zamieniając ją w żrący kwas.$b$bKwas wylany z wysokich blanków może nie być mile widziany przez żołnierzy w dole, ale przynajmniej ofiary nie powstaną i nie zasilą szeregów wroga.$b$bWlej zawartość tej flaszki do jednego z kotłów zarazy w zachodniej komnacie Bramy Śmierci.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gużył:użyła; ropiejącego płynu rdzeniowego na kotle zarazy w Mord\'rethar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Porcja zarazy zneutralizowana', '', '', '', 0),
(13296, 'koKR', 'Do Ymirheim!', 'Potrzebuję cię na dole, w Ymirheim, tym wielkim mieście mroźnych wrykuli w samym środku Lodowej Korony.$B$BFrazzle Zgrzytozębatka jest tam, po południowej stronie miasta, i reprezentuje Ekspedycję Walecznych w zawodach przeciwko hordziej hołocie. Jej skokobot kontra ich skokobot w konkursie o tytuł króla góry!$B$BNie zawiedź nas, $N. Na szali jest duma gnomiej inżynierii! Poza tym wszyscy chłopcy tu w ładowni na ciebie liczą.$B$BNo i postawiliśmy pieniądze na to, że skopiesz tym idiotom tyłki!', 'Porozmawiaj z Frazzle Zgrzytozębatką w Ymirheim.', '', '', '', '', '', '', 0),
(13298, 'koKR', 'Coprous Splugawiony', 'Doszły mnie wieści o potężnym zombie przy Bramie Śmierci, $N.$b$bNie możemy zostawić bez odpowiedzi tak potencjalnie groźnego przeciwnika. Wszelkie informacje, które zdobędziesz, walcząc z nim, będą lepsze niż to, co wiemy teraz.$b$bUdaj się do zachodniej komnaty bramy i znajdź tego stwora. Walcz z nim i znajdź słabość, którą moglibyśmy wykorzystać.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzabił:zabiła; Coprousa Splugawionego w Mord\'rethar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Coprous Splugawiony zabity', '', '', '', 0),
(13300, 'koKR', 'Niewolnicy saronitu', 'Nasi ludzie są pojmani i zmuszani do niewolniczej pracy w kopalniach saronitu w Ymirheim, twierdzy wrykuli w samym środku Lodowej Korony. Król Lisz każe im wydobywać tę bezbożną rudę dniem i nocą.$B$BObiecałem najwyższemu lordowi Fordringowi, że wydostaniemy tych nieszczęśników stamtąd żywych, i dokładnie to zrobimy.$B$BNiestety, mam rozkaz pozostać na tym okręcie bojowym i służyć jako ambasador przy Ekspedycji Walecznych. Czy uratujesz ich, proszę, w moim zastępstwie, $N?', 'Absalan Pobożny na pokładzie Niebołamacza chce, żebyś $guratował:uratowała; 10 niewolników z kopalni saronitu.', '', 'Wróć do Absalana Pobożnego na Niebołamaczu w Lodowej Koronie.', 'Uratowany niewolnik z kopalni saronitu', '', '', '', 0),
(13301, 'koKR', 'Szturm lądem', 'Witaj, $N.$B$BNasze oddziały od jakiegoś czasu próbują szturmować Ymirheim, ale te wrykule są o wiele bardziej zajadłe niż wszyscy, z którymi dotąd walczyliśmy. Raz po raz urządzają nam zasadzki, gdy próbujemy przedostać się przez przełęcz, i straciliśmy wielu ludzi.$B$BJeśli chcesz wesprzeć walkę i pomóc mojej drużynie bezpiecznie dotrzeć do bram Ymirheim, chętnie wynagrodzimy twój trud. Gdy dotrzemy do bram, okopiemy się i zaczekamy, aż dogonią nas posiłki.', 'Odeskortuj żołnierzy Kor\'kronu do bram Ymirheim. Po wykonaniu zadania wróć po zapłatę do dowódcy sił lądowych Xutjji na skraju lodowca na północ od Ymirheim.', '', 'Wróć do dowódcy sił lądowych Xutjji w strefie Ostrzału w Lodowej Koronie.', 'Żołnierze Hordy odeskortowani do Ymirheim', '', '', '', 0),
(13302, 'koKR', 'Niewolnicy saronitu', 'Nasi ludzie są pojmani i zmuszani do niewolniczej pracy w kopalniach saronitu w Ymirheim, twierdzy wrykuli w samym środku Lodowej Korony. Król Lisz każe im wydobywać tę bezbożną rudę dniem i nocą.$B$BObiecałem najwyższemu lordowi Fordringowi, że wydostaniemy tych nieszczęśników stamtąd żywych, i dokładnie to zrobimy.$B$BNiestety, mam rozkaz pozostać na tym okręcie bojowym i służyć jako ambasador przy Ofensywie Wojennej Pieśni. Czy uratujesz ich, proszę, w moim zastępstwie, $N?', 'Brat Keltan na pokładzie Młota Orgrima chce, żebyś $guratował:uratowała; 10 niewolników z kopalni saronitu.', '', 'Wróć do brata Keltana na Młocie Orgrima w Lodowej Koronie.', 'Uratowany niewolnik z kopalni saronitu', '', '', '', 0),
(13304, 'koKR', 'Naprawy polowe', 'Plaga wciąż nie otrząsnęła się po naszym ataku, $N. Teraz trzeba wykorzystać nasz rozpęd.$B$BStrategicznie ważna dolina pod nami stoi otworem. W południowo-wschodnim zakątku Doliny Straconej Nadziei znaleźliśmy rozebrany niszczyciel, który – jak sądzimy – jest sprawny.$B$BJeśli zdobędziesz brakujące części od szabrowników Plagi, powinno ci się udać go uruchomić. Jeden sprawny niszczyciel potrafi siać spustoszenie wśród naziemnych oddziałów wroga.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gzebrał:zebrała; 5 części niszczyciela od szabrujących fantomów w Dolinie Straconej Nadziei i $gzaniósł:zaniosła; je do rozbitego niszczyciela.', '', 'Wróć do rozbitego niszczyciela w Dolinie Straconej Nadziei w Lodowej Koronie.', '', '', '', '', 0),
(13305, 'koKR', 'Pokaż, na co cię stać', 'Zamierzasz użyć tej machiny przeciwko Pladze? W ten sposób z nimi nie wygrasz.$B$BMożesz zniszczyć setki... nawet tysiące. Ale nie wygrasz. Nie tutaj.$B$BKiedy skończysz bawić się swoją machiną, spotkaj się ze mną na północy. Jest tam stary obóz wojskowy. To, co ci pokażę, nauczy cię co nieco o tym, z kim masz do czynienia.', 'Użyj odnowionego niszczyciela, by zniszczyć 150 rozłożonych ghuli, 20 magów Mroźnej Czaszki i 2 kościane olbrzymy w Dolinie Straconej Nadziei. Po wykonaniu zadania porozmawiaj z Matthiasem Lehnerem w Wysuniętym Obozie Pierwszego Legionu.', '', 'Wróć do Matthiasa Lehnera w Dolinie Straconej Nadziei w Lodowej Koronie.', '', '', '', '', 0),
(13306, 'koKR', 'Stawianie barykad', 'Gdy nasze siły ruszą dalej za Aldur\'thar, będą narażone na atak z Wału Żelaznej Tamy i z rozległego lodowca poniżej.$B$BNie mamy ani czasu, ani materiałów, by budować umocnienia, ale możemy postawić kilka barykad, które osłonią naszych ludzi przed ostrzałem i rozbiją szarże Plagi.$B$BZanieś ten zestaw do budowy barykad do Doliny Poległych Bohaterów, po zachodniej stronie Aldur\'thar. Odszukaj znaczniki, które tam rozmieściłem, i użyj zestawu, by postawić w tych miejscach barykady.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś za pomocą zestawu do budowy barykad $gpostawił:postawiła; 8 barykad.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Postawione barykady', '', '', '', 0),
(13307, 'koKR', 'Zbryzgane krwią sztandary', 'W Dolinie Poległych Bohaterów i na Lodowcu Lodowej Korony, na zachód od Aldur\'thar, Plaga próbuje użyć poległych przeciwko nam. Porucznicy Plagi zbudzili zmarłych z doliny i natchnęli ich straszliwą siłą i zapałem. Źródłem tej mocy są sztandary noszone przez przywódców Plagi w rejonie lodowca. Zabij chorążych, a osłabisz nawróconych bohaterów, którymi dowodzą.$B$BTo na tobie spoczywa zadanie usunięcia tej przeszkody i przerzedzenia oporu, zanim ruszą główne siły.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; 5 chorążych Plagi, 5 nawracaczy Plagi i 20 nawróconych bohaterów.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13308, 'koKR', 'Sztuczki umysłu', '<Stwór przemawia wprost do twojego umysłu, a jego myśli są bolesne i obce.>$B$BIstoto, potrzebuję twojej pomocy. Tak jak twoi zniewoleni przyjaciele jestem ofiarą Ymirjarów Króla Lisza i ich chciwości. Pojmali mnie i zakuli w łańcuchy, gdy przyszło mi wynurzyć się z głębin, by zbadać odgłosy dochodzące z tej jaskini.$B$BPomożesz mi? Brygadzista tych kopalń ma klucz do moich łańcuchów. Zabij go!$B$B<Czujesz napór na swój umysł, jakby stwór próbował cię do czegoś zmusić.>', 'Mroczny mówca R\'khem w Kopalniach Saronitu chce, żebyś $godzyskał:odzyskała; klucz brygadzisty do jego łańcuchów.', '', 'Wróć do mrocznego mówcy R\'khema w Kopalniach Saronitu w Lodowej Koronie.', '', '', '', '', 0),
(13309, 'koKR', 'Szturm z powietrza', 'Mam kilku chłopaków w pełnym rynsztunku, gotowych do zrzutu wewnątrz Ymirheim. Przydałby mi się ktoś, kto dopilnuje, żeby bezpiecznie tam dotarli.$B$BW obrębie murów wrykule ustawili jakieś samoczynne wyrzutnie włóczni, które rozszarpują nasze transportowce. Kazaliśmy inżynierom zamontować wieżyczkę tłumiącą, żeby unieszkodliwić te wyrzutnie – wystarczy strzelić w pobliże którejś z nich, a dym powinien zasłonić jej widok i zapchać jej tryby.$B$BWskakuj do wieżyczki i dopilnuj, żeby wszyscy moi chłopcy dotarli w całości na miejsca zrzutu.', 'Dowódca sił lądowych Koup na skraju lodowca na wschód od Ymirheim rozkazał ci użyć wieżyczki tłumiącej z Niebołamacza, by utrzymać transportowiec wojsk Niebołamacza w całości wystarczająco długo, żeby wykonał wszystkie zrzuty.$B', '', 'Wróć do dowódcy sił lądowych Koupa w Dolinie Straconej Nadziei w Lodowej Koronie.', 'Zrzuceni infiltratorzy z Niebołamacza', '', '', '', 0),
(13310, 'koKR', 'Szturm z powietrza', 'No dobra, żółtodziobie, mam coś, dzięki czemu nie będziesz kompletnym zerem.$B$BOddział świetnie wyszkolonych infiltratorów jest gotowy do zrzutu wewnątrz Ymirheim. Wrykule mają tam samoczynne wyrzutnie włóczni, które rozrywają nasze transportowce na strzępy, więc inżynierowie z Młota Orgrima sklecili nam wieżyczkę tłumiącą.$B$BTy jesteś $gstrzelcem:strzelczynią;. Wystrzeliwuj pociski w ich wyrzutnie, żeby zasłonić im widok i zapchać tryby. Dopilnuj, żeby wszyscy moi ludzie zostali zrzuceni, a transportowiec został w jednym kawałku.', 'Dowódca sił lądowych Xutjja na skraju lodowca na północ od Ymirheim rozkazał ci użyć wieżyczki tłumiącej Kor\'kronu, by utrzymać transportowiec wojsk Kor\'kronu w całości wystarczająco długo, żeby wykonał wszystkie zrzuty.', '', 'Wróć do dowódcy sił lądowych Xutjji w strefie Ostrzału w Lodowej Koronie.', 'Zrzuceni infiltratorzy Kor\'kronu', '', '', '', 0),
(13312, 'koKR', 'Wał Żelaznej Tamy', 'Wał Żelaznej Tamy góruje nad Doliną Poległych Bohaterów, na zachód od Aldur\'thar. Panuje nad polami w dole ze wszystkich stron. Nie zdołamy posunąć się naprzód, jeśli nie zdobędziemy wału, a trzyma go Grimkor Nikczemny ze swoimi uczniami z Kultu Potępionych.$B$BJeśli zdołasz osłabić Grimkora, nasze siły będą wiedziały, czego się spodziewać podczas natarcia. Weź tę runę zniekształcenia. Uwolnienie jej mocy w pobliżu kuli Grimkora na końcu wału powinno wystarczyć, by zwrócić uwagę nekromanty.', 'Pokonaj Grimkora Nikczemnego i wróć do Koltiry Tkacza Śmierci na pokładzie Młota Orgrima.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13313, 'koKR', 'Oślepić oczy na niebie', 'Przymierzu jakimś cudem udało się wysłać eskadrę maszyn zwiadowczych nad Dolinę Poległych Bohaterów i Lodowiec Lodowej Korony, rozległe tereny na zachód od Aldur\'thar.$B$BNie możemy pozwolić, by przejęli prowadzenie w tej walce. Główny inżynier Miedziopazur dostarczył mi idealną broń przeciw temu zagrożeniu – swój nowy pocisk nazywa SGM-3. Zapewnia mnie, że zestrzeli maszyny latające Przymierza jednym trafieniem. Idź i użyj tej broni, by dać nam przewagę.', 'Użyj SGM-3, by zniszczyć 6 myśliwców zwiadowczych Niebołamacza, a następnie złóż raport podniebnemu grabieżcy Kormowi Czarnej Bliźnie na pokładzie Młota Orgrima.', '', 'Wróć do podniebnego grabieżcy Korma Czarnej Blizny na Młocie Orgrima w Lodowej Koronie.', 'Zestrzelone myśliwce zwiadowcze Niebołamacza', '', '', '', 0),
(13314, 'koKR', 'Przechwycić wiadomość', 'Horda coś knuje i nie podoba mi się to. Po numerze, jaki wycięli na Złamanym Froncie, są zdolni do wszystkiego, a powstrzymanie ich należy do nas.$B$BNa niebie nad Lodowcem Lodowej Korony, na zachód od Aldur\'thar i Wału Żelaznej Tamy, panuje wzmożony ruch. Zwiadowcy i posłańcy Hordy kursują tam i z powrotem na smoczych jastrzębiach, przewożąc raporty i rozkazy. Weź ten pistolet na strzałki i zabijaj nim zwiadowców Młota Orgrima. Najlepiej będzie chyba działał, jeśli też będziesz w powietrzu.', 'Przechwyć 6 meldunków z Młota Orgrima od zwiadowców Młota Orgrima i przynieś je wielkiemu kapitanowi Justinowi Bartlettowi na pokładzie Niebołamacza.', '', 'Wróć do wielkiego kapitana Justina Bartletta na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13315, 'koKR', 'Pokaz przedpremierowy', 'Robimy postępy. Mamy obiecujący zestaw taktyk, który powinien dać nam kontrolę nad Bramą Śmierci. Ofiar bez wątpienia będzie wiele, ale w końcu powinniśmy zwyciężyć – o ile nie przeszkodzi nam ta Horda, z którą tak się upieracie walczyć...$b$bTak czy inaczej, następnym celem będzie Brama Spustoszenia. Zleć tam i zapoznaj się z nią oraz z wrogami, którzy tam stacjonują.$b$bKiedy wrócisz, będę mieć dla ciebie przygotowane misje.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gpoleciał:poleciała; do Bramy Spustoszenia i $godwiedził:odwiedziła; południową, środkową, północną i północno-zachodnią część bramy.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Południowa część Aldur\'thar odwiedzona', 'Środkowa część Aldur\'thar odwiedzona', 'Północna część Aldur\'thar odwiedzona', 'Północno-zachodnia część Aldur\'thar odwiedzona', 0),
(13316, 'koKR', 'Strażnicy Corp\'rethar', 'Corp\'rethar, zwana Bramą Grozy. To ostatnia przeszkoda między nami a Cytadelą Lodowej Korony. Czeka na południe od Wału Żelaznej Tamy, za lodowcem i Pożogą. Zanim nasze oddziały do niej dotrą, będą wyczerpane, a nawet gorzej.$B$BMusimy osłabić jej obronę, inaczej siła naszej armii rozbije się o jej mury.$B$BNa jej blankach stoją jedni z najzacieklejszych i najbardziej fanatycznych sług Króla Lisza. Zrób wszystko, co w twojej mocy, by zniszczyć tych strażników, i miej nadzieję, że to wystarczy.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; 5 zwiastunów grozy i 5 strażników Corp\'rethar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13318, 'koKR', 'Przeciągnij i upuść', 'Kult Potępionych trzyma Bramę Spustoszenia, co? Żadna niespodzianka.$b$bCzas na małą zabawę. $GWspominałeś:Wspominałaś;, że na południowym krańcu bramy szkoli się nowych kultystów. Niemal na pewno mają przy sobie specjalny przedmiot, który dostaje każdy nowicjusz – kulę iluzji.$b$bTe artefakty służą do przebierania członków kultu, pozwalając im bezpiecznie przejść, przeniknąć do wroga albo po prostu się wśród niego wtopić.$b$bZabijaj tych głupców, dopóki nie znajdziesz kuli, $N, a potem użyj jej na ciemiężcy.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzebrał:zebrała; kule iluzji od zgorzkniałych nowicjuszy w Aldur\'thar i $gużył:użyła; ich na 3 tamtejszych mrocznych ciemiężcach.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Mroczny ciemiężca przeciągnięty i upuszczony', '', '', '', 0),
(13319, 'koKR', 'Łańcuch dowodzenia', 'Z twojego raportu i mojej wiedzy o Kulcie wynika, że w każdym obozowisku na bramie działaniami kieruje nadzorca.$b$bChoć pozbycie się ich przywódców będzie tylko chwilowym utrudnieniem, przynajmniej ich spowolni i wytrąci z równowagi. A to, $N, na razie wystarczająco godny cel.$b$bOdszukaj tych nadzorców i wróć do mnie, gdy już się nimi zajmiesz.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gudał:udała; się do Aldur\'thar i $gpokonał:pokonała; nadzorcę Faedrisa, nadzorcę Savryna, nadzorcę Veraja i nadzorcę Jhaeqona.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Nadzorca Faedris zabity', 'Nadzorca Jhaeqon zabity', 'Nadzorca Veraj zabity', 'Nadzorca Savryn zabity', 0),
(13320, 'koKR', 'Nie da się odtworzyć', 'Czuję ich kotły aż stąd, ale to nie zarazę w nich warzą.$b$bKandydaci do kultu są zmuszani do wypicia mikstury, która odbiera im wolę i na zawsze czyni z nich niewolników Króla Lisza.$b$bPodobno ten napój zawiera spaczoną duszę istoty, którą torturowano, zanim bezlitośnie ją zarżnięto, ale nigdy nie udało mi się go odtworzyć...$b$bNapełnij tę flaszkę próbkami z każdego z trzech kotłów w północno-zachodniej części bramy i zanieś ją głównemu inżynierowi Kluczośrubowi.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gużył:użyła; flaszki z przegródkami przy każdym z 3 kotłów kultystów w Aldur\'thar, a następnie $gzaniósł:zaniosła; ją głównemu inżynierowi Kluczośrubowi.', '', 'Wróć do głównego inżyniera Kluczośruba na Niebołamaczu w Lodowej Koronie.', 'Niebieska próbka pobrana', 'Zielona próbka pobrana', 'Ciemna próbka pobrana', '', 0),
(13321, 'koKR', 'Ponowny test', 'To powinno załatwić sprawę!$b$bCi pokręceni chuligani szukają dusz do swojego wariackiego soczku? No to mówię, pomóżmy im trochę!$b$bPociągnij łyk tego – spokojnie, solidnie to rozcieńczyłem... Jestem prawie pewien, że jedynym skutkiem będzie to, że wyczujesz esencję każdego kultysty, którego pokonasz.$b$bKiedy zbierzesz ich sporo, wrzuć tę wijącą się masę spaczonych dusz do któregoś z ich kotłów.$b$bZobaczymy, jak im posmakuje ich własne lekarstwo!', 'Główny inżynier Kluczośrub na pokładzie Niebołamacza chce, żebyś $gwrzucił:wrzuciła; wijącą się masę do kotła w Aldur\'thar.', '', 'Wróć do głównego inżyniera Kluczośruba na Niebołamaczu w Lodowej Koronie.', 'Wijąca się masa wygnana', '', '', '', 0),
(13322, 'koKR', 'Ponowny test', 'Ci pokręceni kultyści szukają dusz do swojego wariackiego soczku? No to pomóżmy im trochę!$b$bPociągnij łyk tego – spokojnie, solidnie to rozcieńczyłem... Jestem prawie pewien, że jedynym skutkiem będzie to, że wyczujesz esencję każdego kultysty.$b$bKiedy zbierzesz ich sporo, wrzuć tę wijącą się masę spaczonych dusz do jednego z ich kotłów.$b$bZobaczymy, jak im posmakuje ich własne lekarstwo!', 'Główny inżynier Kluczośrub na pokładzie Niebołamacza chce, żebyś $gwypił:wypiła; rozcieńczony tonik kultu, $gzabijał:zabijała; kultystów w Aldur\'thar i $gzbierał:zbierała; ich skażone esencje. Następnie masz połączyć 10 esencji w wijącą się masę i wrzucić ją do dowolnego z ich kotłów.', '', 'Wróć do głównego inżyniera Kluczośruba na Niebołamaczu w Lodowej Koronie.', 'Wijąca się masa wygnana', '', '', '', 0),
(13323, 'koKR', 'Przeciągnij i upuść', 'Wygląda na to, że tych nowicjuszy znowu przybywa. Wiesz, co robić...$b$bW południowej części bramy szkoli się nowych kultystów. Na pewno mają przy sobie specjalny przedmiot, który dostaje każdy nowicjusz – kulę iluzji.$b$bTe artefakty służą do przebierania członków kultu, pozwalając im bezpiecznie przejść, przeniknąć do wroga albo po prostu się wśród niego wtopić.$b$bZabijaj tych głupców, dopóki nie znajdziesz kilku kul, a potem użyj ich na tamtejszych ciemiężcach.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzebrał:zebrała; kule iluzji od zgorzkniałych nowicjuszy w Aldur\'thar i $gużył:użyła; ich na 3 tamtejszych mrocznych ciemiężcach.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Mroczni ciemiężcy przeciągnięci i upuszczeni', '', '', '', 0),
(13328, 'koKR', 'Roztrzaskaj odłamki', 'Na blankach Corp\'rethar słudzy Króla Lisza wznieśli trzy kryształy: odłamki grozy, rozpaczy i męki. Jeśli nasi ludzie dotrą do murów Corp\'rethar, Król Lisz użyje tej broni przeciwko naszej armii.$B$BW pełni mocy kryształy porażą umysły naszych ludzi paraliżującym bólem i strachem. Wtedy Plaga będzie mogła wyrżnąć ich do woli.$B$BZnajdź te odłamki, zniszcz je i przynieś mi ich szczątki. Nie możemy pozwolić, by Król Lisz użył tej broni!', 'Przynieś pęknięty odłamek grozy, pęknięty odłamek rozpaczy i pęknięty odłamek cierpienia Koltirze Tkaczowi Śmierci na pokładzie Młota Orgrima.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13329, 'koKR', 'Przed Bramą Grozy', 'Pożoga, czyli teren przed Corp\'rethar, na południe od Wału Żelaznej Tamy, to miejsce, gdzie elitarni żołnierze Króla Lisza ustawili się, by bronić cytadeli.$B$BDrogę zagradza legion szkieletowych grabieżców pod wodzą oddziału rycerzy śmierci. Obawiam się, że nawet gdy ci grabieżcy padną, Plaga po prostu złoży ich na nowo i znów pośle przeciwko nam.$B$BWymyśliłem plan, jak temu zapobiec, ale nie mam pojęcia, czy się sprawdzi. Weź ten roztwór i użyj go, by rozpuścić szczątki grabieżców.', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś za pomocą lotnego kwasu $grozpuścił:rozpuściła; szczątki 6 szkieletowych grabieżców.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Rozpuszczone kości szkieletowych grabieżców', '', '', '', 0),
(13330, 'koKR', 'Krew Wybranych', 'Wrykule, którzy zyskali przychylność Króla Lisza, nazywają siebie Ymirjarami. Zamieszkują miasto w samym środku Lodowej Korony. Przed szturmem na Cytadelę Lodowej Korony musimy wiele przygotować, a zadanie, które teraz przed nami stoi, to rozgromienie tych tak zwanych „Wybranych” Króla Lisza.$B$BIdź do ich miasta, Ymirheim, i wyrżnij ich we własnym domu. Niech nie będzie wątpliwości, kto jest tu silniejszy.', 'Siewca wojny Davos Rioht na Młocie Orgrima wysłał cię, żebyś $gzabił:zabiła; 20 wrykuli w Ymirheim.', '', 'Wróć do siewcy wojny Davosa Riohta na Młocie Orgrima w Lodowej Koronie.', 'Zabici wrykule z Ymirheim', '', '', '', 0),
(13331, 'koKR', 'Niech Przymierze pozostanie ślepe', 'Przymierze jest uparte, trzeba mu to przyznać, ale żeby nas powstrzymać, potrzeba czegoś więcej. Weź ze sobą ten SGM-3 i znowu zestrzel myśliwce zwiadowcze Niebołamacza.$B$BWątpię, żeby to przesłanie dotarło do ich zakutych łbów, ale pocisków jest dość, żeby próbować dalej. Idź i znajdź ich myśliwce latające nad Doliną Poległych Bohaterów, na zachód od Aldur\'thar, i nie wracaj, dopóki nie zostaną z nich szczątki.', 'Użyj SGM-3, by zniszczyć 6 myśliwców zwiadowczych Niebołamacza, a następnie złóż raport podniebnemu grabieżcy Kormowi Czarnej Bliźnie na pokładzie Młota Orgrima.', '', 'Wróć do podniebnego grabieżcy Korma Czarnej Blizny na Młocie Orgrima w Lodowej Koronie.', 'Zestrzelone myśliwce zwiadowcze Niebołamacza', '', '', '', 0),
(13332, 'koKR', 'Stawianie barykad', 'Gdy nasze siły ruszą dalej za Aldur\'thar, będą narażone na atak z Wału Żelaznej Tamy i z rozległego lodowca poniżej.$B$BNie mamy ani czasu, ani materiałów, by budować umocnienia, ale możemy postawić kilka barykad, które osłonią naszych ludzi przed ostrzałem i rozbiją szarże Plagi.$B$BZanieś ten zestaw do budowy barykad do Doliny Poległych Bohaterów, po zachodniej stronie Aldur\'thar. Odszukaj znaczniki, które tam rozmieściłem, i użyj zestawu, by postawić w tych miejscach barykady.', 'Thassarian na pokładzie Niebołamacza chce, żebyś za pomocą zestawu do budowy barykad $gpostawił:postawiła; 8 barykad.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Postawione barykady', '', '', '', 0),
(13333, 'koKR', 'Przechwyć więcej meldunków', 'Mimo naszych wysiłków Horda wciąż wysyła zwiadowców nad Lodowiec Lodowej Korony, na zachód od Wału Żelaznej Tamy i Aldur\'thar.$B$BNie możemy pozwolić, by Horda zyskała przewagę dzięki temu zwiadowi. Weź znowu pistolet na strzałki i nie okazuj zwiadowcom Młota Orgrima litości! Przynieś mi przechwycone meldunki.$B$BZmarnowany wysiłek Hordy będzie naszym zyskiem.', 'Przechwyć 6 meldunków z Młota Orgrima od zwiadowców Młota Orgrima i przynieś je wielkiemu kapitanowi Justinowi Bartlettowi na pokładzie Niebołamacza.', '', 'Wróć do wielkiego kapitana Justina Bartletta na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13334, 'koKR', 'Zbryzgane krwią sztandary', 'W Dolinie Poległych Bohaterów i na Lodowcu Lodowej Korony, na zachód od Aldur\'thar, Plaga próbuje użyć poległych przeciwko nam. Porucznicy Plagi zbudzili zmarłych z doliny i natchnęli ich straszliwą siłą i zapałem. Źródłem tej mocy są sztandary noszone przez przywódców Plagi w rejonie lodowca. Zabij chorążych, a osłabisz nawróconych bohaterów, którymi dowodzą.$B$BTo na tobie spoczywa zadanie usunięcia tej przeszkody i sprawdzenia oporu, zanim ruszą główne siły.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzabił:zabiła; 5 chorążych Plagi, 5 nawracaczy Plagi i 20 nawróconych bohaterów.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13335, 'koKR', 'Przed Bramą Grozy', 'Pożoga, czyli teren przed Corp\'rethar, na południe od Wału Żelaznej Tamy, to miejsce, gdzie elitarni żołnierze Króla Lisza ustawili się, by bronić cytadeli.$B$BDrogę zagradza legion szkieletowych grabieżców pod wodzą oddziału rycerzy śmierci. Obawiam się, że nawet gdy ci grabieżcy padną, Plaga po prostu złoży ich na nowo i znów pośle przeciwko nam.$B$BWymyśliłem plan, jak temu zapobiec, ale nie mam pojęcia, czy się sprawdzi. Weź ten roztwór i użyj go, by rozpuścić szczątki grabieżców.', 'Thassarian na pokładzie Niebołamacza chce, żebyś za pomocą lotnego kwasu $grozpuścił:rozpuściła; zwłoki 6 szkieletowych grabieżców.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Rozpuszczone kości szkieletowych grabieżców', '', '', '', 0),
(13336, 'koKR', 'Krew Wybranych', 'Wrykule, którzy zyskali przychylność Króla Lisza, nazywają siebie Ymirjarami. Zamieszkują miasto w samym środku Lodowej Korony. Przed szturmem na Cytadelę Lodowej Korony musimy wiele przygotować, a zadanie, które teraz przed nami stoi, to rozgromienie tych tak zwanych „Wybranych” Króla Lisza.$B$BIdź do ich miasta, Ymirheim, i wyrżnij ich we własnym domu. Niech nie będzie wątpliwości, kto jest tu silniejszy.', 'Rycerz-kapitan Drosche na Niebołamaczu wysłał cię, żebyś $gzabił:zabiła; 20 wrykuli w Ymirheim.', '', 'Wróć do rycerza-kapitana Drosche na Niebołamaczu w Lodowej Koronie.', 'Zabici wrykule z Ymirheim', '', '', '', 0),
(13337, 'koKR', 'Wał Żelaznej Tamy', 'Wał Żelaznej Tamy góruje nad Doliną Poległych Bohaterów, na zachód od Aldur\'thar. Panuje nad polami w dole ze wszystkich stron. Nie zdołamy posunąć się naprzód, jeśli nie zdobędziemy wału, a trzyma go Grimkor Nikczemny ze swoimi uczniami z Kultu Potępionych.$B$BJeśli zdołasz osłabić Grimkora, nasze siły będą wiedziały, czego się spodziewać podczas natarcia. Weź tę runę zniekształcenia. Uwolnienie jej mocy w pobliżu kuli Grimkora na końcu wału powinno wystarczyć, by zwrócić uwagę nekromanty.', 'Pokonaj Grimkora Nikczemnego i wróć do Thassariana na pokładzie Niebołamacza.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13338, 'koKR', 'Strażnicy Corp\'rethar', 'Corp\'rethar, zwana Bramą Grozy. To ostatnia przeszkoda między nami a Cytadelą Lodowej Korony. Czeka na południe od Wału Żelaznej Tamy, za lodowcem i Pożogą. Zanim nasze oddziały do niej dotrą, będą wyczerpane, a nawet gorzej.$B$BMusimy osłabić jej obronę, inaczej siła naszej armii rozbije się o jej mury.$B$BNa jej blankach stoją jedni z najzacieklejszych i najbardziej fanatycznych sług Króla Lisza. Zrób wszystko, co w twojej mocy, by zniszczyć tych strażników, i miej nadzieję, że to wystarczy.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzabił:zabiła; 5 zwiastunów grozy i 5 strażników Corp\'rethar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13339, 'koKR', 'Roztrzaskaj odłamki', 'Na blankach Corp\'rethar słudzy Króla Lisza wznieśli trzy kryształy: odłamki grozy, rozpaczy i męki. Jeśli nasi ludzie dotrą do murów Corp\'rethar, Król Lisz użyje tej broni przeciwko naszej armii.$B$BW pełni mocy kryształy porażą umysły naszych ludzi paraliżującym bólem i strachem. Wtedy Plaga będzie mogła wyrżnąć ich do woli.$B$BZnajdź te odłamki, zniszcz je i przynieś mi ich szczątki. Nie możemy pozwolić, by Król Lisz użył tej broni!', 'Przynieś pęknięty odłamek grozy, pęknięty odłamek rozpaczy i pęknięty odłamek cierpienia Thassarianowi na pokładzie Niebołamacza.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13340, 'koKR', 'Dołącz do szturmu', 'Potrzebujemy więcej ludzi do głównego szturmu na Ymirheim.$B$BKażdy wojownik z choćby połową mózgu ci powie, że wrykule to zażarci wojownicy i nie wolno ich lekceważyć. Dla Ymirjarów to podwójnie prawda. Bez żadnych hamulców pokazali nam, dlaczego Król Lisz uznał ich za godnych.$B$BSzturmem dowodzi dowódca sił lądowych Xutjja. Samo miasto leży w środku Lodowej Korony – oddziały Xutjji stoją na skraju lodowca, na północ od miasta.', 'Zamelduj się u dowódcy sił lądowych Xutjji na skraju lodowca na północ od Ymirheim.', '', '', '', '', '', '', 0),
(13341, 'koKR', 'Dołącz do szturmu', 'Potrzebujemy więcej ludzi do głównego szturmu na Ymirheim.$B$BKażdy wojownik, który ma choć pół mózgu, powie ci, że wrykule to zaciekli wojownicy, których nie wolno lekceważyć. Ymirjarów dotyczy to w dwójnasób. Bez żadnych zahamowań pokazują nam, dlaczego Król Lisz uznał ich za godnych.$B$BSzturmem dowodzi dowódca sił lądowych Koup. Samo miasto leży w środku Lodowej Korony – oddziały Koupa stoją na skraju lodowca, na wschód od miasta.', 'Zamelduj się u dowódcy sił lądowych Koupa na skraju lodowca na wschód od Ymirheim.', '', '', '', '', '', '', 0),
(13342, 'koKR', 'To nie pluskwa', 'Dobra, $gprzyjacielu:panienko;, czas podłożyć pluskwę.$b$bSpokojnie, to nie do końca pluskwa, ale spełni swoje zadanie.$b$bW północnej części Aldur\'thar przywoływacze Pustki z kultu zniewalają demoniczne sługi. Użyj tej różdżki, by wyssać ciemną materię ze zwłok tych zniewolonych sług, a potem za pomocą ich kryształu przywołań powołaj do istnienia naszego małego szpiega.$b$bDopóki go nie wykryją, posłaniec będzie naszymi oczami i uszami i dyskretnie będzie śledził poczynania wroga.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzebrał:zebrała; 5 porcji ciemnej materii i $gprzywołał:przywołała; mrocznego posłańca w Aldur\'thar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Przywołano mrocznego posłańca', '', '', '', 0),
(13344, 'koKR', 'To nie pluskwa', 'Kultyści wykryli ostatniego posłańca, którego $gprzywołałeś:przywołałaś;, $N.$b$bDużo się dzięki niemu dowiedzieliśmy, ale musimy dalej śledzić każdy ich ruch.$b$bUżyj tej różdżki, by wyssać ciemną materię ze zwłok zniewolonych sług w Aldur\'thar. Potem za pomocą ich kryształu przywołań powołaj do istnienia kolejnego mrocznego posłańca.$b$bDopóki go nie wykryją, posłaniec będzie naszymi oczami i uszami i dyskretnie będzie śledził poczynania wroga.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzebrał:zebrała; 5 porcji ciemnej materii i $gprzywołał:przywołała; mrocznego posłańca w Aldur\'thar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Przywołano mrocznego posłańca', '', '', '', 0),
(13345, 'koKR', 'Potrzeba więcej informacji', 'Kult Potępionych słynie z wymyślania wielkopańskich planów, które koniec końców rzadko się udają. Ale tym razem coś jest inaczej...$b$bMoże to bliskość Króla Lisza podsyca ich zapał. Cokolwiek to jest, wydają się pewniejsi siebie niż kiedykolwiek. Musimy się dowiedzieć, co karmi tę brawurę, a potem znaleźć sposób, by ich jej pozbawić!$b$bSądzę, że klucz leży w rękach ich badaczy. Dowiedz się, nad czym pracują, i przekaż mi szczegóły.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzdobył:zdobyła; 3 strony badań kultystów od badaczy kultu w Aldur\'thar i $gzłożył:złożyła; z nich rozprawę Kultu Potępionych.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13346, 'koKR', 'Nie ma spokoju dla niegodziwców', 'Ci głupcy naprawdę natrafili na coś, co może poważnie zagrozić naszym planom!$b$bPrzywódca tej sekty, Alumeth, złożył się w rytualnej ofierze, a teraz jego podwładni przelewają moc w jego duszę.$b$bJeśli pozwolimy mu spocząć, ich wysiłki wkrótce zmienią go w potężnego przeciwnika.$b$bZbierz z ich komnaty jego serce, czaszkę, berło i szaty, połącz je i użyj jego szczątków na tamtejszym krysztale.$b$bPośpiesz się, $N! Zniszcz go, zanim stanie się jeszcze potężniejszy!', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gpokonał:pokonała; Alumetha Wyniesionego w Aldur\'thar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Pokonano Alumetha Wyniesionego', '', '', '', 0),
(13348, 'koKR', 'Daremność', 'Teraz już widzisz? Wysyłając swoich ludzi przeciw armiom księcia, tylko zasilasz jego szeregi.$B$BNie oczekuję, że to zrozumiesz... pewnie skończysz jak inni. Lepiej wracaj do tego, kto cię przysłał. Może się martwi.', 'Wróć do Koltiry Tkacza Śmierci na pokładzie Młota Orgrima.', '', '', '', '', '', '', 0),
(13349, 'koKR', 'Kolebka Mroźnego Pomiotu', 'Nie możemy wytracić impetu. Nie dajmy siłom Plagi wytchnienia.$B$BUpadek Sindragosy leży na wschodzie, tuż za Doliną Straconej Nadziei. Działa tam Kult Potępionych pod czujnym nadzorem nieumarłych wrykulskich sługusów Króla Lisza.$B$BTo miejsce wielkiej mocy, być może cmentarzysko Błękitnego Stada. To tam z kości błękitnych smoków powstaje budzący grozę Mroźny Pomiot.$B$BAtak na to miejsce mocno utrudniłby wrogowi dostęp do żmijów mrozu. Dasz radę, $N?', 'Koltira Tkacz Śmierci na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; 5 wskrzesicieli żmijów, 8 kultystów plugawicieli i 3 nekrowładców wrykulów przy Upadku Sindragosy.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13350, 'koKR', 'Nie ma spokoju dla niegodziwców', 'To Alumeth... Znów rośnie w siłę. Czuję to. Jego podwładni ponownie przelewają moc w jego duszę.$b$bJeśli pozwolimy mu spocząć, ich wysiłki wkrótce zmienią go w potężnego przeciwnika.$b$bWróć do jego komnaty w północnej części Aldur\'thar. Połącz jego serce, czaszkę, berło i szaty, a potem użyj jego szczątków na tamtejszym krysztale.$b$bPośpiesz się, $N! Zniszcz go, zanim stanie się jeszcze potężniejszy!', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gpokonał:pokonała; Alumetha Wyniesionego w Aldur\'thar.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', 'Zabito Alumetha Wyniesionego', '', '', '', 0),
(13351, 'koKR', 'Pokaz przedpremierowy', 'Robimy postępy. Mamy obiecujący zestaw taktyk, które powinny dać nam kontrolę nad bramą śmierci. Bez wątpienia będzie wiele ofiar, ale ostatecznie powinniśmy zwyciężyć – o ile Przymierze nie wejdzie nam w drogę.$b$bNastępnym celem będzie Aldur\'thar, Brama Spustoszenia. Zleć tam i zapoznaj się z nią oraz z wrogami, którzy jej strzegą.$b$bKiedy wrócisz, będę mieć dla ciebie przygotowane zadania.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzleciał:zleciała; do Bramy Spustoszenia i $godwiedził:odwiedziła; jej południową, środkową, północną i północno-zachodnią część.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Południowa część Aldur\'thar odwiedzona', 'Środkowa część Aldur\'thar odwiedzona', 'Północna część Aldur\'thar odwiedzona', 'Północno-zachodnia część Aldur\'thar odwiedzona', 0),
(13352, 'koKR', 'Przeciągnij i upuść', 'Kult Potępionych trzyma Bramę Spustoszenia, co? Żadna niespodzianka.$b$bCzas na małą zabawę. $GWspominałeś:Wspominałaś;, że na południowym krańcu bramy szkoli się nowych kultystów. Niemal na pewno mają przy sobie specjalny przedmiot, który dostaje każdy nowicjusz – kulę iluzji.$b$bTe artefakty służą do przebierania członków kultu, pozwalając im bezpiecznie przejść, przeniknąć do wroga albo po prostu się wśród niego wtopić.$b$bZabijaj tych głupców, dopóki nie znajdziesz kuli, $N, a potem użyj jej na ciemiężcy.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzdobył:zdobyła; kule iluzji od zgorzkniałych nowicjuszy w Aldur\'thar i $gużył:użyła; ich na 3 tamtejszych mrocznych ciemiężcach.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Mroczny ciemiężca przeciągnięty i upuszczony', '', '', '', 0),
(13353, 'koKR', 'Przeciągnij i upuść', 'Wygląda na to, że tych nowicjuszy znowu przybywa. Wiesz, co robić...$b$bW południowej części bramy szkoli się nowych kultystów. Na pewno mają przy sobie specjalny przedmiot, który dostaje każdy nowicjusz – kulę iluzji.$b$bTe artefakty służą do przebierania członków kultu, pozwalając im bezpiecznie przejść, przeniknąć do wroga albo po prostu się wśród niego wtopić.$b$bZabijaj tych głupców, dopóki nie znajdziesz kilku kul, a potem użyj ich na tamtejszych ciemiężcach.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzdobył:zdobyła; kule iluzji od zgorzkniałych nowicjuszy w Aldur\'thar i $gużył:użyła; ich na 3 tamtejszych mrocznych ciemiężcach.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Mroczny ciemiężca przeciągnięty i upuszczony', '', '', '', 0),
(13354, 'koKR', 'Łańcuch dowodzenia', 'Z twojego raportu i mojej wiedzy o Kulcie wynika, że w każdym obozowisku na bramie działaniami kieruje nadzorca.$b$bChoć pozbycie się ich przywódców będzie tylko chwilowym utrudnieniem, przynajmniej ich spowolni i wytrąci z równowagi. A to, $N, na razie wystarczająco godny cel.$b$bOdszukaj tych nadzorców i wróć do mnie, gdy już się nimi zajmiesz.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gudał:udała; się do Aldur\'thar i $gpokonał:pokonała; nadzorców Faedrisa, Savryna, Veraja i Jhaeqona.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Nadzorca Faedris zabity', 'Nadzorca Jhaeqon zabity', 'Nadzorca Veraj zabity', 'Nadzorca Savryn zabity', 0),
(13355, 'koKR', 'Nie da się odtworzyć', 'Czuję ich kotły aż stąd, ale to, co tam warzą, to nie zaraza.$b$bKandydaci do kultu muszą wypić miksturę, która odbiera im wolę i na zawsze czyni ich niewolnikami Króla Lisza.$b$bPodobno mikstura zawiera wypaczoną duszę istoty, którą torturowano, zanim bezlitośnie ją zarżnięto, ale nigdy nie udało mi się tego odtworzyć...$b$bNapełnij tę flaszkę próbkami z każdego z trzech kotłów w północno-zachodniej części bramy i zanieś ją głównemu inżynierowi Miedziopazurowi.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gużył:użyła; flaszki z przegródkami przy każdym z 3 kotłów kultystów w Aldur\'thar, a potem $gzaniósł:zaniosła; ją głównemu inżynierowi Miedziopazurowi.', '', 'Wróć do głównego inżyniera Miedziopazura na Młocie Orgrima w Lodowej Koronie.', 'Niebieska próbka pobrana', 'Zielona próbka pobrana', 'Ciemna próbka pobrana', '', 0),
(13356, 'koKR', 'Ponowny test', 'To powinno załatwić sprawę!$b$bTe pokręcone chuligany szukają dusz do swojego szalonego soczku? To ja mówię, że trochę im pomożemy!$b$bPociągnij łyk tego – nie bój się, porządnie rozcieńczyłem... Jedyne działanie to wykrywanie esencji każdego kultysty, którego pokonasz.$b$bKiedy zbierzesz trochę esencji, wrzuć tę wijącą się masę wypaczonych dusz do któregokolwiek z ich kotłów.$b$bZobaczymy, jak im posmakuje ich własne lekarstwo!', 'Główny inżynier Miedziopazur na pokładzie Młota Orgrima chce, żebyś $gwrzucił:wrzuciła; wijącą się masę do kotła w Aldur\'thar.', '', 'Wróć do głównego inżyniera Miedziopazura na Młocie Orgrima w Lodowej Koronie.', 'Wijąca się masa wygnana', '', '', '', 0),
(13357, 'koKR', 'Ponowny test', 'Ci pokręceni kultyści szukają dusz do swojego wariackiego soczku? No to pomóżmy im trochę!$b$bPociągnij łyk tego – spokojnie, solidnie to rozcieńczyłem... Jestem prawie pewien, że jedynym skutkiem będzie to, że wyczujesz esencję każdego kultysty.$b$bKiedy zbierzesz ich sporo, wrzuć tę wijącą się masę spaczonych dusz do jednego z ich kotłów.$b$bZobaczymy, jak im posmakuje ich własne lekarstwo!', 'Główny inżynier Miedziopazur na pokładzie Młota Orgrima chce, żebyś $gwrzucił:wrzuciła; wijącą się masę do kotła w Aldur\'thar.', '', 'Wróć do głównego inżyniera Miedziopazura na Młocie Orgrima w Lodowej Koronie.', 'Wijąca się masa wygnana', '', '', '', 0),
(13358, 'koKR', 'To nie pluskwa', 'Dobra, $gprzyjacielu:panienko;, czas podłożyć pluskwę.$b$bSpokojnie, to nie do końca pluskwa, ale spełni swoje zadanie.$b$bW północnej części Aldur\'thar przywoływacze Pustki z kultu zniewalają demoniczne sługi. Użyj tej różdżki, by wyssać ciemną materię ze zwłok tych zniewolonych sług, a potem za pomocą kryształu przywołań kultystów powołaj do istnienia naszego małego szpiega.$b$bDopóki go nie wykryją, posłaniec będzie naszymi oczami i uszami i dyskretnie będzie śledził poczynania wroga.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzebrał:zebrała; 5 porcji ciemnej materii i $gprzywołał:przywołała; mrocznego posłańca w Aldur\'thar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Przywołano mrocznego posłańca', '', '', '', 0),
(13359, 'koKR', 'Gdzie padły smoki', 'Padł tu cały lęg błękitnych smoków. A teraz jego słudzy podnoszą je jednego po drugim.$B$BNajwiększego z nich wskrzesił sam. Przynieś mi trochę pyłu z kości piskląt, a pokażę ci dokładnie, jak to zrobił.', 'Matthias Lehner przy Upadku Sindragosy chce, żebyś $gzdobył:zdobyła; 6 porcji pyłu z kości smoczych piskląt.', '', 'Wróć do Matthiasa Lehnera przy Upadku Sindragosy w Lodowej Koronie.', '', '', '', '', 0),
(13360, 'koKR', 'Czas na odpowiedzi', 'Masz wiele pytań, $N. Tylko ty mnie widzisz, bo $gdotknąłeś:dotknęłaś; czegoś, co kiedyś należało do niego... nie pamiętasz?$B$BNie wiesz, co to jest? Cóż, nie mogę ci tak po prostu powiedzieć... bardzo by się rozzłościł. On nie jest już tylko księciem... jest królem!$B$BSpotkajmy się na Dziedzińcu Kości, na północ od Cytadeli Lodowej Korony, a zobaczysz na własne oczy.', 'Porozmawiaj z Matthiasem Lehnerem na Dziedzińcu Kości.', '', '', '', '', '', '', 0),
(13361, 'koKR', 'Łowca i książę', 'Zanim książę został królem, stoczył wiele bitew... ale tylko w jednej omal nie zginął.$B$BToczyła się właśnie tutaj. Kiedy pozwolisz mi pokazać ci, co się stało, wszystko zrozumiesz.$B$BZnajdź zakrwawiony kamień i podnieś go z ziemi. Zobaczysz, co się wydarzyło.', 'Matthias Lehner na Dziedzińcu Kości chce, żebyś $godszukał:odszukała; zakrwawiony kamień i $gdopełnił:dopełniła; Przeznaczenia księcia.', '', 'Wróć do Matthiasa Lehnera na Dziedzińcu Kości w Lodowej Koronie.', 'Przeznaczenie księcia', '', '', '', 0),
(13362, 'koKR', 'Wiedza to straszliwe brzemię', 'Teraz już wiesz, z kim się mierzysz, $N. Z przeciwnikiem, który nie zna już bólu... skruchy... ani człowieczeństwa. Z przeciwnikiem, który zrobi wszystko, by dostać to, czego chce.$B$BSerce było jego słabością, a teraz on wie, że je $gznalazłeś:znalazłaś;.$B$BJeśli zamierzasz po nie wrócić, lepiej weź ze sobą pomoc. Drugi raz nie zostawi go bez straży.', 'Zamelduj się u Koltiry na pokładzie Młota Orgrima.', '', '', '', '', '', '', 0),
(13363, 'koKR', 'Pomoc Argentu', 'Wśród rycerzy śmierci krążyły pogłoski o wydarzeniach, o których mówisz. Zawsze sądziłem, że ta historia jest bardziej... symboliczna.$B$BMusimy ostrzec innych, ale dyskretnie. Gdy tylko Król Lisz się zorientuje, że wykonujemy ruch, przeniesie serce w inne miejsce – drugiej takiej szansy już nie dostaniemy.$B$BKult Potępionych już kiedyś przeniknął do Hordy i Przymierza. Hebanowy Miecz działa zbyt blisko Plagi.$B$BMusimy porozmawiać z Tirionem Fordringiem i jego Krucjatą Argentu.', 'Porozmawiaj z najwyższym lordem Tirionem Fordringiem na Szczycie Krzyżowców.', '', '', '', '', '', '', 0),
(13364, 'koKR', 'Gambit Tiriona', 'Jeszcze dziś rano moi zwiadowcy donieśli mi o procesji Kultu Potępionych, która wyruszyła z Cytadeli Lodowej Korony do Katedry Ciemności, niosąc jakiś artefakt.$B$BA teraz dowiaduję się, że może to być serce samego Arthasa... coś, co zawiera ostatnią resztkę jego człowieczeństwa.$B$BTo znak od Światłości. Dopóki taki artefakt istnieje, jest szansa, że Arthas Menethil znów stanie się człowiekiem!$B$BSpotkajmy się przy wejściu do katedry. Koniecznie zdobądź kaptur kultysty – idziemy incognito.', 'Tirion Fordring na Szczycie Krzyżowców chce, żebyś $gzdobył:zdobyła; i $gzałożył:założyła; kaptur akolity kultu, a potem $gspotkał:spotkała; się z nim przy wejściu do Katedry Ciemności, na północny zachód od Cytadeli Lodowej Korony.', '', 'Wróć do najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców w Lodowej Koronie.', '', 'Gambit Tiriona', '', '', 0),
(13365, 'koKR', 'To nie pluskwa', 'Kultyści wykryli ostatniego posłańca, którego $gprzywołałeś:przywołałaś;, $N.$b$bDużo się dzięki niemu dowiedzieliśmy, ale musimy dalej śledzić każdy ruch kultu.$b$bUżyj tej różdżki, by wyssać ciemną materię ze zwłok zniewolonych sług w Aldur\'thar. Potem za pomocą ich kryształu przywołań powołaj do istnienia kolejnego mrocznego posłańca.$b$bDopóki go nie wykryją, posłaniec będzie naszymi oczami i uszami i dyskretnie będzie śledził poczynania wroga.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzebrał:zebrała; 5 porcji ciemnej materii i $gprzywołał:przywołała; mrocznego posłańca w Aldur\'thar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Przywołano mrocznego posłańca', '', '', '', 0),
(13366, 'koKR', 'Potrzeba więcej informacji', 'Kult Potępionych słynie z wymyślania wielkopańskich planów, które koniec końców rzadko się udają. Ale tym razem coś jest inaczej...$b$bMoże to bliskość Króla Lisza podsyca ich zapał. Cokolwiek to jest, wydają się pewniejsi siebie niż kiedykolwiek. Musimy się dowiedzieć, co karmi tę brawurę, a potem znaleźć sposób, by ich jej pozbawić!$b$bSądzę, że klucz leży w rękach ich badaczy. Dowiedz się, nad czym pracują, i przekaż mi szczegóły.', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzdobył:zdobyła; 3 strony badań kultystów od badaczy kultu w Aldur\'thar i $gzłożył:złożyła; z nich rozprawę Kultu Potępionych.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13367, 'koKR', 'Nie ma spokoju dla niegodziwców', 'Ci głupcy naprawdę natrafili na coś, co może poważnie zagrozić naszym planom!$b$bPrzywódca tej sekty, Alumeth, złożył się w rytualnej ofierze, a teraz jego podwładni przelewają moc w jego duszę.$b$bJeśli pozwolimy mu spocząć, ich wysiłki wkrótce zmienią go w potężnego przeciwnika.$b$bZbierz z ich komnaty jego serce, czaszkę, berło i szaty, połącz je i użyj jego szczątków na tamtejszym krysztale.$b$bPośpiesz się, $N! Zniszcz go, zanim stanie się jeszcze potężniejszy!', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; Alumetha Wyniesionego w Aldur\'thar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Pokonano Alumetha Wyniesionego', '', '', '', 0),
(13368, 'koKR', 'Nie ma spokoju dla niegodziwców', 'To Alumeth... Znów rośnie w siłę. Czuję to. Jego podwładni ponownie przelewają moc w jego duszę.$b$bJeśli pozwolimy mu spocząć, ich wysiłki wkrótce zmienią go w potężnego przeciwnika.$b$bWróć do jego komnaty w północnej części Aldur\'thar. Połącz jego serce, czaszkę, berło i szaty, a potem użyj jego szczątków na tamtejszym krysztale.$b$bPośpiesz się, $N! Zniszcz go, póki jeszcze jest czas!', 'Koltira na pokładzie Młota Orgrima chce, żebyś $gzabił:zabiła; Alumetha Wyniesionego w Aldur\'thar.', '', 'Wróć do Koltiry Tkacza Śmierci na Młocie Orgrima w Lodowej Koronie.', 'Pokonano Alumetha Wyniesionego', '', '', '', 0),
(13373, 'koKR', 'Korzyści z nauki na obrzeżach', 'Zainstalowałam naszą infrazieloną technologię w przejętych bombowcach – ochroni cię podczas pierwszej misji na terytorium wroga! Porozmawiaj z Rizzy Zapadkokręt, żeby dostać bombowiec, a potem leć nad Ostrzał!$B$BBędziesz mieć bomby, rakiety i osłony. Trzymaj osłony naładowane i zrzucaj bomby na naziemne siły Plagi w strefie Ostrzału. Wróć, gdy trafisz swoje cele, a czeka cię więcej pracy.', 'Inżynier z obrzeży Tezzla chce, żebyś $gzabił:zabiła; 40 żołnierzy piechoty ostrzału, 8 kapitanów ostrzału i 15 czyhających gargulców.', '', 'Wróć do inżynier z obrzeży Tezzli w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13374, 'koKR', 'Naładowani do buntu!', '$N, tylko nasi najlepsi piloci dostają taką misję – głęboko, bardzo głęboko na terytorium wroga, a chroni cię jedynie moc infrazielonej technologii!$B$BPoproś Rizzy o kolejny bombowiec i tym razem przeleć nim przez Dolinę Straconej Nadziei. W tej misji masz cele zarówno w powietrzu, jak i na ziemi, więc miej oczy szeroko otwarte, a osłony na pełnej mocy!$B$BPowodzenia!', 'Inżynier z obrzeży Tezzla chce, żebyś $gzabił:zabiła; żołnierzy piechoty ostrzału, czyhające gargulce, wartowników Mroźnego Pomiotu i machiny wojenne Plagi.$B', '', 'Wróć do inżynier z obrzeży Tezzli w strefie Ostrzału w Lodowej Koronie.', '', '', '', '', 0),
(13376, 'koKR', 'Totalny opór: Dolina Straconej Nadziei!', '$N, walka trwa. Na szczęście mamy pełne zapasy bomb i rakiet! Czas na kolejną misję bombową – tym razem długą, przez Ostrzał aż do Doliny Straconej Nadziei. Wyleć znowu infrazielonym bombowcem i rozwal tę Plagę na małe plażątka!', 'Inżynier z obrzeży Tezzla chce, żebyś $gzabił:zabiła; 50 żołnierzy piechoty ostrzału, 20 czyhających gargulców, 12 wartowników Mroźnego Pomiotu i 12 machin wojennych Plagi.', '', 'Wróć do inżynier z obrzeży Tezzli w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13378, 'koKR', 'Główny inżynier Miedziopazur', 'Porozmawiaj z głównym inżynierem Miedziopazurem.', 'Porozmawiaj z głównym inżynierem Miedziopazurem.', '', '', '', '', '', '', 0),
(13379, 'koKR', 'Zielona technologia', 'To Tezzlę musisz poznać, tak, ją... Opanowała nową długość fali, infrazieleń, i użyła jej, żeby ukryć się tuż przy Pladze! Na tyle blisko, żeby ją bombardować!$B$BDam ci infrazielone widzenie, żebyś $gmógł:mogła; ją znaleźć w kryjówce nad Aldur\'thar, Bramą Spustoszenia. Leć, leć... Wiem, że ma robotę dla dzielnych bohaterów, którzy aż się palą, żeby wylecieć w powietrze! To znaczy... żeby wysadzić Plagę w powietrze!$B$BI jeszcze jedno, $N: Przymierze ukradło naszą technologię i ma w pobliżu własne ukryte lądowisko. Omijaj kopułę z banerami Przymierza!', 'Porozmawiaj z inżynier z obrzeży Tezzlą.', '', '', '', '', '', '', 0),
(13380, 'koKR', 'Na czele szarży', 'Infrazielona technologia pozwala nam pozostać w ukryciu tutaj, Pladze tuż pod nosem! Co więcej, zainstalowaliśmy infrazieleń w specjalnie skonstruowanych bombowcach... ale nie po to, żeby je ukryć, o nie! Używamy infrazielonej technologii, żeby je osłaniać!$B$BPorozmawiaj z Karen No i poproś o bombowiec. Przeleć nim nad Ostrzałem... używaj osłon i wieżyczki, żeby się chronić, a wyrzutni bomb, żeby trafiać cele Plagi. Dobrze się wyćwicz, a potem wróć do mnie – będę mieć dla ciebie jeszcze ważniejszą misję!', 'Kibli Kilohertz chce, żebyś $gzabił:zabiła; 40 żołnierzy piechoty ostrzału, 8 kapitanów ostrzału i 15 czyhających gargulców.', '', 'Wróć do Kibliego Kilohertza w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13381, 'koKR', 'Cel pod napięciem', 'Włóż szczęśliwe skarpetki, $N, i odmów ulubione modlitwy. Ta misja wystawi na próbę twój spryt i wytrzymałość jak wizyta teściów!$B$BPoproś Karen No o kolejny bombowiec. Przeleć nim za Ostrzał, nad Dolinę Straconej Nadziei. Tym razem masz więcej celów, i na ziemi, i w powietrzu. Trzymaj osłony naładowane, a broń gotową do strzału, $N! Zobaczymy się, jak będzie po wszystkim.', 'Kibli Kilohertz chce, żebyś $gzabił:zabiła; żołnierzy piechoty ostrzału, czyhające gargulce, wartowników Mroźnego Pomiotu i machiny wojenne Plagi.', '', 'Wróć do Kibliego Kilohertza w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13382, 'koKR', 'Herce i harce: Dolina Straconej Nadziei', 'Walka trwa! Przyszły twoje nowe rozkazy – dalekiego zasięgu misja bombowa przez Ostrzał aż do Doliny Straconej Nadziei. Kiedy będziesz $ggotowy:gotowa;, poproś Karen o bombowiec i zasyp Plagę bombami i rakietami!', 'Kibli Kilohertz chce, żebyś $gzabił:zabiła; 50 żołnierzy piechoty ostrzału, 20 czyhających gargulców, 12 wartowników Mroźnego Pomiotu i 12 machin wojennych Plagi.', '', 'Wróć do Kibliego Kilohertza w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13383, 'koKR', 'Kilohertz', 'Gobliny miały szczęście i odkryły nową energię. Nazywają ją infrazielenią i niech mnie nazwą jednookim ogrem, jeśli te świry nie trafiły na zieloną żyłę złota.$B$BIdź i znajdź Kibliego Kilohertza. Kieruje inżynierią wsteczną infrazieleni w małym, ukrytym lądowisku Przymierza nad Aldur\'thar, Bramą Spustoszenia. Dam ci infrazielone widzenie, żebyś $gmógł:mogła; je znaleźć. Leć do kopuły z naszymi banerami Przymierza – jeśli zbliżysz się do lądowiska Hordy, wpakujesz się w zielone tarapaty.', 'Główny inżynier Kluczośrub chce, żebyś $godnalazł:odnalazła; Kibliego Kilohertza w ukrytym lądowisku Przymierza nad Aldur\'thar, Bramą Spustoszenia.', '', '', '', '', '', '', 0),
(13386, 'koKR', 'Wykorzystać wyrwę', 'Mam dla ciebie ciekawe zadanie, $N. O ile masz ochotę na wyzwanie.$B$BDostaliśmy cynk o otworze pod Cytadelą Lodowej Korony. Nasi inżynierowie przestudiowali układ budowli i uznali, że to słaby punkt konstrukcji.$B$BWysłaliśmy tam kilku ludzi razem z „pożyczonymi” saronitowymi bombami. Dowodzi nimi kapitan Kendall.$B$BZ niewielką pomocą moglibyśmy zadać siłom Plagi potężny cios. Co ty na to, $N?', 'Porozmawiaj z kapitanem Kendallem pod Cytadelą Lodowej Korony.', '', '', '', '', '', '', 0),
(13387, 'koKR', 'Zabezpieczenie terenu', 'Saronitowe bomby są na miejscu, $N. Mamy jednak tylko jedną szansę. Nie zmarnujmy jej.$B$BPotrzebujemy chwilowej kontroli nad terenem, żeby bezpiecznie przeprowadzić detonację. Spróbujmy trochę przetrzebić szeregi Plagi.', 'Kapitan Kendall przy Cytadeli Lodowej Korony chce, żebyś $gzabił:zabiła; 10 potężnych poczwar.', '', 'Wróć do kapitana Kendalla przy Cytadeli Lodowej Korony w Lodowej Koronie.', '', '', '', '', 0),
(13388, 'koKR', 'Odpalaj!', 'Wszystko wygląda dobrze. Do dzieła.$B$BStos bomb leży tuż przy otchłani. Zacznę ewakuować ludzi.', 'Kapitan Kendall pod Cytadelą Lodowej Korony chce, żebyś $gpodszedł:podeszła; do pobliskiego stosu saronitowych bomb i $gpodpalił:podpaliła; lont.', '', '', '', '', '', '', 0),
(13389, 'koKR', 'Krótki lont', 'Gdy podpalasz lont, zauważasz, że ogień trawi go znacznie szybciej, niż można by się spodziewać.$B$BBomby zaraz wybuchną, a twoją największą szansą na przeżycie jest rzucić się w stronę szybu i mieć nadzieję, że upadek cię nie zabije.', 'Szukaj wskazówek tam, gdzie zaprowadzi cię upadek.', '', '', '', '', '', '', 0),
(13390, 'koKR', 'Głos w ciemności', 'Ten przedmiot wcale nie jest kryształem, lecz jakimś organem zamkniętym w lodzie.$B$BGdy go dotykasz, przez twoją dłoń przeszywa straszliwy ból. Czujesz się, jakby ktoś rozciął ci rękę, a jednak nie widać żadnej rany.$B$BGdy zbierasz myśli, słyszysz w pobliżu głos małego chłopca.$B$B„Naprawdę nie trzeba było tego robić”.', 'Sprawdź, skąd dochodzi pobliski głos w Naz\'anak, w Zapomnianych Głębinach.', '', '', '', '', '', '', 0),
(13391, 'koKR', 'Czas się ukryć', 'Nie trzeba było tego dotykać. Ale skoro już to $gzrobiłeś:zrobiłaś;, on przyjdzie cię szukać.$B$BI znajdzie cię. Chyba że się przed nim ukryjesz.$B$BJeśli chcesz żyć, przynieś mi krew Beztwarzowych!', 'Matthias Lehner chce, żebyś $gzdobył:zdobyła; 3 porcje krwi Beztwarzowego.', '', 'Wróć do Matthiasa Lehnera w Naz\'anak: Zapomnianych Głębinach w Lodowej Koronie.', '', '', '', '', 0),
(13392, 'koKR', 'Powrót na powierzchnię', 'Musisz już iść. Za mną znajdziesz portal. Zabierze cię na powierzchnię.$B$BJeszcze się spotkamy. On będzie cię szukał.$B$BTo tylko kwestia czasu, aż cię znajdzie.', 'Wróć do Thassariana na pokładzie Niebołamacza.', '', '', '', '', '', '', 0),
(13393, 'koKR', 'Naprawy polowe', 'Dobra. Nie świętujmy jeszcze. Musimy wykorzystać impet, który daliśmy sobie tą małą misją bombową.$B$BNa polu poniżej wypatrzyliśmy sprawny katapultowy niszczyciel Hordy. Wygląda na to, że fantomy rozbierają go na części.$B$BJeśli zdołasz go poskładać, będziemy mogli poważnie przetrzebić armie Plagi w dolinie.$B$BJasne, będziesz w mniejszości, ale bardzo w ciebie wierzę!', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzebrał:zebrała; 5 części niszczyciela od szabrujących fantomów i $gzaniósł:zaniosła; je do rozbitego niszczyciela w Dolinie Straconej Nadziei.', '', 'Wróć do rozbitego niszczyciela w Dolinie Straconej Nadziei w Lodowej Koronie.', '', '', '', '', 0),
(13394, 'koKR', 'Pokaż, na co cię stać', 'Zamierzasz użyć tej machiny przeciwko Pladze? W ten sposób z nimi nie wygrasz.$B$BMożesz zniszczyć setki... nawet tysiące. Ale nie wygrasz. Nie tutaj.$B$BKiedy skończysz bawić się swoją machiną, spotkaj się ze mną na północy. Jest tam stary obóz wojskowy. To, co ci pokażę, nauczy cię co nieco o tym, z kim masz do czynienia.', 'Użyj odnowionego niszczyciela, by zniszczyć 150 rozłożonych ghuli, 20 magów Mroźnej Czaszki i 2 kościane olbrzymy w Dolinie Straconej Nadziei. Po wykonaniu zadania porozmawiaj z Matthiasem Lehnerem w Wysuniętym Obozie Pierwszego Legionu.', '', 'Wróć do Matthiasa Lehnera w Dolinie Straconej Nadziei w Lodowej Koronie.', '', '', '', '', 0),
(13395, 'koKR', 'Armia potępionych', 'Pewnie uważasz, że jesteś $gbardzo silny:bardzo silna; – walczysz z tymi nieumarłymi i miażdżysz ich kości swoimi machinami wojennymi.$B$BTo nic w porównaniu z siłą, jakiej trzeba było, by ich stworzyć.$B$BWidziałem, jak książę robił to osobiście. Mogę ci pokazać, jak to się stało... jeśli chcesz.', 'Matthias Lehner w Wysuniętym Obozie Pierwszego Legionu chce, żebyś $gwskrzesił:wskrzesiła; armię 100 ghulich sług.', '', 'Wróć do Matthiasa Lehnera w Dolinie Straconej Nadziei w Lodowej Koronie.', 'Wskrzeszone ghule sługi', '', '', '', 0),
(13396, 'koKR', 'Daremność', 'Teraz już widzisz? Wysyłając swoich ludzi przeciw armiom księcia, tylko zasilasz jego szeregi.$B$BNie oczekuję, że to zrozumiesz... pewnie skończysz jak inni. Lepiej wracaj do tego, kto cię przysłał. Może się martwi.', 'Wróć do Thassariana na pokładzie Niebołamacza.', '', '', '', '', '', '', 0),
(13397, 'koKR', 'Upadek Sindragosy', 'Prawdziwy z ciebie skarb, $N. Widzisz, kiedy daję zadanie któremuś z pozostałych żołnierzy, szanse, że je wykona, są mniej więcej pół na pół. Szanse, że wróci... cóż, trochę gorsze.$B$BAle z tobą to zawsze pewniak. Jak gnomi mechanizm zegarowy!$B$BW każdym razie mam dla ciebie kolejne. Upadek Sindragosy, na wschód od doliny. Kultyści są tam bardzo aktywni, między innymi – choć nie tylko – wskrzeszają żmije mrozu. Musisz im porządnie dać po zębach.$B$BNienawidzę kultystów.', 'Thassarian na pokładzie Niebołamacza chce, żebyś $gzabił:zabiła; 5 wskrzesicieli żmijów, 8 kultystów plugawicieli i 3 nekrowładców wrykulów przy Upadku Sindragosy.', '', 'Wróć do Thassariana na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13398, 'koKR', 'Gdzie padły smoki', 'Padł tu cały lęg błękitnych smoków. A teraz jego słudzy podnoszą je jednego po drugim.$B$BNajwiększego z nich wskrzesił sam. Przynieś mi trochę pyłu z kości piskląt, a pokażę ci dokładnie, jak to zrobił.', 'Matthias Lehner przy Upadku Sindragosy chce, żebyś $gzdobył:zdobyła; 6 porcji pyłu z kości smoczych piskląt.', '', 'Wróć do Matthiasa Lehnera przy Upadku Sindragosy w Lodowej Koronie.', '', '', '', '', 0),
(13399, 'koKR', 'Czas na odpowiedzi', 'Masz wiele pytań, $N. Tylko ty mnie widzisz, bo $gdotknąłeś:dotknęłaś; czegoś, co kiedyś należało do niego... nie pamiętasz?$B$BNie wiesz, co to jest? Cóż, nie mogę ci tak po prostu powiedzieć... bardzo by się rozzłościł. On nie jest już tylko księciem... jest królem!$B$BSpotkajmy się na Dziedzińcu Kości, na północ od Cytadeli Lodowej Korony, a zobaczysz na własne oczy.', 'Porozmawiaj z Matthiasem Lehnerem na Dziedzińcu Kości.', '', '', '', '', '', '', 0),
(13400, 'koKR', 'Łowca i książę', 'Zanim książę został królem, stoczył wiele bitew... ale tylko w jednej omal nie zginął.$B$BToczyła się właśnie tutaj. Kiedy pozwolisz mi pokazać ci, co się stało, wszystko zrozumiesz.$B$BZnajdź zakrwawiony kamień i podnieś go z ziemi. Zobaczysz, co się wydarzyło.', 'Matthias Lehner na Dziedzińcu Kości chce, żebyś $godszukał:odszukała; zakrwawiony kamień i $gdopełnił:dopełniła; Przeznaczenia księcia.', '', 'Wróć do Matthiasa Lehnera na Dziedzińcu Kości w Lodowej Koronie.', 'Przeznaczenie księcia', '', '', '', 0),
(13401, 'koKR', 'Wiedza to straszliwe brzemię', 'Teraz już wiesz, z kim się mierzysz, $N. Z przeciwnikiem, który nie zna już bólu... skruchy... ani człowieczeństwa. Z przeciwnikiem, który zrobi wszystko, by dostać to, czego chce.$B$BSerce było jego słabością, a teraz on wie, że je $gznalazłeś:znalazłaś;.$B$BJeśli zamierzasz po nie wrócić, lepiej weź ze sobą pomoc. Drugi raz nie zostawi go bez straży.', 'Zamelduj się u Thassariana na pokładzie Niebołamacza.', '', '', '', '', '', '', 0),
(13402, 'koKR', 'Pomoc Tiriona', 'To nie pierwszy raz, gdy słyszę tę historię o Arthasie i jego sercu... Zawsze myślałem, że to zmyślona opowiastka, która ma robić wrażenie na szeregowcach.$B$BMusimy natychmiast zrobić użytek z tych informacji. Niestety, musimy działać w tajemnicy.$B$BAgenci Arthasa są wszędzie, a jeśli się dowie, nasz plan pójdzie na dno.$B$BMusimy z tym iść do Krucjaty Argentu. Każdego paladyna w tym zakonie Tirion wybrał osobiście. Jeśli ktoś jest wolny od kultystów w swoich szeregach, to właśnie oni.', 'Porozmawiaj z najwyższym lordem Tirionem Fordringiem na Szczycie Krzyżowców.', '', '', '', '', '', '', 0),
(13403, 'koKR', 'Gambit Tiriona', 'Jeszcze dziś rano moi zwiadowcy donieśli mi o procesji Kultu Potępionych, która wyruszyła z Cytadeli Lodowej Korony do Katedry Ciemności, niosąc jakiś artefakt.$B$BA teraz dowiaduję się, że może to być serce samego Arthasa... coś, co zawiera ostatnią resztkę jego człowieczeństwa.$B$BTo znak od Światłości. Dopóki taki artefakt istnieje, jest szansa, że Arthas Menethil znów stanie się człowiekiem!$B$BSpotkajmy się przy wejściu do katedry. Koniecznie zdobądź kaptur kultysty – idziemy incognito.', 'Tirion Fordring na Szczycie Krzyżowców chce, żebyś $gzdobył:zdobyła; i $gzałożył:założyła; kaptur akolity kultu, a potem $gspotkał:spotkała; się z nim przy wejściu do Katedry Ciemności, na północny zachód od Cytadeli Lodowej Korony.', '', 'Wróć do najwyższego lorda Tiriona Fordringa na Szczycie Krzyżowców w Lodowej Koronie.', '', 'Gambit Tiriona', '', '', 0),
(13404, 'koKR', 'Oddziały szoku statycznego: Ostrzał', 'To misja krótkiego zasięgu, nad Ostrzałem. Dobra rozgrzewka. $GGotowy:Gotowa;?', 'Kibli Kilohertz chce, żebyś $gzabił:zabiła; 50 żołnierzy piechoty ostrzału, 10 kapitanów ostrzału i 20 czyhających gargulców.', '', 'Wróć do Kibliego Kilohertza w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13406, 'koKR', 'Na tej samej fali: Ostrzał', '$GGotowy:Gotowa; na rozgrzewkę w postaci krótkiej misji bombowej? Rozkazy masz, a nasze bombowce są zaopatrzone i czekają.', 'Inżynier z obrzeży Tezzla chce, żebyś $gzabił:zabiła; 50 żołnierzy piechoty ostrzału, 10 kapitanów ostrzału i 20 czyhających gargulców.', '', 'Wróć do inżynier z obrzeży Tezzli w Aldur\'thar: Bramie Spustoszenia w Lodowej Koronie.', '', '', '', '', 0),
(13418, 'koKR', 'Przygotowania do wojny', 'Hej, ty!$B$BWyglądasz na kogoś, kto ma głowę na karku. Przydałoby się nam w Lodowej Koronie więcej zdolnych do walki.$B$BMożliwe, że $gsłyszałeś:słyszałaś; pogłoski o naszej porażce w natarciu lądowym na lodowiec, ale pozwól, że rozwieję te obawy. Teraz prowadzimy natarcie z pokładu jednego z najbardziej zaawansowanych dzieł inżynierii w Azeroth – Niebołamacza. Horda nie ma żadnych szans, podobnie jak Arthas.$B$BOdezwij się do mnie, gdy będziesz $ggotowy:gotowa; do drogi.', 'Porozmawiaj z oficerem Van Rossemem, by zapewnić sobie przelot na Niebołamacz w Lodowej Koronie, a potem zamelduj się u wielkiego kapitana Justina Bartletta.', '', '', '', '', '', '', 0),
(13419, 'koKR', 'Przygotowania do wojny', 'Hej, ty!$B$BWyglądasz na kogoś, kto ma głowę na karku. Przydałoby się nam w Lodowej Koronie więcej zdolnych do walki.$B$BTo ścierwo z Przymierza wpadło do Lodowej Korony przed nami, nieprzygotowane, i dostało dokładnie to, na co zasłużyło swoją niecierpliwością. My nie spieszyliśmy się, przygotowaliśmy się i wkrótce przypuścimy prawdziwe natarcie z pokładu jednego z najbardziej zaawansowanych dzieł inżynierii w Azeroth – Młota Orgrima. Przymierze nie ma żadnych szans, podobnie jak Arthas.$B$BOdezwij się do mnie, gdy będziesz $ggotowy:gotowa; do drogi i do pomocy.', 'Porozmawiaj z podniebnym grabieżcą Klumem, by zapewnić sobie przelot na Młot Orgrima w Lodowej Koronie, a potem zamelduj się u podniebnego grabieżcy Korma Czarnej Blizny.', '', '', '', '', '', '', 0),
(13481, 'koKR', 'Wynośmy się stąd!', 'Światłość mi sprzyja. Jeszcze nie zginąłem w tym żywym koszmarze, ale jeśli nie zdołam uciec, Plaga mnie zabije i rozerwie moje ciało na części do swojej tutejszej „pracy”.$B$BSam nie dam rady, $N, ale z twoją pomocą może jeszcze dożyję dnia, gdy znów będę walczyć z Plagą.$B$BPomożesz mi uciec, zanim rzeźnicy Plagi przyjdą mnie dobić?', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce, a następnie złóż raport bratu Keltanowi na pokładzie Młota Orgrima.', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce', 'Zamelduj się u brata Keltana na Młocie Orgrima w Lodowej Koronie.', '', '', '', '', 0),
(13482, 'koKR', 'Wynośmy się stąd', 'Światłość mi sprzyja. Jeszcze nie zginąłem w tym żywym koszmarze, ale jeśli nie zdołam uciec, Plaga mnie zabije i rozerwie moje ciało na części do swojej tutejszej „pracy”.$B$BSam nie dam rady, moje dziecko, ale z twoją pomocą może jeszcze dożyję dnia, gdy znów będę walczyć z Plagą.$B$BPomożesz mi uciec, zanim rzeźnicy Plagi przyjdą mnie dobić?', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce, a następnie złóż raport Absalanowi Pobożnemu na pokładzie Niebołamacza.', 'Odeskortuj ojca Kamarosa w bezpieczne miejsce', 'Zamelduj się u Absalana Pobożnego na Niebołamaczu w Lodowej Koronie.', '', '', '', '', 0),
(13592, 'koKR', 'Ćwiczenia polowe śmiałka', 'Turniej to czas, by sprawdzić swoje umiejętności w starciu z równymi sobie, ale nie wolno nam zapominać, że prawdziwy wróg, Plaga, nie będzie czekać. Szlifując umiejętności w walce z innymi, musisz też zachować formę w walce z wrogiem.$B$BUdaj się na tereny na południowy zachód od Doliny Poległych Bohaterów i na północ od Corp\'rethar. Plaga wskrzesza tam poległych bohaterów i obraca ich przeciwko nam. Pokonaj tych sługusów Plagi, oddaj cześć naszym sojusznikom i bądź w gotowości do walki.', 'Sir Marcus Barlowe na Placu Turniejowym Argentu chce, żebyś $gzabił:zabiła; 10 nawróconych bohaterów.', '', 'Wróć do sir Marcusa Barlowe\'a w Lodowej Koronie.', '', '', '', '', 0),
(13593, 'koKR', 'Śmiałek z Wichrogrodu', 'Witaj, $gczempionie:czempionko;. Wieści o twojej sprawności w walce już do mnie dotarły. Czy chcesz dołączyć do turniejowej delegacji Wichrogrodu?$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Wichrogrodu, twój giermek będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z marszałkiem Jacobem Aleriusem, jeśli chcesz dołączyć do śmiałków z Wichrogrodu.', '', '', '', '', '', '', 0),
(13600, 'koKR', 'Godna broń', 'Akurat teraz takiego pecha!$B$BZaginęło moje turniejowe ostrze, a potrzebuję go na pojedynek dziś po południu.$B$BJeden z bardów mówi, że podróżni ofiarowywali niegdyś zimowe hiacynty samotnej dziewicy w zamian za dary. Te hiacynty rosną tylko na lodzie spływającym z Żelaznej Tamy, na północno-zachodniej granicy Lasu Kryształowej Pieśni z Lodową Koroną. Zbierz kwiaty i zanieś je nad jezioro Drak\'Mar w północno-wschodniej części Smoczych Pustkowi, przy granicy z Zul\'Drakiem i Wzgórzami Grizli.', 'Przynieś ostrze Drak\'Mar marszałkowi Jacobowi Aleriusowi na Placu Turniejowym Argentu.', '', 'Wróć do marszałka Jacoba Aleriusa w Lodowej Koronie.', '', '', '', '', 0),
(13603, 'koKR', 'Ostrze godne czempiona', 'Dobra, uczciwa, naostrzona stal może nie wystarczyć do zwycięstwa. Inni zawodnicy używają zaklętych ostrzy i jestem na straconej pozycji, ale nie wszystko stracone.$B$BWe Wzgórzach Grizli krąży stara legenda o dziewicy, którą przeklęto i zamieniono w żabę, by strzegła ostrza, którego od dawna pilnuje. Żyje wśród jeziornych żab na brzegu Jeziora Jesionowego Lasu, tuż na wschód od Posterunku Jesionowego Lasu. Podobno klątwę może zdjąć tylko pocałunek dany z własnej woli. Zanim cokolwiek pocałujesz, posmaruj się tym balsamem, $N. Inaczej złapiesz brodawki.', 'Zdobądź jesionową głownię i przynieś ją marszałkowi Jacobowi Aleriusowi na Placu Turniejowym Argentu.', '', 'Wróć do marszałka Jacoba Aleriusa w Lodowej Koronie.', '', '', '', '', 0),
(13616, 'koKR', 'Ostrze zimy', 'Niech przepadnie ten rycerz śmierci, który złamał mi miecz!$B$BW południowej części Lasu Kryształowej Pieśni, nad wylotem Kryształowego Imadła, znajdziesz Lorda Wieczny Żar. Zabij go i weź z jego zwłok wiecznie żarzący się węgielek.$B$BZanieś go na środek Jeziora Zimowego Oddechu w północnej części Wyjącego Fiordu i użyj go, by uwolnić dziewicę zamkniętą w lodzie. Jest strażniczką pradawnego miecza i odda go temu, kto ją uwolni.$B$BUdowodnij swoją wartość i zdobądź broń, której tak długo strzegła, $N.', 'Marszałek Jacob Alerius na Placu Turniejowym Argentu chce, żebyś $gprzyniósł:przyniosła; mu Ostrze zimy.', '', 'Wróć do marszałka Jacoba Aleriusa w Lodowej Koronie.', '', '', '', '', 0),
(13625, 'koKR', 'Chwytanie wodzy', 'W większości konkurencji turniejowych zawodnicy muszą panować nad wierzchowcem w walce. Żeby oswoić cię z walką na wierzchowcu, w całej północnej części placu turniejowego ustawiliśmy manekiny treningowe.$B$BOdwiedź stajnie przed pawilonem, weź do ręki kopię i dosiądź rumaka quel\'dorei. Zapoznaj się z dostępnymi taktykami i użyj ich, by pokonać trzy różne rodzaje manekinów treningowych.', 'Traf 5 razy Pchnięciem cel do walki wręcz, użyj Łamacza tarcz na 2 odsłoniętych celach do walki dystansowej, użyj Szarży na 2 odsłoniętych celach do szarży, a potem wróć do zwiadowczyni Shalyndrii na Placu Turniejowym Argentu.$B$BJeśli zgubisz kopię, możesz wziąć nową z dowolnego stojaka na kopie przy stajniach albo przy Pawilonie Srebrnego Sojuszu.', '', 'Wróć do zwiadowczyni Shalyndrii w Lodowej Koronie.', 'Użyj Pchnięcia na celu do walki wręcz', 'Użyj Łamacza tarcz na odsłoniętym celu do walki dystansowej', 'Użyj Szarży na odsłoniętym celu do szarży', '', 0),
(13633, 'koKR', 'Czarny Rycerz z Zachodniego Skraju?', 'Bez wątpienia $gsłyszałeś:słyszałaś; niepokojące pogłoski o zawodniku, którego inni nazywają Czarnym Rycerzem. Podobno każdy jeździec, który miał się z nim zmierzyć, przedwcześnie zszedł z tego świata.$B$BOczywiście nie mamy na nic niezbitych dowodów, ale nie zaszkodzi przyjrzeć się przeszłości tego rycerza.$B$BTwierdzi, że wywodzi się z rodziny Cooperów z Zachodniego Skraju. Czy możesz odwiedzić ich dom w zachodniej części Księżycowego Potoku na Zachodnim Skraju? Sprawdź, czy znajdziesz jakiś dowód na jego historię.', 'Zbadaj, ile prawdy jest w tym, co mówi o sobie Czarny Rycerz, i wróć ze swoimi ustaleniami do krzyżowczyni Rhydalli na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13634, 'koKR', 'Czarny Rycerz ze Srebrzystego Boru?', 'Bez wątpienia $gsłyszałeś:słyszałaś; niepokojące pogłoski o zawodniku, którego inni nazywają Czarnym Rycerzem. Podobno każdy jeździec, który miał się z nim zmierzyć, przedwcześnie zszedł z tego świata.$B$BOczywiście nie mamy na nic niezbitych dowodów, ale nie zaszkodzi przyjrzeć się przeszłości tego rycerza.$B$BTwierdzi, że pochodzi z Pola Valgana w Srebrzystym Borze. To małe gospodarstwo na zachodnim brzegu Jeziora Lordamere. Czy możesz odwiedzić to gospodarstwo i dać mi znać, czy w jego historii jest choć ziarno prawdy?', 'Zbadaj, ile prawdy jest w tym, co mówi o sobie Czarny Rycerz, i wróć ze swoimi ustaleniami do krzyżowczyni Rhydalli na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13641, 'koKR', 'Kryształ jasnowidza', 'Skoro wiemy już, że w opowieściach Czarnego Rycerza nie ma ani słowa prawdy, musimy znaleźć sposób, by powiązać go z zamordowanymi rycerzami.$B$BZnam sposób, by ujawnić prawdę o tym, jak zginęli, ale wymaga on rzadkiego materiału. Musimy zdobyć kryształ jasnowidza, który mają tylko wyzwoleni jasnowidze zbierający się przy ruinach nocnych elfów w Opuszczonym Lesie, w środkowej części Lasu Kryształowej Pieśni. Znajdź jednego z tych jasnowidzów, $N, i przynieś mi kryształ, który ma przy sobie.', 'Przynieś kryształ jasnowidza krzyżowczyni Rhydalli na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13643, 'koKR', 'Co mówią umarli', 'Kryształ ujawni prawdę o tym, jak zginęło trzech uczestników turnieju. Zabierz go na cmentarz na wschód od Placu Turniejowego i użyj go przed grobami sir Wendella Balfoura, Loriena Słonecznego Płomienia i Conalla Żelaznego Uchwytu.$B$BJeśli ci ludzie rzeczywiście zostali zamordowani, musimy znaleźć sposób, by powiązać to z Czarnym Rycerzem, zanim znów uderzy. Przyjrzyj się uważnie temu, co pokaże ci kryształ, $N, bo musimy mieć pewność, że te śmierci nie były przypadkowe.', 'Użyj kryształu jasnowidza przy grobach sir Wendella Balfoura, Loriena Słonecznego Płomienia i Conalla Żelaznego Uchwytu, by ustalić, jak zginęli, a potem wróć do krzyżowczyni Rhydalli.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', 'Zbadano śmierć sir Wendella Balfoura', 'Zbadano śmierć Loriena Słonecznego Płomienia', 'Zbadano śmierć Conalla Żelaznego Uchwytu', '', 0),
(13654, 'koKR', 'Coś nie tak z tym giermkiem', 'Codziennie giermek Czarnego Rycerza, Maloric, z wielką ostentacją wyrusza do Lasu Kryształowej Pieśni z toporem na ramieniu. Chce, żebyśmy wierzyli, że rąbie drewno, ale nigdy nie wraca z niczym więcej niż kilkoma gałązkami.$B$BZwykle idzie w stronę ruin na południowy zachód od Lustra Zmierzchu. Spędza tam mnóstwo czasu, nawet jak na giermka, który ma obowiązki wobec swojego rycerza.$B$BZnajdź sposób, by odwrócić jego uwagę albo go obezwładnić, i go przeszukaj. Jeśli coś knuje, dowiemy się.', 'Zdobądź dużą kość udową od szkieletowego drwala i użyj jej, by obezwładnić Malorica. Przeszukaj Malorica w poszukiwaniu dowodów, a potem złóż raport krzyżowczyni Rhydalli na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13663, 'koKR', 'Rozkazy Czarnego Rycerza', 'Musimy się dowiedzieć, kto przysłał Czarnego Rycerza na turniej i co jego pan chce zyskać, zabijając zawodników.$B$BKirin Tor zaoferował pomoc w tej sprawie i przekazał nam coś, co ułatwi poszukiwania.$B$BZanieś tę zaklętą uzdę do obozu Czarnego Rycerza na wschodnim skraju placu turniejowego i użyj jej, by przejąć kontrolę nad gryfem Czarnego Rycerza. Magia uzdy zmusi gryfa, by zaniósł cię do domu jego pana. Przeszukaj go i wróć ze wszystkim, co znajdziesz.', 'Użyj zaklętej uzdy, by przejąć kontrolę nad gryfem Czarnego Rycerza, i leć na nim do celu. Gdy dotrzesz na miejsce, odzyskaj skradzione zaproszenie na turniej i Rozkazy Czarnego Rycerza, a potem zanieś je krzyżowczyni Rhydalli na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', 'Przejęto gryfa Czarnego Rycerza', '', '', '', 0),
(13664, 'koKR', 'Upadek Czarnego Rycerza', 'Musimy położyć kres knowaniom Czarnego Rycerza i pokazać tym, którzy nam się sprzeciwiają, że nie będziemy biernie patrzeć, jak mordowani są nasi czempioni.$B$BTeraz już na pewno podejrzewa, że ktoś depcze mu po piętach. Wyzwij go w biały dzień, gdy nie będzie mógł odmówić ani zabić po cichu, w ciemności, $N.$B$BDo walki użyj mojego szarżownika Argentu. Stoi w stajniach.$B$BPorozmawiaj z giermkiem Cavinem w Kręgu Czempionów. Giermek wezwie Czarnego Rycerza do walki, a ty sprawisz, że odpowie za swoje zbrodnie.', 'Pokonaj Czarnego Rycerza, a potem porozmawiaj z krzyżowczynią Rhydallą na Placu Turniejowym Argentu.', '', 'Wróć do krzyżowczyni Rhydalli na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13665, 'koKR', 'Wielkie starcie', 'Wielkie starcie to najważniejsza z turniejowych konkurencji. Mieszkańcy Wichrogrodu uwielbiają swoich rycerzy i nie mogą się doczekać naszego zwycięstwa w starciu. Dlatego nasi rycerze szlifują umiejętności w walkach z innymi śmiałkami.$B$BRadzę ci zrobić to samo.$B$BIdź do stajni przed pawilonem, weź do ręki kopię, dosiądź stojącego tam rumaka z Elwynn i wyzwij śmiałków. Czekają w Kręgu Śmiałków Przymierza, tuż przed naszym namiotem.$B$B', 'Przynieś 3 znaki śmiałka kapitanowi Josephowi Holleyowi na Placu Turniejowym Argentu.$B$BJeśli zgubisz kopię, możesz wziąć nową z dowolnego stojaka na kopie przy stajniach albo w Pawilonie Srebrnego Sojuszu.', '', 'Wróć do kapitana Josepha Holleya w Lodowej Koronie.', '', '', '', '', 0),
(13666, 'koKR', 'Ostrze godne czempiona', 'Niektórzy czempioni wierzą, że pradawna broń zrodzona w Północnej Grani przyniesie im szczęście w turnieju. Zgodziłem się pomóc im w poszukiwaniach.$B$BWe Wzgórzach Grizli krąży stara legenda o dziewicy, którą przeklęto i zamieniono w żabę, by strzegła ostrza, którego od dawna pilnuje. Żyje wśród jeziornych żab na brzegu Jeziora Jesionowego Lasu, tuż na wschód od Posterunku Jesionowego Lasu. Podobno klątwę może zdjąć tylko pocałunek dany z własnej woli. Zanim cokolwiek pocałujesz, posmaruj się tym balsamem, $N. Inaczej złapiesz brodawki.', 'Zdobądź jesionową głownię i przynieś ją arkaniście Taelisowi na Placu Turniejowym Argentu.', '', 'Wróć do arkanisty Taelisa w Lodowej Koronie.', '', '', '', '', 0),
(13667, 'koKR', 'Turniej Argentu', 'Zaprosiliśmy cię tutaj, byś $gsprawdził:sprawdziła; swoje umiejętności i męstwo w starciu z innymi, którzy dzielnie przeciwstawili się Pladze. Wiele nas dzieliło, ale nadszedł czas, by bohaterowie walczący pod wszystkimi sztandarami skrzyżowali ze sobą ostrza, szykując się na spotkanie z naszym wspólnym wrogiem.$B$BArkanista Taelis reprezentuje na turnieju Srebrny Sojusz – wpisze cię na listę i rozpocznie twoje szkolenie. Znajdziesz go w dużym namiocie Przymierza w północno-wschodniej części placu.', 'Porozmawiaj z arkanistą Taelisem na Placu Turniejowym Argentu, by zapisać się na turniej.', '', '', '', '', '', '', 0),
(13668, 'koKR', 'Turniej Argentu', 'Zaprosiliśmy cię tutaj, byś $gsprawdził:sprawdziła; swoje umiejętności i męstwo w starciu z innymi, którzy dzielnie przeciwstawili się Pladze. Wiele nas dzieliło, ale nadszedł czas, by bohaterowie walczący pod wszystkimi sztandarami skrzyżowali ze sobą ostrza, szykując się na spotkanie z naszym wspólnym wrogiem.$B$BMagister Edien Słoneczna Kotlina reprezentuje na turnieju Słońcobójców – wpisze cię na listę i rozpocznie twoje szkolenie. Znajdziesz go w dużym namiocie Hordy w południowo-wschodniej części placu.$B', 'Porozmawiaj z magistrem Edienem Słoneczną Kotliną na Placu Turniejowym Argentu, by zapisać się na turniej.', '', '', '', '', '', '', 0),
(13669, 'koKR', 'Godna broń', 'Naszym czempionom spodobała się pradawna broń wykuwana tu, w Północnej Grani.$B$BSłyszałem, jak bardowie opowiadali o podróżnych, którzy ofiarowywali zimowe hiacynty samotnej dziewicy w zamian za dary. Te hiacynty rosną tylko na lodzie spływającym z Żelaznej Tamy, na północno-zachodniej granicy Lasu Kryształowej Pieśni z Lodową Koroną. Zbierz kwiaty i zanieś je do kręgu lamp na Jeziorze Drak\'Mar w północno-wschodniej części Smoczych Pustkowi, w pobliżu Zul\'Draku i Wzgórz Grizli. Poproś samotną dziewicę o godne ostrze.', 'Przynieś ostrze Drak\'Mar arkaniście Taelisowi na Placu Turniejowym Argentu.', '', 'Wróć do arkanisty Taelisa w Lodowej Koronie.', '', '', '', '', 0),
(13670, 'koKR', 'Ostrze zimy', 'Giermek wielkiego czempiona Żelaznej Kuźni opowiedział mi ciekawą historię.$B$BW południowej części Lasu Kryształowej Pieśni, nad wylotem Kryształowego Imadła, znajdziesz Lorda Wieczny Żar. Zabij go i weź z jego zwłok wiecznie żarzący się węgielek.$B$BZanieś go na środek Jeziora Zimowego Oddechu w północnej części Wyjącego Fiordu i użyj go, by uwolnić dziewicę zamkniętą w lodzie. Jest strażniczką pradawnego miecza i odda go temu, kto ją uwolni.$B$BUdowodnij swoją wartość i zdobądź broń, której tak długo strzegła, $N.', 'Arkanista Taelis na Placu Turniejowym Argentu chce, żebyś $gprzyniósł:przyniosła; mu Ostrze zimy.', '', 'Wróć do arkanisty Taelisa w Lodowej Koronie.', '', '', '', '', 0),
(13671, 'koKR', 'Ćwiczenia w terenie', 'Turniej to czas, by sprawdzić swoje umiejętności w starciu z równymi sobie, ale nie wolno nam zapominać, że prawdziwy wróg, Plaga, nie będzie czekać. Ucząc się walki na wierzchowcu, nie zapominaj ćwiczyć umiejętności, które przez te wszystkie lata dobrze ci służyły. Pokaż nam, że potrafisz stawić czoła Pladze z honorem i odwagą, a zasłużysz na prawo do udziału w turnieju.$B$BUdaj się w głąb Lodowej Korony i zabijaj wszelkie sługi Plagi, jakie napotkasz, ale trzymaj się z dala od Ostrzału, gdzie zostałbyś $gprzytłoczony:przytłoczona; przewagą wroga.', 'Avareth Szybki Cios na Placu Turniejowym Argentu chce, żebyś $gzabił:zabiła; 8 sług Plagi w Lodowej Koronie. Możesz zabijać Plagę w każdej części Lodowej Korony z wyjątkiem Ostrzału.', '', 'Wróć do Avaretha Szybkiego Ciosu w Lodowej Koronie.', 'Zabici słudzy Plagi w Lodowej Koronie', '', '', '', 0),
(13672, 'koKR', 'Na wysokości zadania', 'Gdy opanujesz umiejętności pretendenta, możesz podjąć próbę pretendenta. Sprawdzi ona twoje umiejętności walki na wierzchowcu i oceni, czy jesteś $ggotowy:gotowa;, by zostać śmiałkiem. Jeśli ją przejdziesz, dołączysz jako śmiałek do delegacji swojej stolicy.$B$BKiedy będziesz $ggotowy:gotowa; rozpocząć próbę, wróć do mnie.', 'Przekaż arkaniście Taelisowi na Turnieju Argentu 15 pieczęci pretendenta na znak, że jesteś $ggotowy:gotowa; podjąć próbę pretendenta.', '', 'Wróć do arkanisty Taelisa w Lodowej Koronie.', '', '', '', '', 0),
(13673, 'koKR', 'Ostrze godne czempiona', 'Niektórzy czempioni wierzą, że pradawna broń zrodzona w Północnej Grani przyniesie im szczęście w turnieju. Zgodziłem się pomóc im w poszukiwaniach.$B$BWe Wzgórzach Grizli krąży stara legenda o dziewicy, którą przeklęto i zamieniono w żabę, by strzegła ostrza, którego od dawna pilnuje. Żyje wśród jeziornych żab na brzegu Jeziora Jesionowego Lasu, tuż na wschód od Posterunku Jesionowego Lasu. Podobno klątwę może zdjąć tylko pocałunek dany z własnej woli. Zanim cokolwiek pocałujesz, posmaruj się tym balsamem, $N. Inaczej złapiesz brodawki.', 'Zdobądź jesionową głownię i przynieś ją magistrowi Edienowi Słonecznej Kotlinie na Placu Turniejowym Argentu.', '', 'Wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13674, 'koKR', 'Godna broń', 'Naszym czempionom spodobała się pradawna broń wykuwana tu, w Północnej Grani.$B$BSłyszałem, jak bardowie opowiadali o podróżnych, którzy ofiarowywali zimowe hiacynty samotnej dziewicy w zamian za dary. Te hiacynty rosną tylko na lodzie spływającym z Żelaznej Tamy, na północno-zachodniej granicy Lasu Kryształowej Pieśni z Lodową Koroną. Zbierz kwiaty i zanieś je do kręgu lamp na Jeziorze Drak\'Mar w północno-wschodniej części Smoczych Pustkowi, w pobliżu Zul\'Draku i Wzgórz Grizli. Poproś samotną dziewicę o godne ostrze.', 'Przynieś ostrze Drak\'Mar magistrowi Edienowi Słonecznej Kotlinie na Placu Turniejowym Argentu.', '', 'Wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13675, 'koKR', 'Ostrze zimy', 'Usłyszałem ciekawą historię od jednego ze śmiałków z Orgrimmaru.$B$BW południowej części Lasu Kryształowej Pieśni, nad wylotem Kryształowego Imadła, znajdziesz Lorda Wieczny Żar. Zabij go i weź z jego zwłok wiecznie żarzący się węgielek.$B$BZanieś go na środek Jeziora Zimowego Oddechu w północnej części Wyjącego Fiordu i użyj go, by uwolnić dziewicę zamkniętą w lodzie. Jest strażniczką pradawnego miecza i odda go temu, kto ją uwolni.$B$BUdowodnij swoją wartość i zdobądź broń, której tak długo strzegła, $N.', 'Magister Edien Słoneczna Kotlina na Placu Turniejowym Argentu chce, żebyś $gprzyniósł:przyniosła; mu Ostrze zimy.', '', 'Wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13676, 'koKR', 'Ćwiczenia w terenie', 'Turniej to czas, by sprawdzić swoje umiejętności w starciu z równymi sobie, ale nie wolno nam zapominać, że prawdziwy wróg, Plaga, nie będzie czekać. Ucząc się walki na wierzchowcu, nie zapominaj ćwiczyć umiejętności, które przez te wszystkie lata dobrze ci służyły. Pokaż nam, że potrafisz stawić czoła Pladze z honorem i odwagą, a zasłużysz na prawo do udziału w turnieju.$B$BUdaj się w głąb Lodowej Korony i zabijaj wszelkie sługi Plagi, jakie napotkasz, ale trzymaj się z dala od Ostrzału, gdzie zostałbyś $gprzytłoczony:przytłoczona; przewagą wroga.', 'Amariel Zaprzysiężony Słońcu na Placu Turniejowym Argentu chce, żebyś $gzabił:zabiła; 8 sług Plagi w Lodowej Koronie. Możesz zabijać Plagę w każdej części Lodowej Korony z wyjątkiem Ostrzału.', '', 'Wróć do Amariela Zaprzysiężonego Słońcu na Placu Turniejowym Argentu w Lodowej Koronie.', 'Zabici słudzy Plagi w Lodowej Koronie', '', '', '', 0),
(13677, 'koKR', 'Chwytanie wodzy', 'W większości konkurencji turniejowych zawodnicy muszą panować nad wierzchowcem w walce. Żeby oswoić cię z walką na wierzchowcu, w całej północnej części placu turniejowego ustawiliśmy manekiny treningowe.$B$BOdwiedź stajnie przed pawilonem, weź do ręki kopię i dosiądź szybkobieżcy Słońcobójców. Poznaj swojego wierzchowca i użyj jego umiejętności, by pokonać trzy różne rodzaje manekinów treningowych.$B', 'Traf 5 razy Pchnięciem cel do walki wręcz, użyj Łamacza tarcz na 2 odsłoniętych celach do walki dystansowej, użyj Szarży na 2 odsłoniętych celach do szarży, a potem wróć do Galathii Jasnego Świtu na Placu Turniejowym Argentu.$B$BJeśli zgubisz kopię, możesz wziąć nową z dowolnego stojaka na kopie przy stajniach albo przy Pawilonie Słońcobójców.', '', 'Wróć do Galathii Jasnego Świtu na Placu Turniejowym Argentu w Lodowej Koronie.', 'Użyj Pchnięcia na celu do walki wręcz', 'Użyj Łamacza tarcz na odsłoniętym celu do walki dystansowej', 'Użyj Szarży na odsłoniętym celu do szarży', '', 0),
(13678, 'koKR', 'Na wysokości zadania', 'Gdy opanujesz umiejętności pretendenta, możesz podjąć próbę pretendenta. Sprawdzi ona twoje umiejętności walki na wierzchowcu i oceni, czy jesteś $ggotowy:gotowa;, by zostać śmiałkiem. Jeśli ją przejdziesz, dołączysz jako śmiałek do delegacji swojej stolicy.$B$BKiedy będziesz $ggotowy:gotowa; rozpocząć próbę, wróć do mnie.', 'Przekaż magistrowi Edienowi Słonecznej Kotlinie na Turnieju Argentu 15 pieczęci pretendenta na znak, że jesteś $ggotowy:gotowa; podjąć próbę pretendenta.', '', 'Wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13679, 'koKR', 'Próba pretendenta', 'Ciężko $gćwiczyłeś:ćwiczyłaś; jako $gpretendent:pretendentka;, $N, a teraz nadszedł czas, by sprawdzić twoje umiejętności walki na wierzchowcu w starciu z wprawnym przeciwnikiem.$B$BWeź do ręki kopię, potem idź do stajni przed pawilonem i dosiądź stojącego tam rumaka quel\'dorei.$B$BW Kręgu Pretendentów po północnej stronie placu turniejowego znajdziesz giermka Davida. Upewni się, że jesteś $ggotowy:gotowa; do walki, i wezwie twojego przeciwnika.$B$BPowodzenia, $N. Niech twój koń stąpa pewnie, a twój cios będzie celny.', 'Porozmawiaj z giermkiem Davidem, by wezwać przeciwnika. Gdy pokonasz śmiałka Argentu, wróć do arkanisty Taelisa na Placu Turniejowym Argentu.$B$BJeśli zgubisz kopię, możesz wziąć nową z dowolnego stojaka na kopie przy stajniach albo w Pawilonie Srebrnego Sojuszu.', '', 'Wróć do arkanisty Taelisa w Lodowej Koronie.', 'Pokonano śmiałka Argentu', '', '', '', 0),
(13680, 'koKR', 'Próba pretendenta', 'Ciężko $gćwiczyłeś:ćwiczyłaś; jako $gpretendent:pretendentka;, $N, a teraz nadszedł czas, by sprawdzić twoje umiejętności walki na wierzchowcu w starciu z doświadczonym przeciwnikiem.$B$BWeź do ręki kopię, potem idź do stajni przed pawilonem i dosiądź szybkobieżcy Słońcobójców.$B$BW Kręgu Pretendentów po północnej stronie placu turniejowego znajdziesz ludzkie dziecko – giermka Davida. Zapyta, czy jesteś $ggotowy:gotowa; do walki, i wezwie twojego przeciwnika.$B$BPowodzenia, $N. Niech twój wierzchowiec stąpa pewnie, a twój cios będzie celny.', 'Porozmawiaj z giermkiem Davidem, by wezwać przeciwnika. Gdy pokonasz śmiałka Argentu, wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu.', '', 'Wróć do magistra Ediena Słonecznej Kotliny na Placu Turniejowym Argentu w Lodowej Koronie.', 'Pokonano śmiałka Argentu', '', '', '', 0),
(13682, 'koKR', 'Zagrożenie z góry', 'Od kiedy $gzdemaskowałeś:zdemaskowałaś; agenta Kultu Potępionych, najwyższy lord Tirion Fordring podwoił straże. Nie wierzy, że kultyści się zatrzymają tylko dlatego, że ich Czarny Rycerz został pokonany.$B$BNasi zwiadowcy na szponach niebios donieśli, że widzieli żmija mrozu imieniem Zimnopaszcza, który prowadzi oddział najeźdźców z kultu. Jeśli ich nie przechwycimy, turniej zostanie zaatakowany. Zwiadowcy widzieli Zimnopaszczę na południowym zachodzie, jak przelatywał nad terenem między Wałem Żelaznej Tamy a Aldur\'thar.', 'Eadric Czysty na Turnieju Argentu chce, żebyś $gpokonał:pokonała; Zimnopaszczę i 3 kultystów bombardierów.', '', 'Wróć do Eadrica Czystego na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13684, 'koKR', 'Śmiałek z Wichrogrodu', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Wichrogrodu, $N. Teraz przedstaw się marszałkowi Jacobowi Aleriusowi, który przewodzi delegacji Wichrogrodu. Jako wielki czempion Wichrogrodu zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z marszałkiem Jacobem Aleriusem na Placu Turniejowym Argentu, by zostać śmiałkiem z Wichrogrodu.', '', '', '', '', '', '', 0),
(13685, 'koKR', 'Śmiałek z Żelaznej Kuźni', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Żelaznej Kuźni, $N. Teraz przedstaw się Lanie Mocnomłot, która przewodzi delegacji Żelaznej Kuźni. Jako wielka czempionka Żelaznej Kuźni zgłosi cię do turnieju w imieniu miasta i będzie nadzorować twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Laną Mocnomłot na Placu Turniejowym Argentu, by zostać śmiałkiem z Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(13688, 'koKR', 'Śmiałek z Gnomoregan', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Gnomoregan, $N. Teraz przedstaw się Ambrose\'owi Iskrobełtowi, który przewodzi delegacji Gnomoregan. Jako wielki czempion gnomów zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Ambrose\'em Iskrobełtem na Placu Turniejowym Argentu, by zostać śmiałkiem z Gnomoregan.', '', '', '', '', '', '', 0),
(13689, 'koKR', 'Śmiałek z Darnassus', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Darnassus, $N. Teraz przedstaw się Jaelyne Wieczornej Pieśni, która przewodzi delegacji Darnassus. Jako wielka czempionka nocnych elfów zgłosi cię do turnieju w imieniu miasta i będzie nadzorować twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Jaelyne Wieczorną Pieśnią na Placu Turniejowym Argentu, by zostać śmiałkiem z Darnassus.', '', '', '', '', '', '', 0),
(13690, 'koKR', 'Śmiałek z Exodaru', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Exodaru, $N. Teraz przedstaw się Colososowi, który przewodzi delegacji Exodaru. Jako wielki czempion draeneiów zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Colososem na Placu Turniejowym Argentu, by zostać śmiałkiem z Exodaru.', '', '', '', '', '', '', 0),
(13691, 'koKR', 'Śmiałek z Orgrimmaru', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Orgrimmaru, $N. Teraz porozmawiaj z Mokrą Miażdżyczaszką, który przewodzi zawodnikom z Orgrimmaru. Jako wielki czempion Orgrimmaru zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Mokrą Miażdżyczaszką na Placu Turniejowym Argentu, by zostać śmiałkiem z Orgrimmaru.', '', '', '', '', '', '', 0),
(13693, 'koKR', 'Śmiałek z Sen\'jin', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Sen\'jin, $N. Teraz porozmawiaj z Zul\'tore\'em, który przewodzi wojownikom z Sen\'jin. Jako wielki czempion trolli zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Zul\'tore\'em na Placu Turniejowym Argentu, by zostać śmiałkiem z Sen\'jin.', '', '', '', '', '', '', 0),
(13694, 'koKR', 'Śmiałek z Gromowych Urwisk', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Gromowych Urwisk, $N. Teraz porozmawiaj z Runokiem Dzikogrzywym, który przewodzi zawodnikom z Gromowych Urwisk. Jako wielki czempion Gromowych Urwisk zgłosi cię do turnieju w imieniu miasta i będzie nadzorował twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Runokiem Dzikogrzywym na Placu Turniejowym Argentu, by zostać śmiałkiem z Gromowych Urwisk.', '', '', '', '', '', '', 0),
(13695, 'koKR', 'Śmiałek z Podmiasta', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Podmiasta, $N. Teraz porozmawiaj z tropicielką śmierci Visceri, która przewodzi delegacji Podmiasta. Jako wielka czempionka zgłosi cię do turnieju w imieniu miasta i będzie nadzorować twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z tropicielką śmierci Visceri na Placu Turniejowym Argentu, by zostać śmiałkiem z Podmiasta.', '', '', '', '', '', '', 0),
(13696, 'koKR', 'Śmiałek ze Srebrnej Luny', '$GUdowodniłeś:Udowodniłaś;, że jesteś $ggodny:godna; walczyć pod sztandarem Srebrnej Luny, $N. Teraz porozmawiaj z Eresseą Pieśnią Brzasku, która przewodzi delegacji Srebrnej Luny. Jako wielka czempionka Srebrnej Luny zgłosi cię do turnieju w imieniu miasta i będzie nadzorować twoje szkolenie i próby jako śmiałka.$B$BWspółpraca z tobą była dla mnie zaszczytem, $N. Życzę ci powodzenia w nadchodzących zawodach.', 'Porozmawiaj z Eresseą Pieśnią Brzasku na Placu Turniejowym Argentu, by zostać śmiałkiem ze Srebrnej Luny.', '', '', '', '', '', '', 0),
(13697, 'koKR', 'Szarża śmiałka', 'Podczas szkolenia na śmiałka będziesz mieć okazję sprawdzić swoje umiejętności w walce ze śmiałkami z innych miast. Choć walki śmiałków nie są formalną częścią zawodów, wyniesiesz z nich cenną wiedzę o stylach walki i słabościach przeciwników.$B$BŚmiałkowie to zadziorna gromada, która rywalizuje między sobą o honor i sławę.$B$BĆwicz jako śmiałek, dopóki nie nabierzesz pewności, że pokonasz każdego, kto stanie ci na drodze, a potem przynieś mi zdobyte pieczęcie.', 'Przynieś 25 pieczęci śmiałka Mokrze Miażdżyczaszce na Placu Turniejowym Argentu.', '', 'Wróć do Mokry Miażdżyczaszki na Placu Turniejowym Argentu w Lodowej Koronie.', '', '', '', '', 0),
(13699, 'koKR', 'Próba śmiałka', 'Już niemal możesz walczyć w imieniu Wichrogrodu w wielkim starciu. Aby udowodnić, że jesteś $ggodny:godna; stanąć w szranki w imieniu naszego miasta, musisz pokonać czempiona Krucjaty Argentu.$B$BIdź do stajni przed pawilonem, weź do ręki kopię i dosiądź wierzchowca. Porozmawiaj z giermkiem Dannym w Kręgu Śmiałków Argentu na zachodnim skraju placu. Giermek wezwie twojego przeciwnika, gdy będziesz $ggotowy:gotowa;.$B$BGdy walka się zakończy, porozmawiamy o jej wyniku.', 'Porozmawiaj z giermkiem Dannym, by wezwać przeciwnika. Gdy pokonasz czempiona Argentu, wróć do marszałka Jacoba Aleriusa na Placu Turniejowym Argentu.$B$BJeśli zgubisz kopię, możesz wziąć nową z dowolnego stojaka na kopie przy stajniach albo w Pawilonie Srebrnego Sojuszu.', '', 'Wróć do marszałka Jacoba Aleriusa w Lodowej Koronie.', 'Pokonano czempiona Argentu', '', '', '', 0),
(13702, 'koKR', 'Narodziny czempiona', 'Gratulacje, $N. $GOpanowałeś:Opanowałaś; wiele rodzajów walki i $gpokonałeś:pokonałaś; wszystkie wyzwania, jakie przed tobą stanęły. Nie ma wątpliwości, że jesteś $ggotowy:gotowa;, by mierzyć się z najlepszymi wojownikami, którzy zebrali się na turnieju – z czempionami stolic.$B$BJustycjariuszka Mariel Prawe Serce prosiła o rozmowę z tobą, $N, i chce oficjalnie zgłosić cię do wielkiego starcia czempionów.', 'Porozmawiaj z justycjariuszką Mariel Prawym Sercem na Placu Turniejowym Argentu.', '', '', '', '', '', '', 0),
(13703, 'koKR', 'Śmiałek z Żelaznej Kuźni', 'Witaj, $gczempionie:czempionko;. Wieści o twojej sprawności w walce już do mnie dotarły. Czy chcesz dołączyć do turniejowej delegacji Żelaznej Kuźni?$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Żelaznej Kuźni, twój giermek będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Laną Mocnomłot, jeśli chcesz dołączyć do śmiałków z Żelaznej Kuźni.', '', '', '', '', '', '', 0),
(13704, 'koKR', 'Śmiałek z Gnomoregan', 'Witaj, $gczempionie:czempionko;. Wieści o twojej sprawności w walce już do mnie dotarły. Delegacji Gnomoregan bardzo przydałby się ktoś taki jak ty.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Gnomoregan, twój giermek będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Ambrose\'em Iskrobełtem, jeśli chcesz dołączyć do śmiałków z Gnomoregan.', '', '', '', '', '', '', 0),
(13705, 'koKR', 'Śmiałek z Exodaru', 'Witaj, $gczempionie:czempionko;. Wieści o twoich czynach już do mnie dotarły. Czy chcesz dołączyć do turniejowej delegacji Exodaru?$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Exodaru, twój giermek będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Colososem, jeśli chcesz dołączyć do śmiałków z Exodaru.', '', '', '', '', '', '', 0),
(13706, 'koKR', 'Śmiałek z Darnassus', 'Witaj, $gczempionie:czempionko;. Wieści o twoich dokonaniach do nas dotarły i bylibyśmy zaszczyceni, gdybyś $gdołączył:dołączyła; do delegacji z Darnassus.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Darnassus, twój giermek będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Jaelyne Wieczorną Pieśnią, jeśli chcesz dołączyć do śmiałków z Darnassus.', '', '', '', '', '', '', 0),
(13707, 'koKR', 'Śmiałek z Orgrimmaru', 'A więc $gzostałeś czempionem:zostałaś czempionką;? W takim razie $gudowodniłeś:udowodniłaś;, że jesteś $ggodnym:godną; przeciwnikiem, i z dumą powitam cię w delegacji Orgrimmaru.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Orgrimmaru, twój siepaczyk będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Mokrą Miażdżyczaszką, jeśli chcesz dołączyć do śmiałków z Orgrimmaru.', '', '', '', '', '', '', 0),
(13708, 'koKR', 'Śmiałek z Sen\'jin', 'Witaj, $gczempionie:czempionko;. Jeśli zechcesz, chętnie powitam cię w turniejowej delegacji Sen\'jin.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Sen\'jin, twój siepaczyk będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Zul\'tore\'em, jeśli chcesz dołączyć do śmiałków z Sen\'jin.', '', '', '', '', '', '', 0),
(13709, 'koKR', 'Śmiałek z Gromowych Urwisk', 'Witaj, $gczempionie:czempionko;. Jako wielki czempion delegacji Gromowych Urwisk będę zaszczycony, mogąc powitać cię w naszych szeregach, jeśli zechcesz.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Gromowych Urwisk, twój siepaczyk będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Runokiem Dzikogrzywym, jeśli chcesz dołączyć do śmiałków z Gromowych Urwisk.', '', '', '', '', '', '', 0),
(13710, 'koKR', 'Śmiałek z Podmiasta', 'Witaj, $gczempionie:czempionko;. Delegacji Porzuconych zawsze przydadzą się tacy jak ty. Dołączysz do nas?$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Podmiasta, twój siepaczyk będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z tropicielką śmierci Visceri, jeśli chcesz dołączyć do śmiałków z Podmiasta.', '', '', 'Podjęto decyzję o zostaniu giermkiem Wichrogrodu', '', '', '', 0),
(13711, 'koKR', 'Śmiałek ze Srebrnej Luny', 'A więc $gzostałeś czempionem:zostałaś czempionką;? W takim razie $gudowodniłeś:udowodniłaś;, że jesteś $ggodnym:godną; przeciwnikiem, i z dumą powitam cię w delegacji Srebrnej Luny.$B$BBędziesz się szkolić i piąć w hierarchii jak wcześniej, ale gdy zostaniesz $gczempionem:czempionką; Srebrnej Luny, twój siepaczyk będzie mógł nieść nasz sztandar do boju.', 'Porozmawiaj ponownie z Eresseą Pieśnią Brzasku, jeśli chcesz dołączyć do śmiałków ze Srebrnej Luny.', '', '', '', '', '', '', 0),
