INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3535, 'koKR', 'Najwyższy lordzie,\n$N z powodzeniem $gpoprowadził:poprowadziła; kampanię przeciw Pladze w Plagoholmie i $gprzygotował:przygotowała; nam drogę do marszu na Lodową Koronę.\nMurarze mają już zapasy potrzebne do rozpoczęcia budowy Twierdzy Sprawiedliwości – i znów zawdzięczamy to pomocy, której $N $gudzielił:udzieliła; nam w Lesie Kryształowej Pieśni.\nZostało tylko jedno, ostatnie wyzwanie: zdobycie Szczytu Krzyżowców. To właśnie tam, w miejscu, gdzie najwięcej wycierpieliśmy, pragnę rozpocząć ten ostatni rozdział.\nCzekamy na twój rozkaz, panie.\nNiech Światłość cię chroni.\n-Gustav', 0),
(3569, 'koKR', 'Doktorze Kohler,\n\nCzarny Rycerz jeszcze nie spełnił swojego zadania. Zabierz jego szczątki z placu turniejowego i swoją sztuką przywróć go do życia. Obrócimy siłę krzyżowców i ich zwolenników przeciwko nim samym.\n\nBierz jeńców i użyj ich dusz, by wzmocnić mojego sługę. Pojmaj krzyżowca Kula, którego towarzysze nazywają lekkomyślnym, i złóż go w ofierze na swoim ołtarzu. Jego duch napełni Czarnego Rycerza straszliwą siłą i mocą. Potem dostarcz mi Czarnego Rycerza.', 0),
(3596, 'koKR', 'Doprawdy rzadkie są „pryzmatyczne” ostrza, wykute połączoną wolą pięciu smoczych stad. Do największych z nich należały siostrzane miecze Quel\'Serrar i Quel\'Delar.\nW swej mądrości smocza królowa Alexstraza podarowała po jednym z tych ostrzy każdemu z elfich ludów Azeroth. Quel\'Serrar miał nosić dzielny wojownik kaldorei, a Quel\'Delar powierzono czempionowi quel\'dorei.\nKażde ostrze przemieniało się w rękach swojego właściciela, dopasowując swą magię do mocnych stron pana...', 0);
