INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(30195, 0, 0, 'koKR', 'Zemścimy się... innym razem!'),
(30404, 1, 0, 'koKR', 'Oto koszmar budzi się na jawie. Dr Okropny przybywa, by siać grozę. Niech cały świat przede mną klęknie, a mnie... nic to nie wzruszy'),
(31254, 0, 2, 'koKR', 'Plotki były prawdziwe! Książę oszalał!'),
(31773, 4, 0, 'koKR', 'Porcja zarazy staje się niestabilna!'),
(31773, 5, 0, 'koKR', 'Środek neutralizujący przestaje działać!'),
(31773, 6, 0, 'koKR', 'Wkrótce trzeba dolać płynu!'),
(31773, 7, 0, 'koKR', 'Dolej płynu NATYCHMIAST!!'),
(32236, 0, 3, 'koKR', 'Nagle dziwnie się czuję. Eee?!'),
(33459, 4, 0, 'koKR', 'Czempion Orgrimmaru się śmieje.'),
(33465, 2, 0, 'koKR', 'Czempion Podmiasta się śmieje.'),
(33465, 3, 0, 'koKR', 'Czempion Podmiasta macha do Spowiedniczki Argentu Paletress i wraca na swoje miejsce.'),
(33467, 3, 0, 'koKR', 'Czempion Srebrnej Luny posyła całusa Spowiedniczce Argentu Paletress.'),
(34102, 32, 0, 'koKR', 'Spowiedniczka Argentu Paletress posyła całusa Czempionowi Srebrnej Luny.'),
(34102, 41, 0, 'koKR', 'Choć może tego nie widać, ten turniej pomaga stworzyć silną, zjednoczoną armię. Gdy będziemy gotowi, oczy krucjaty i wszystkich jej czempionów zwrócą się ku Lodowej Koronie.'),
(34907, 0, 6, 'koKR', '$GZawędrowałeś:Zawędrowałaś; za daleko od swojej wygodnej ziemi, $N.'),
(34947, 0, 6, 'koKR', '$GZawędrowałeś:Zawędrowałaś; za daleko od swojej wygodnej ziemi, $N.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13803, 'koKR', '', 'Zaszczycasz nas swoją obecnością, $n.', 0),
(30032, 'koKR', 'Tak, Król Lisz padnie pod naszą potęgą. Dokonamy ostatecznej zemsty.$B$BAle najpierw dopilnujemy, by zaraza zwana Szkarłatnym Szturmem raz na zawsze zniknęła z tego świata!', '', 0),
(30033, 'koKR', 'Lordzie-dowódco, chcę usłyszeć twoją opowieść.', 'Lordzie-dowódco, chcę usłyszeć twoją opowieść.', 0),
(30034, 'koKR', 'Dobrze, ale na twoim miejscu słuchałbym uważnie, zamiast tylko bezmyślnie kiwać głową.$B$BZaczyna się, jak każda dobra opowieść, od zdrady. Och, to nie nas zdradzono... bynajmniej. Król Lisz wyniósł nas, rycerzy śmierci, ponad wszystkich innych.$B$BTo raczej my zdradziliśmy jego, z pomocą najwyższego lorda Dariona Mograine\'a.$B$BW ostatecznej bitwie przy Kaplicy Świetlistej Nadziei na Plagowiskach, gdy tym prostaczkom zostały chwile do zagłady, Tirion Fordring pomógł Mograine\'owi zerwać władzę Króla Lisza nad nim i nad nami wszystkimi, którzy tam byliśmy.', '', 0),
(30035, 'koKR', '<Lekko kiwasz głową, ale przerywasz ruch, gdy lord-dowódca mruży oczy, po czym podejmuje opowieść.>', '<Lekko kiwasz głową, ale przerywasz ruch, gdy lord-dowódca mruży oczy, po czym podejmuje opowieść.>', 0),
(30037, 'koKR', 'Gdy Król Lisz uciekł w strachu przed Fordringiem dzierżącym Spopielacza, bez trudu odebraliśmy Hebanową Warownię resztkom sił Plagi.$B$BTo jednak nie zakończyło sporu między nami a Szkarłatną Krucjatą.$B$BJak Porzuceni przekonali się na własnej skórze, szkarłatni chyba nie potrafią odróżnić nas od Plagi.$B$BMyślimy samodzielnie, mamy własne pobudki, mamy niemal wszystkie przymioty żywych, a jednak dla nich niczym się nie różnimy od bezmyślnych niewolników Króla Lisza.$B$BMylą się, sądząc, że położymy się i będziemy udawać trupy.', '', 0),
(30038, 'koKR', '$GMyślałem:Myślałam;, że teraz nazywają się Szkarłatnym Szturmem?', '$GMyślałem:Myślałam;, że teraz nazywają się Szkarłatnym Szturmem?', 0),
(30039, 'koKR', 'Lordzie-dowódco, możesz powtórzyć, co mówiłeś wcześniej?', 'Lordzie-dowódco, możesz powtórzyć, co mówiłeś wcześniej?', 0),
(30040, 'koKR', '<Lord-dowódca mierzy cię wzrokiem, po czym ciągnie dalej.>$B$BWłaśnie do tego zmierzałem. Istotnie, gdy wielka generał Abbendis wysadziła swoje wojska w Północnej Grani, zmieniła ich nazwę na Szkarłatny Szturm.$B$BNiedługo potem w Nowym Żagiewiu na Smoczych Pustkowiach zjawił się u niej admirał Barean Zachodni Wiatr. Z wszystkich relacji wynika, że się go nie spodziewała. Ani tego, że podkopie jej autorytet i odbierze jej dowództwo.$B$BZapewne $gmiałeś:miałaś; swój udział w jej śmierci, ale mniejsza z tym. Gdy zginęła, admirał w tajemniczych okolicznościach zniknął i straciliśmy jego ślad.', '', 0),
(30045, 'koKR', 'Dokąd udał się wielki admirał?', 'Dokąd udał się wielki admirał?', 0),
(30046, 'koKR', 'Jak mówiłem, straciliśmy jego ślad, ale jestem pewien, że zdołasz to dla mnie ustalić. Podejrzewam, że jest gdzieś tam na dole, ale szpiedzy, którzy wrócili, nie zdołali go namierzyć nigdzie na wyspie.$B$BPorzuceni z Jadozłości dobrze się spisali, sabotując Nowe Żagiewie, ale siły Szturmu, które tam stacjonują, to zaprawiona w bojach resztka z tamtego miejsca. Niestety, po drodze zdobyli lepszy sprzęt, a także gryfy odebrane jakimś głupcom.$B$BChcę powiedzieć, że to nie będzie przechadzka po wsi, $n, nawet dla ciebie.', '', 0),
(30047, 'koKR', 'W porządku. Kiedy zaczynam?', 'W porządku. Kiedy zaczynam?', 0),
(30048, 'koKR', 'Zaczniemy za chwilę.$B$BChcę tylko, żeby było jasne – nie jesteśmy tu, by ich zmiękczyć. Nie jesteśmy tu, by zadać im jakieś straty. Jesteśmy tu, by położyć kres zarazie, która nazywa się Szkarłatnym Szturmem.$B$BJeśli nie chcesz brać w tym udziału, jeśli brak ci żołądka, odleć teraz. Chcę mieć przy sobie kogoś, kto będzie tu codziennie, aż robota zostanie skończona.$B$BCzy jesteś $gtakim mężczyzną:taką kobietą;, $n?', '', 0),
(30049, 'koKR', 'Skończmy z tym!', 'Skończmy z tym!', 0),
(30050, 'koKR', '<Lord-dowódca szczerzy się w trupim uśmiechu, mierząc cię bacznie wzrokiem od stóp do głów.>$B$BTo chciałem usłyszeć.', '', 0),
(30094, 'koKR', '', 'Pomyśl o całym cierpieniu, jakie szkarłatni sprowadzali przez lata. O torturach, fanatyzmie, morderstwach.$B$BNie pozwolę, by to trwało dalej. A ty?', 0),
(30116, 'koKR', 'Proszę bardzo, mon. Twój własny kościany gryf. A teraz pogadajmy o tym, jak wyruszysz na nim walczyć ze Szturmem!', '', 0),
(30117, 'koKR', 'Niezła opowieść, lordzie-dowódco.', 'Niezła opowieść, lordzie-dowódco.', 0),
(30146, 'koKR', '', 'Nie wiem, gdzie jest wielki admirał. Idź do diabła!', 0),
(30161, 'koKR', 'Arcybiskup Landgren musi wiedzieć! Aaaaaaaaaach.....!', '', 0),
(30223, 'koKR', 'Dobra robota. Miejmy to już za sobą.', '', 0),
(30231, 'koKR', 'Chodź, Landgrenie, wypluj swoją duszę, żebym mógł zadać ci bardzo ważne pytanie.', '', 0),
(30241, 'koKR', 'POWIESZ MI, GDZIE JEST ZACHODNI WIATR, ALBO ZNISZCZĘ TWOJĄ DUSZĘ!', '', 0),
(30244, 'koKR', 'W takim razie nie zostawiasz mi wyboru. Nie powiem, że nie sprawi mi to przyjemności.', '', 0),
(30246, 'koKR', 'Dobrze. Mów!', '', 0),
(30248, 'koKR', 'Ukryta kotlina? Jakież to ciekawe. Spełniłeś swoje zadanie, Landgrenie, ale obawiam się, że tym razem nie będzie dla ciebie zmartwychwstania!', '', 0),
(30251, 'koKR', 'Skoro te nieprzyjemności mamy już za sobą, pomówmy o tym, jak rozprawisz się z wielkim admirałem Zachodnim Wiatrem.', '', 0),
(30265, 'koKR', 'Mroczny tkacz przeszywa cię złowrogim uśmiechem i przybiera zupełnie inną postać.', 'Mroczna tkaczka przeszywa cię złowrogim uśmiechem i przybiera zupełnie inną postać.', 0),
(30266, 'koKR', 'Teraz już wiesz. Teraz musisz zginąć!', 'Teraz już wiesz. Teraz musisz zginąć!', 0),
(30267, 'koKR', 'Nawet w śmierci nie znajdziesz ucieczki!', 'Nawet w śmierci nie znajdziesz ucieczki!', 0),
(30268, 'koKR', 'Pożrę twoją duszę!', 'Pożrę twoją duszę!', 0),
(30269, 'koKR', 'Nie wyjdziesz z tej jaskini $gżywy:żywa;!', 'Nie wyjdziesz z tej jaskini $gżywy:żywa;!', 0),
(30273, 'koKR', 'CO?! Mniejsza z tym. Nawet bez mojej kuli cię zmiażdżę! Ujrzyj moje prawdziwe oblicze i rozpaczaj!', '', 0),
(30275, 'koKR', 'Ech! Za długo tkwiłem w tej słabej skorupce.', '', 0),
(30276, 'koKR', 'Kirel narak! Jestem Mal\'Ganis. JESTEM WIECZNY!', '', 0),
(30277, 'koKR', 'DOŚĆ! Tracę tu czas. Muszę odzyskać siły w moim ojczystym świecie.', '', 0),
(30278, 'koKR', 'Nigdy nie pokonacie Króla Lisza bez moich sił. Zemszczę się... na nim I NA TOBIE!', '', 0),
(30279, 'koKR', '$GMyślałeś:Myślałaś;, że tak po prostu pozwolę ci się zabić?', '', 0),
(30281, 'koKR', 'Jak mnie $gznalazłeś:znalazłaś;? Landgren się wygadał?', '', 0),
(30416, 'koKR', 'Marnujesz czas. Idź zabijać sługi Króla Lisza, $N!', '', 0),
(30417, 'koKR', 'Jak idzie ci walka z Królem Liszem, $N?', '', 0),
(30418, 'koKR', 'Dobrze cię znowu widzieć, $n. Jakże można zapomnieć $gtego, który ocalił:tę, która ocaliła; życie mojej siostry?', '', 0),
(30434, 'koKR', 'Nie pokazuj się tu, dobrze? Udaję, że wciąż jestem pod kontrolą Króla Lisza!', '', 0),
(30458, 'koKR', '', 'Jak śmiesz?! Gdzie jest baron Sliver? Chcę z nim pomówić!', 0),
(30459, 'koKR', 'Mrmrmmrmrmrmrm... mrmrmrmr?!', '', 0),
(30460, 'koKR', 'Wstręciuch wolny? Wstręciuch kochać $n!', '', 0),
(30461, 'koKR', 'Miażdżyć... kaleczyć... NISZCZYĆ!', '', 0),
(30462, 'koKR', '', 'Kto śmie przerywać mój rytuał?', 0),
(30463, 'koKR', 'Mrrfrmrfrmrrrrr!', '', 0),
(30465, 'koKR', 'To ty mieszasz nam szyki? To będzie łatwe.', '', 0),
(30647, 'koKR', 'Musimy bez przerwy uderzać na Jotunheim. Nie dawać im chwili wytchnienia, nie dawać chwili snu i nigdy nie przyjmować kapitulacji!$B$BTirion Fordring z całą mocą Spopielacza i Krucjatą Argentu za plecami nie może marzyć o tym, czego ty dokonujesz!$B$BA teraz rób swoje i to szybko, $n. Za dużo się dzieje, by tracić czas na pogaduszki.', '', 0),
(30660, 'koKR', 'Hebanowy Miecz ma wobec ciebie dług za pomoc w zdobyciu Krypty Cienia. Szczęście, że cię mamy.$B$BGdy Przymierze i Horda walczą ze sobą, odwalając za Króla Lisza jego robotę, my pozostaniemy skupieni na naszym zadaniu.$B$BTam, gdzie Krucjata Argentu może się zawahać i dwa razy się zastanowić, jak najlepiej zmiażdżyć wroga, my nie będziemy mieć takich moralnych rozterek.$B$BBędziesz naszym narzędziem zemsty, $n.', '', 0),
(30693, 'koKR', 'No chodź, nie mam całego dnia!', '', 0),
(30694, 'koKR', 'Zabicie cię nie przybliży mnie do wykazania się w Valhalas, ale przynajmniej będzie zabawnie!', '', 0),
(30695, 'koKR', 'Jeśli szukasz śmierci, to ją $gznalazłeś:znalazłaś;!', '', 0),
(30696, 'koKR', 'Dla ciebie szybka podróż do zaświatów, a dla mnie trochę śmiechu. Uczciwa wymiana!', '', 0),
(30712, 'koKR', 'Z rozkazu księcia Lankrala, dowódcy Rycerzy Hebanowego Miecza, Pogromcy Plagi i Zdobywcy Krypty Cienia, masz złożyć broń. Jaka jest twoja odpowiedź?', 'Z rozkazu księcia Lankrala, dowódcy Rycerzy Hebanowego Miecza, Pogromcy Plagi i Zdobywcy Krypty Cienia, masz złożyć broń. Jaka jest twoja odpowiedź?', 0),
(30713, 'koKR', 'Moja odpowiedź? Oto moja odpowiedź, mały posłańcu!', '', 0),
(30719, 'koKR', 'Jeśli nie masz nic innego do roboty, zabijaj te stwory!', '', 0),
(30724, 'koKR', 'Potrafię o siebie zadbać, $n.', '', 0),
(30741, 'koKR', 'A TY co tu robisz?$B$BPilnuj tylko, żeby nie wchodzić mi w drogę. Nie odszedłem ze Szkarłatnego Szturmu po to, żeby rozpraszał mnie ktoś taki jak ty!', '', 0),
(30742, 'koKR', 'Wyzywam cię na pojedynek, szkarłatna szumowino!', 'Wyzywam cię na pojedynek, szkarłatna szumowino!', 0),
(30746, 'koKR', 'Śmiesz mnie DOTKNĄĆ?! Nie przeszkodzisz mi w wykazaniu się przed Królem Liszem!', '', 0),
(30750, 'koKR', '', 'Posmakuj mojej stali, $gchłopczyku:dziewczynko;!', 0),
(30752, 'koKR', '', 'Nie zawracaj mi głowy, szkodniku. Przyglądam się nieudolnej walce tych tak zwanych wojowników.$B$BPokonam ich wszystkich, a wtedy dostąpię zaszczytu służby Królowi Liszowi.', 0),
(30753, 'koKR', '$GSłyszałem:Słyszałam;, że wrykulki w ogóle nie umieją walczyć. Jeśli chcesz udowodnić, że się mylę, spróbuj.', '$GSłyszałem:Słyszałam;, że wrykulki w ogóle nie umieją walczyć. Jeśli chcesz udowodnić, że się mylę, spróbuj.', 0),
(30821, 'koKR', '', 'Dobrze walczysz, maleńka istoto. Tym razem przegrałam. Zapewniam cię, że jeszcze się spotkamy. A wtedy będę lepiej przygotowana!', 0),
(30822, 'koKR', '', 'Grrrrrrrr! Rozwalę ci kolana!', 0),
(30823, 'koKR', '', 'Też jesteś tu, żeby wykazać się przed Królem Liszem?$B$BTo trochę archaiczne, nie sądzisz? Walczyć i przeżyć?', 0),
(30824, 'koKR', '', 'Hej, znam cię! Chyba to tobie zawdzięczam, że tu jestem. Ten wypadek z teleportem to najlepsze, co mnie w życiu spotkało.$B$BJeśli wrócisz do Boreańskiej Tundry, przekaż mojej grzecznej, kujonowatej sobowtórce, że nieźle się wybiłam!', 0),
(30825, 'koKR', 'Przykro mi, Tinky, ale nie mogę sobie pozwolić, żebyś mnie rozpraszała, gdy robię tu to, co trzeba.', 'Przykro mi, Tinky, ale nie mogę sobie pozwolić, żebyś mnie rozpraszała, gdy robię tu to, co trzeba.', 0),
(30828, 'koKR', '', 'JUHUUU!!!', 0),
(30856, 'koKR', 'Onu\'zun cię zabić na śmierć!', '', 0),
(30857, 'koKR', 'Onu\'zun tu przyjść wyzwać wrykulów i piąć się w szeregach.$B$BA jak Onu\'zun walczyć w Valhalas i wygrać, Onu\'zun pracować dla Króla Lisza!', '', 0),
(30858, 'koKR', 'Mam dla ciebie złe wieści, Onu\'zunie: będę $gmusiał:musiała; przerwać twoje marzenia!', 'Mam dla ciebie złe wieści, Onu\'zunie: będę $gmusiał:musiała; przerwać twoje marzenia!', 0),
(30919, 'koKR', '', 'Kiedyś miałam dom w bujnych lasach Quel\'Thalas. Kiedyś miałam rodzinę, męża... dzieci. Kiedyś żyłam i byłam jednością ze światem. Król Lisz odebrał mi to wszystko w mgnieniu oka.$B$BChoć nie mam mocy, by uderzyć wprost w niego, odpłacę mu się po trzykroć!', 0),
(30976, 'koKR', 'Niech moc cię wspiera, $N. Niech Plaga poczuje furię miliona zagubionych dusz!', 'Niech moc cię wspiera, $N. Niech Plaga poczuje furię miliona zagubionych dusz!', 0),
(30977, 'koKR', 'Chwała i siła tobie, $N. Błogosławię cię całą siłą, jaka mi pozostała. Oby ten koszmar wkrótce się skończył!', 'Chwała i siła tobie, $N. Błogosławię cię całą siłą, jaka mi pozostała. Oby ten koszmar wkrótce się skończył!', 0),
(30978, 'koKR', 'Niech mądrość wieków spłynie na ciebie, $gszlachetny:szlachetna; $N.', 'Niech mądrość wieków spłynie na ciebie, $gszlachetny:szlachetna; $N.', 0),
(30980, 'koKR', 'Dziękuję i żegnaj, przyjacielu. Muszę wrócić do Awangardy Argentu.', 'Dziękuję i żegnaj, przyjacielu. Muszę wrócić do Awangardy Argentu.', 0),
(31004, 'koKR', 'Król Lisz szybko zareagował na wyłom. Szybciej, niż się spodziewałem.', '', 0),
(31005, 'koKR', 'Masz do czynienia z istotą, która nosi w sobie świadomość najprzebieglejszych, najinteligentniejszych i najbardziej bezwzględnych osób, jakie kiedykolwiek żyły.', '', 0),
(31006, 'koKR', 'Król Lisz nie przypomina żadnego wroga, z jakim się dotąd mierzyłeś, najwyższy lordzie. Choć pokonałeś go na świętej ziemi Kaplicy Świetlistej Nadziei, teraz stąpasz po jego włościach.\n', '', 0),
(31007, 'koKR', 'Nie możesz wygrać. Nie w ten sposób...\n', '', 0),
(31008, 'koKR', 'Co mam według ciebie zrobić, Darionie?', '', 0),
(31009, 'koKR', 'Nic. Nic nie możesz zrobić, póki Światłość cię wiąże. Kontroluje cię całkowicie, przykuwa cię do ziemi swoimi cnotami.', '', 0),
(31010, 'koKR', 'Waż słowa, rycerzu śmierci. Stoisz pośród oddanych sług Światłości.', '', 0),
(31012, 'koKR', 'Spójrz na pole bitwy, najwyższy lordzie. Król Lisz całkowicie powstrzymał twoje natarcie i zyskał przewagę!', '', 0),
(31013, 'koKR', 'Wyłom, który zrobiłeś, został zasklepiony nerubiańską pajęczyną niemal tak szybko, jak go otwarto.', '', 0),
(31014, 'koKR', 'Twoi żołnierze służą za żywe tarcze chroniące przed ostrzałem artyleryjskim w Dolinie Ech, dzięki czemu siły Króla Lisza mogą bez przeszkód atakować twoją bazę.', '', 0),
(31015, 'koKR', 'Król Lisz zna twoje granice, najwyższy lordzie. Wie, że nie otworzysz ognia do własnych ludzi. Czy nie rozumiesz? On nie ma granic. Żadnych zasad, których musiałby przestrzegać.\n', '', 0),
(31016, 'koKR', 'Zrobimy to z honorem, Darionie. Nie zniżymy się do poziomu Plagi, by zwyciężyć. Stalibyśmy się wtedy nie lepsi od potwora, którego chcemy zniszczyć!', '', 0),
(31017, 'koKR', 'W takim razie przegrałeś, najwyższy lordzie.\n', '', 0),
(31065, 'koKR', 'Co ci chodzi po głowie, chłopcze?', '', 0),
(31070, 'koKR', 'Gaj Wszechpieśni, Dalforsie. Myślę o tym, jaki był piękny, zanim Arthas przeciął go pasem śmierci...', '', 0),
(31090, 'koKR', 'Doktor powierzył mi plany Nergelda, naszego mięsnego olbrzyma zszytego w całości z wargulów! Będzie to najpotężniejszy twór swego rodzaju, a stworzymy cały ich legion, by zniszczyć wasze żałosne siły!', '', 0),
(31114, 'koKR', 'Dziękuję, przyjacielu, ale jeszcze nie jesteśmy bezpieczni!', 'Dziękuję, przyjacielu, ale jeszcze nie jesteśmy bezpieczni!', 0),
(31115, 'koKR', 'Uciekajmy stąd! Szybko!', 'Uciekajmy stąd! Szybko!', 0),
(31119, 'koKR', '$GPrzyszedłeś:Przyszłaś; po plany doktora! Znajdziesz tu tylko śmierć!', '', 0),
(31120, 'koKR', 'Gdy wskakujesz do Nergelda, gnijące mięso konstruktu ożywa.', '', 0),
(31121, 'koKR', 'Szykują wielki atak! Musimy ostrzec najwyższego lorda Fordringa!', 'Szykują wielki atak! Musimy ostrzec najwyższego lorda Fordringa!', 0),
(31122, 'koKR', 'Szybciej, $gbohaterze:bohaterko;! Musimy wrócić do Awangardy Argentu i ostrzec ich przed nadciągającym atakiem!', 'Szybciej, $gbohaterze:bohaterko;! Musimy wrócić do Awangardy Argentu i ostrzec ich przed nadciągającym atakiem!', 0),
(31123, 'koKR', 'Są ich setki! Może tysiące! Zaatakują w każdej chwili! Jestem tego pewien!', 'Są ich setki! Może tysiące! Zaatakują w każdej chwili! Jestem tego pewien!', 0),
(31124, 'koKR', 'Gdyby nie ty, na pewno bym zginął!', 'Gdyby nie ty, na pewno bym zginął!', 0),
(31130, 'koKR', 'Dziękuję ci, $gbohaterze:bohaterko;.', 'Dziękuję ci, $gbohaterze:bohaterko;.', 0),
(31132, 'koKR', '%s rozpada się na kawałki.', '', 0),
(31134, 'koKR', 'KTO ŚMIE?! ZEDRĘ CI MIĘSO Z KOŚCI, NAWET JEŚLI BĘDĘ MUSIAŁ ZNISZCZYĆ NERGELDA, ŻEBY SIĘ DO CIEBIE DOBRAĆ!', '', 0),
(31173, 'koKR', 'POWSTANĘ ZNOWU, A WTEDY SIĘ ZEMSZCZĘ!', '', 0),
(31174, 'koKR', 'Zostaw mnie z moim wstydem.', '', 0),
(31208, 'koKR', 'Znaleźliśmy te protosmoki w Brązowej Smoczej Świątyni na Smoczych Pustkowiach. Od razu wiedzieliśmy, że to nasi pobratymcy – nasza krew sprzed wieków.$B$BWybacz, $N. Pewnie nic z tego nie rozumiesz. Jestem Penumbrius z Brązowego Stada. Ta postać jest po prostu wygodna. Znacznie łatwiej porozumiewać się ze śmiertelnymi i żyć pośród nich w śmiertelnej powłoce.$B$BJak mogę ci pomóc?\n', '', 0),
(31209, 'koKR', 'Miecz Bethoda?!! Dobrze, przyjmuję twoje wyzwanie. Ale najpierw musisz pokonać moich czempionów. Volgurze! Zgnieć tego robaka!', '', 0),
(31211, 'koKR', 'Brito, zrób z tego cherlaka poduszkę na szpilki!', '', 0),
(31212, 'koKR', 'Może i $gpokonałeś:pokonałaś; moich czempionów. Ale ja to zupełnie inna sprawa.', '', 0),
(31213, 'koKR', 'Módl się do swoich bogów o szybką śmierć.', '', 0),
(31312, 'koKR', 'Mrfrrmrfrmrrr!$B$B<Fantom odchrząkuje.>$B$BTak?', '', 0),
(31342, 'koKR', '', 'Mięsarnia to serce produkcji ghuli, plugastw i mięsnych olbrzymów Plagi. Jeśli zdołamy ją zniszczyć, Król Lisz bardzo osłabnie.', 0),
(31369, 'koKR', '', 'Spotkanie bohaterów takich jak ty w tej zapomnianej krainie to zawsze przyjemność. Czy mogę ci jakoś pomóc?', 0),
(31372, 'koKR', 'Mnie również miło cię poznać, arcydruidko. Wykonuję zadanie dla Tiriona i mam mało czasu. Czy mogę prosić o portal do Gaju Luny?', 'Mnie również miło cię poznać, arcydruidko. Wykonuję zadanie dla Tiriona i mam mało czasu. Czy mogę prosić o portal do Gaju Luny?', 0),
(31373, 'koKR', '', 'Oczywiście! Idź z błogosławieństwem Eluny.', 0),
(31380, 'koKR', '', 'Witaj. Nie mogłam nie usłyszeć waszej rozmowy. Pozwól, że ci pomogę.', 0),
(31384, 'koKR', 'Bez ciebie nie dalibyśmy rady, $gpanie:pani;.', 'Bez ciebie nie dalibyśmy rady, $gpanie:pani;.', 0),
(31385, 'koKR', 'Oto $gbohater:bohaterka; Awangardy!', 'Oto $gbohater:bohaterka; Awangardy!', 0),
(31386, 'koKR', 'Zaszczycasz nas swoją obecnością, $n.', 'Zaszczycasz nas swoją obecnością, $n.', 0),
(31388, 'koKR', 'Dziękuję, $n. Z głębi serca. Dziękuję.', 'Dziękuję, $n. Z głębi serca. Dziękuję.', 0),
(31389, 'koKR', 'Wzywaj mnie, kiedy tylko zechcesz, $n.', 'Wzywaj mnie, kiedy tylko zechcesz, $n.', 0),
(31393, 'koKR', 'Nie możemy tracić skupienia. Zatracenie się w chwili mogłoby nas narazić na niebezpieczeństwo. Niestety, żołnierze potrzebują wytchnienia od tego szaleństwa.$B$BCiesz się zwycięstwem, $n. Gdyby nie ty, moglibyśmy stracić Awangardę.', '', 0),
(31437, 'koKR', 'To, co teraz robię dla Krucjaty Argentu, należy postrzegać wyłącznie jako wypełnienie zobowiązania. Spłatę, jeśli wolisz. Najwyższy lord wyrwał mnie ze szponów Króla Lisza i otworzył przed nami wszystkimi drogę do zbawienia. Trzeba jednak zrozumieć, że nasze metody się różnią – i to bardzo. Ja i Rycerze Hebanowego Miecza pomożemy Krucjacie Argentu położyć fundamenty w Lodowej Koronie, a potem nasze drogi się rozejdą. Dług zostanie spłacony w całości.$B$BCzeka nas inne przeznaczenie.', '', 0),
(31438, 'koKR', 'Nie ma wątpliwości, że ci krzyżowcy przysparzają nam wielu niewygód, $gbracie:siostro;. Ale czym jest poświęcenie bez bólu? $GByłeś:Byłaś; ze mną przy Kaplicy Świetlistej Nadziei. $GWidziałeś:Widziałaś; wiele wielkich poświęceń. Jesteśmy tu, by spłacić dług wobec najwyższego lorda. Spłacić w całości za jego poświęcenie.$B$BGdy Krucjata Argentu umocni się w murach Lodowej Korony, odejdziemy. Czeka nas inne przeznaczenie.', '', 0),
(31491, 'koKR', 'W głębi oka wiruje prastara magia. Przyprawia cię o zawrót głowy, jakbyś w każdej chwili $gmógł:mogła; wpaść w jego tęczówkę i spadać bez końca.', '', 0),
(31492, 'koKR', 'Chwyć Oko Króla Lisza i skup na nim swoją wolę, by wypatrzyć ważne informacje.', 'Chwyć Oko Króla Lisza i skup na nim swoją wolę, by wypatrzyć ważne informacje.', 0),
(31503, 'koKR', 'Wrykul spoczywa spokojnie w magicznym śnie.', '', 0),
(31505, 'koKR', 'Obudź śpiącego mjordina, by sprawdzić, czy to naprawdę prastary bohater Iskalder.', 'Obudź śpiącego mjordina, by sprawdzić, czy to naprawdę prastary bohater Iskalder.', 0),
(31540, 'koKR', 'Walcz teraz ze mną, $n! Zabij Iskaldera!', '', 0),
(31554, 'koKR', 'Łatek już nie dać się rozcinać i zszywać!', '', 0),
(31556, 'koKR', 'Łatek zemścić się na doktorze Sabnoku!', '', 0),
(31569, 'koKR', 'Ucztujcie, me dzieci! Ucztujcie na ciałach żywych!', '', 0),
(31597, 'koKR', 'Śmiesz mnie wyzywać? Nie $gzasłużyłeś:zasłużyłaś; na to prawo!', '', 0),
(31599, 'koKR', 'Vardmadra?! Czy to Król Lisz osobiście cię przysłał?', '', 0),
(31600, 'koKR', 'Dobrze. Rozprawię się z tymi stworami. To tylko drobna niedogodność. Szykuj się na śmierć!', '', 0),
(31601, 'koKR', 'Safirdrangu, niech poczują chłód Lodowej Korony!', '', 0),
(31608, 'koKR', 'Dla mnie?', '', 0),
(31609, 'koKR', 'Prezent?', '', 0),
(31610, 'koKR', 'Do czego bomba?', '', 0),
(31611, 'koKR', 'Chcieć, żebym gdzieś zanieść?', '', 0),
(31612, 'koKR', 'Ja nie pewny, czy to bezpieczne, mały fantomie.', '', 0),
(31613, 'koKR', 'To nie tu.', '', 0),
(31614, 'koKR', 'Czego mały fantom chcieć?', '', 0),
(31615, 'koKR', 'To nieładnie!', '', 0),
(31624, 'koKR', 'Niebołamacz patroluje Lodową Koronę. Nie znajdziesz lepszego okrętu w całym świecie.', '', 0),
(31625, 'koKR', 'Zabierz mnie na okręt.', 'Zabierz mnie na okręt.', 0),
(31626, 'koKR', 'Młot Orgrima jest gotów do uderzenia w Lodowej Koronie. Nie znajdziesz lepszego statku.', '', 0),
(31627, 'koKR', 'STAĆ! Na kolana, głupcy, to Król Lisz!', '', 0),
(31635, 'koKR', 'Ale, mój panie...?', '', 0),
(31637, 'koKR', 'GIŃCIE, PSY!', '', 0),
(31661, 'koKR', 'Krwistoczerwona toń w oku wiruje, zdradzając obrazy gromadzącej się armii Plagi. Oko zdaje się cię przyciągać, wdzierając się w twój umysł, aż instynktownie się cofasz. W obecności tego przedmiotu czujesz się bardzo nieswojo.', '', 0),
(31674, 'koKR', '', 'Czegokolwiek chcesz, mów szybko.', 0),
(31719, 'koKR', '<Przejmij przez oko kontrolę nad strażnikiem eidolonów.>', '<Przejmij przez oko kontrolę nad strażnikiem eidolonów.>', 0),
(31742, 'koKR', '', 'Wielu poległo w Valhalas, a ich zwłoki świadczą o sile naszych obyczajów.$B$BCzy i twoje kości zaścielą to miejsce honoru i bitwy, $n?', 0),
(31743, 'koKR', 'Powinienem zabić cię na miejscu!$B$BPowiedz, co masz do powiedzenia w tej swojej bezsensownej paplaninie, i znikaj!', '', 0),
(31744, 'koKR', '', 'Valhalas jest twoje – możesz tu zwyciężyć albo zginąć, $n. Ale cokolwiek zrobisz, nie opuszczaj areny. Ucieczka oznacza porażkę i hańbę.', 0),
(31745, 'koKR', '', '$n i $gjego:jej; towarzysze broni zgodzili się stanąć do honorowej walki w świętych granicach Valhalas.', 0),
(31746, 'koKR', '', 'Taka bitwa może mieć tylko jeden koniec: śmierć jednej ze stron. Niech $n dowiedzie swej wartości na kościach obcych, którzy padli tu wcześniej!', 0),
(31753, 'koKR', '', 'Nie byliście gotowi!', 0),
(31755, 'koKR', '', '$n $gpokonał:pokonała; poległych bohaterów dawnych bitew Valhalas. To dopiero początek, ale na razie wystarczy.', 0),
(31756, 'koKR', 'Polegli bohaterowie Valhalas wychodzą z ziemi, by znów stanąć do walki!', '', 0),
(31757, 'koKR', '', 'Nie $gdowiodłeś:dowiodłaś; jeszcze, że jesteś $ggodny:godna; rzucić wyzwanie w Valhalas, $n.$B$BWróć, gdy zdobędziesz sobie imię.', 0),
(31758, 'koKR', '', 'Wielu poległo w Valhalas, a ich zwłoki świadczą o sile naszych obyczajów.$B$BCzy i twoje kości zaścielą to miejsce honoru i bitwy, $n?', 0),
(31770, 'koKR', '', '$n $gprzyjął:przyjęła; wyzwanie Khit\'rixa Mrocznego Mistrza. Niech bogowie okażą $gmu:jej; litość, bo Khit\'rix z pewnością nie okaże.', 0),
(31771, 'koKR', '', 'Przygotuj się. Khit\'rix wkroczy do Valhalas od południowego wschodu. Pamiętaj, nie opuszczaj kręgu, bo przegrasz walkę.', 0),
(31820, 'koKR', '', '$n i $gjego:jej; drużyna pokonali Khit\'rixa Mrocznego Mistrza. Niech padnie kolejne wyzwanie!', 0),
(31826, 'koKR', 'Dzięki Światłości za kolejną szansę. I dziękuję tobie, $n.', '', 0),
(31827, 'koKR', 'Gdyby nie twoja pomoc, byłbym skazany na nieżycie pośród makabrycznych tworów Króla Lisza.', '', 0),
(31828, 'koKR', 'Na porządne podziękowania przyjdzie czas później, ale bitwa wciąż trwa!', '', 0),
(31835, 'koKR', '', 'Wiedziałam, że przyjdziesz.', 0),
(31852, 'koKR', '', 'Masz w sobie trochę ducha walki. Jestem pod wrażeniem.', 0),
(31853, 'koKR', '', 'Dobra walka...', 0),
(31858, 'koKR', '', 'Witaj w świecie nieżywych.', 0),
(31885, 'koKR', '', 'Nadchodzi Jatka! Pamiętajcie, cokolwiek się stanie, NIE opuszczajcie kręgu bitewnego, bo zdyskwalifikuję was całą grupą.', 0),
(31892, 'koKR', '', 'Sigrid Zrodzona z Lodu wróciła na wyżyny Jotunheim, a jej przeciwnikiem znów jest $n. Podczas ostatniego spotkania $n $gpokonał:pokonała; ją w osobistym pojedynku. Zobaczmy, jak skończy się to starcie.', 0),
(31921, 'koKR', '', '$n po raz drugi $gpokonał:pokonała; Sigrid Zrodzoną z Lodu. No, tym razem z pomocą przyjaciół, ale wygrana to wygrana!', 0),
(31930, 'koKR', '', 'Z trzewi Podziemnych Sal nadchodzi Jatka. $GOdważny i nierozważny:Odważna i nierozważna; $n $gprzyjął:przyjęła; wyzwanie. $GOn:Ona; i $gjego:jej; grupa są gotowi stawić czoła potworności.', 0),
(31931, 'koKR', '', 'Okropieństwo zwane Jatką przestało istnieć. Czyżby $n $gbył naprawdę godzien:była naprawdę godna; walki w Valhalas? Zobaczymy.', 0),
(31932, 'koKR', 'Uhhh.... Nie... trać na mnie czasu.$b$bTo... mój koniec...', 'Uhhh.... Nie... trać na mnie czasu.$b$bTo... mój koniec....', 0),
(31933, 'koKR', 'Zbieraliśmy... informacje... o Pladze.$b$bPojawiły się siły Przymierza...$b$bSchowaliśmy się... czekaliśmy, aż zaatakują bramę... a potem uderzyliśmy od tyłu.$b$bWzięci w kleszcze... między nami... a Plagą... nie wytrzymali....$b$b$GBracie:Siostro;... to było... wspaniałe.', 'Zbieraliśmy... informacje... o Pladze.$b$bPojawiły się siły Przymierza...$b$bSchowaliśmy się... czekaliśmy, aż zaatakują bramę... a potem uderzyliśmy od tyłu.$b$bWzięci w kleszcze... między nami... a Plagą... nie wytrzymali....$b$b$GBracie:Siostro;... to było... wspaniałe.', 0),
(31934, 'koKR', 'Trzymaj się, przyjacielu. Powiedz mi, co się tu stało.', 'Trzymaj się, przyjacielu. Powiedz mi, co się tu stało.', 0),
(31938, 'koKR', '', 'Spójrz na południowy wschód, a gdy than się pokaże, zobaczysz go na podwyższeniu obok Gjonnera Bezlitosnego. Pozwól mu zejść. Nie opuszczaj kręgu Valhalas.', 0),
(31939, 'koKR', '', 'Than Banahogg wraca do Valhalas po raz pierwszy od wieków, by dowieść, że tylko wrykule są godni walczyć w jego świętym kręgu. Czy $n udowodni mu, że się myli?', 0),
(31940, 'koKR', '', '$n i $gjego:jej; towarzysze broni pokonali thana Banahogga, Cios Śmierci. Przed $gnim:nią; już tylko jedno wyzwanie. Kto to będzie?', 0),
(31941, 'koKR', 'Niech błogosławieństwo Światłości spłynie na ciebie za pomoc w potrzebie, $n.', '', 0),
(31942, 'koKR', 'Mam już dość tego miejsca. Ruszajmy.', '', 0),
(31943, 'koKR', 'Tobie zawdzięczam życie. Wrócę do towarzyszy i rozgłoszę wieść o twojej odwadze. Walcz z Plagą z całych sił, a my staniemy u twego boku.', '', 0),
(31944, 'koKR', 'Musisz powiedzieć moim braciom, że żyję.', '', 0),
(31945, 'koKR', '', 'Stało się nie do pomyślenia... $n $gzabił:zabiła; księcia Sandovala!', 0),
(31946, 'koKR', '', 'Pokonując go, $gon:ona; i $gjego:jej; towarzysze broni dowiedli, że są godni walki w tym najświętszym miejscu wrykulskiego honoru.', 0),
(31947, 'koKR', 'Czas sądu jest bliski. W głębi serca wiesz, że sprawiedliwość to jedyna prawdziwa droga.', '', 0),
(31948, 'koKR', '', 'CHWAŁA! OTO $n, $GCZEMPION:CZEMPIONKA; VALHALAS!', 0),
(31949, 'koKR', '', 'Za późno na ucieczkę. Nie opuszczaj kręgu. Giń dzielnie, $n!', 0),
(31951, 'koKR', '', 'Z głębin Cytadeli Lodowej Korony nadchodzi jeden z wybrańców Króla Lisza. To tu $n i $gjego:jej; przyjaciele mają zakończyć swój żywot.', 0),
(31953, 'koKR', 'Krucjata Argentu nigdy się nie poddaje!', '', 0),
(31955, 'koKR', '', 'Wojownicy Jotunheim, oto przed wami Krwawy Książę Sandoval!', 0),
(31959, 'koKR', 'Ach, ręka Hebanowego Miecza w końcu po mnie przyszła. Drżę ze strachu.', '', 0),
(31961, 'koKR', 'Ha! To wszystko, na co cię stać? Dziwię się, że w ogóle $gdotarłeś:dotarłaś; do cytadeli.', '', 0),
(31962, 'koKR', 'Król Lisz dał mi moc przekraczającą twoje najśmielsze koszmary. Patrz!', '', 0),
(31963, 'koKR', 'Tu wszystko się kończy.', '', 0),
(31964, 'koKR', 'Jesteś wreszcie, Darionie! Zastanawiałem się, kiedy wypełzniesz.', '', 0),
(31966, 'koKR', '%s chichocze porozumiewawczo.', '', 0),
(31967, 'koKR', 'Król Lisz zgasi... każdego... z was... co do jednego.', '', 0),
(31992, 'koKR', 'Uhhh.... Dla mnie jest już za późno, $gbracie:siostro;.$b$bTo... mój koniec...', 'Uhhh.... Dla mnie jest już za późno, $gbracie:siostro;.$b$bTo... mój koniec...', 0),
(32012, 'koKR', 'Zostań ze mną, przyjacielu. Muszę wiedzieć, co się tu stało.', 'Zostań ze mną, przyjacielu. Muszę wiedzieć, co się tu stało.', 0),
(32013, 'koKR', '', '$GCzempionie:Czempionko; $n, dobrze cię znowu widzieć.$B$BCzy $gwróciłeś:wróciłaś; do Valhalas, by pomóc przyjacielowi w jego wyzwaniach?', 0),
(32014, 'koKR', 'Zaatakowaliśmy pod osłoną zamieci....$b$bPlaga została zaskoczona... zwycięstwo było pewne....$b$bA potem... za naszymi plecami... znikąd pojawiła się Horda.$b$bKosztowało nas to... wszystko....', 'Zaatakowaliśmy pod osłoną zamieci....$b$bPlaga została zaskoczona... zwycięstwo było pewne....$b$bA potem... za naszymi plecami... znikąd pojawiła się Horda.$b$bKosztowało nas to... wszystko....', 0),
(32015, 'koKR', 'Rycerze Hebanowego Miecza, gotujcie się do bitwy!', '', 0),
(32017, 'koKR', 'Zaczekaj, $gbracie:pani;....$b$bJeszcze jedno...', 'Zaczekaj, $gbracie:pani;....$b$bJeszcze jedno...', 0),
(32027, 'koKR', 'Nieumarli są tuż-tuż!', '', 0),
(32028, 'koKR', 'Tutaj stawiamy opór!', '', 0),
(32029, 'koKR', 'Plotki były prawdziwe! Książę oszalał!', '', 0),
(32117, 'koKR', 'Mięsarnia już nigdy nie wyprodukuje żołnierzy dla armii Króla Lisza.', '', 0),
(32118, 'koKR', 'Zabijmy to... coś... i miejmy to z głowy.', 'Zabijmy to... coś... i miejmy to z głowy.', 0),
(32195, 'koKR', '', 'Do licha, Olakinie, wracaj tu natychmiast! Jest robota do zrobienia!', 0),
(32213, 'koKR', 'Plagę trzeba powstrzymać za wszelką cenę. Nie możemy pozwolić, by wystawiła armię, którą tu buduje.', '', 0),
(32217, 'koKR', 'Nikt nie będzie we mnie rzucał kamieniami!', '', 0),
(32218, 'koKR', 'Nie chcesz mnie widzieć, kiedy jestem zły...', '', 0),
(32220, 'koKR', 'Wreszcie! Pretekst, żeby cię zgnieść!', '', 0),
(32221, 'koKR', 'Tym razem zginiesz na dobre, szkielecie!', '', 0),
(32222, 'koKR', 'Miarka się przebrała...', '', 0),
(32223, 'koKR', 'Czekałem tylko na pretekst, żeby rozerwać cię na kawałki!', '', 0),
(32224, 'koKR', 'To twój ostatni błąd, szkielecie.', '', 0),
(32256, 'koKR', 'Proszę...$b$bUwolnij mnie...', 'Proszę...$b$bUwolnij mnie...', 0),
(32257, 'koKR', 'Nie myśl, $N.$b$bPo prostu... zrób to....', 'Nie myśl, $N.$b$bPo prostu... zrób to....', 0),
(32258, 'koKR', 'Powiedz mojej rodzinie...$b$bŻe moje ostatnie myśli należały do nich...', 'Powiedz mojej rodzinie...$b$bŻe moje ostatnie myśli należały do nich...', 0),
(32259, 'koKR', 'Odpraw mnie w ostatnią drogę... błagam...', 'Odpraw mnie w ostatnią drogę... błagam...', 0),
(32260, 'koKR', 'Zrób to, $N... A potem... pomścij mnie!', 'Zrób to, $N... A potem... pomścij mnie!', 0),
(32261, 'koKR', 'Proszę...$b$bNie zostawiaj niczego, co Plaga mogłaby wskrzesić!', 'Proszę...$b$bNie zostawiaj niczego, co Plaga mogłaby wskrzesić!', 0),
(32262, 'koKR', 'Szczęśliwej drogi, bohaterze Przymierza!', 'Szczęśliwej drogi, bohaterze Przymierza!', 0),
(32268, 'koKR', 'Ledwie mogę uwierzyć, że Kult był tak nieostrożny, by to zostawić.', '', 0),
(32269, 'koKR', 'Jestem $ggotów:gotowa; dołączyć do szturmu, Keritose. Masz dla mnie szkieletowego gryfa?', 'Jestem $ggotów:gotowa; dołączyć do szturmu, Keritose. Masz dla mnie szkieletowego gryfa?', 0),
(32270, 'koKR', '<Przejmij przez oko kontrolę nad zwinnym czyhaczem.>', '<Przejmij przez oko kontrolę nad zwinnym czyhaczem.>', 0),
(32285, 'koKR', 'Słabością Arthasa jest jego duma. A ta słabość rośnie wraz z jego mocą. Hebanowy Miecz będzie miał okazję uderzyć w byłego księcia – co do tego nie mam wątpliwości.', '', 0),
(32338, 'koKR', 'Nie $gpowinieneś był:powinnaś była; tego robić! Nie spodoba mu się to.', '', 0),
(32343, 'koKR', '', 'Bitwa powietrzna toczy się tuż obok, $n. I my, i Horda wysyłamy bombowce nad Ostrzał i Dolinę Straconej Nadziei. Rzucisz się w wir walki?', 0),
(32344, 'koKR', 'Dajcie mi bombowiec!', 'Dajcie mi bombowiec!', 0),
(32346, 'koKR', 'Trochę zajęty jestem.', 'Trochę zajęty jestem.', 0),
(32347, 'koKR', 'Co? Mam tu robotę.', 'Co? Mam tu robotę.', 0),
(32348, 'koKR', 'Jestem na służbie. ODEJDŹ.', 'Jestem na służbie. ODEJDŹ.', 0),
(32351, 'koKR', 'Dobra, chłopaki, do roboty!', '', 0),
(32353, 'koKR', 'Dzięki za osłonę! Utrzymamy bramę, póki nie nadejdą posiłki.', '', 0),
(32364, 'koKR', '', 'O rany! Ciszej, $n! Co ty? Chcesz nas pozabijać?!$B$BJasne, że wiem, kim jesteś! Kto w Przymierzu nie zna imienia $n?!$B$BPowiedz, co myślisz o moim skokobocie? Wzorowany na projekcie mechagnoma. Smukły i aerodynamiczny!', 0),
(32365, 'koKR', 'Ej, ej, ej! Ciszej, $n. Ciszej!$B$B<Blast rozgląda się.>$B$BNie chcemy, żeby te zmarznięte wrykule nas zauważyły, prawda?$B$BCo myślisz o moim skokobocie? Wzorowany na mechagnomie. Niezły, co?', '', 0),
(32384, 'koKR', 'Przed nami nie ma łatwej drogi. Jeśli masz krzepę w ramieniu, zostań, aż któraś z moich drużyn będzie gotowa do wspinaczki na Ymirheim. Przyda im się każda pomoc.', '', 0),
(32397, 'koKR', 'Nadlatuje!', '', 0),
(32399, 'koKR', 'Na nogi, chłopaki!', '', 0),
(32400, 'koKR', 'Zasadzka!', '', 0),
(32403, 'koKR', 'Zbiórka!', '', 0),
(32404, 'koKR', 'Wrykule atakują!', '', 0),
(32412, 'koKR', 'Masz w sobie ducha walki! Krew i honor, przyjacielu!', '', 0),
(32438, 'koKR', 'Od tego, co tu zrobimy, zależy ludzkie życie. Mów szybko, co masz do powiedzenia, $N.', '', 0),
(32439, 'koKR', 'Przynosisz wieści z pola bitwy?', '', 0),
(32440, 'koKR', 'Najlepsza wojna to szybka wojna. To samo można powiedzieć o rozmowie. Co masz do powiedzenia?', '', 0),
(32444, 'koKR', 'Głosy do mnie mówią.', '', 0),
(32445, 'koKR', 'Muszę słuchać.', '', 0),
(32446, 'koKR', 'Musisz się stąd wydostać, zanim i ciebie dopadnie!', '', 0),
(32450, 'koKR', 'Jest wszędzie wokół nas. Jest w mojej głowie!', '', 0),
(32451, 'koKR', 'Moi ludzie są gotowi. Utoczmy trochę wrykulskiej krwi!', '', 0),
(32452, 'koKR', 'Saronit... coś w nim jest!', '', 0),
(32453, 'koKR', 'Coś tu jest. W skałach i w ziemi!', '', 0),
(32456, 'koKR', 'Muszę się stąd wydostać! Możesz mnie uwolnić?', '', 0),
(32457, 'koKR', 'Słyszysz, jak mówi w twoim umyśle?', '', 0),
(32458, 'koKR', 'Idź, jesteś wolny. Uciekaj stąd!', 'Idź, jesteś wolny. Uciekaj stąd!', 0),
(32466, 'koKR', 'Już idę, panie!', '', 0),
(32467, 'koKR', 'Oddam za ciebie życie!', '', 0),
(32469, 'koKR', 'Nie odejdę!', '', 0),
(32470, 'koKR', 'NIE! Mylisz się! Głosy w mojej głowie są piękne!', '', 0),
(32471, 'koKR', 'Nie chcę odchodzić! Chcę tu zostać!', '', 0),
(32472, 'koKR', 'Nigdy nie wrócę. Cały sens mojego istnienia czeka na dole!', '', 0),
(32473, 'koKR', 'AHAHAHAHA... wkrótce do nas dołączysz!', '', 0),
(32474, 'koKR', 'Muszę zejść głębiej pod ziemię, tam gdzie on jest. Muszę skoczyć!', '', 0),
(32477, 'koKR', 'Kocioł zarazy zaczyna gwałtownie wrzeć!', '', 0),
(32478, 'koKR', 'Coś wyłania się z kotła!', '', 0),
(32479, 'koKR', 'Coś wyłania się z kotła!', '', 0),
(32483, 'koKR', 'Kocioł wciąż wrze...', '', 0),
(32488, 'koKR', 'Porcja zarazy zneutralizowana!', '', 0),
(32506, 'koKR', 'Proszę, już dość.', '', 0),
(32507, 'koKR', 'Uderz mnie jeszcze raz, a pożałujesz!', '', 0),
(32508, 'koKR', 'Au!', '', 0),
(32509, 'koKR', 'Przepraszam. Będę ciężej pracować.', '', 0),
(32510, 'koKR', 'Wkrótce pan znów mnie przygarnie!', '', 0),
(32533, 'koKR', '%s wydaje dziwny dźwięk, który twój umysł odbiera jako śmiech.', '', 0),
(32546, 'koKR', 'Myślisz, że zdołasz wyrwać mi ten wał obronny?', '', 0),
(32547, 'koKR', 'Nie sądzę. Kiedy już wybiję z ciebie tę arogancję, nabiję twoje zwłoki na kolce ku przestrodze innych „bohaterów”!', '', 0),
(32578, 'koKR', 'Już czas. Niech Światłość doda nam sił.', '', 0),
(32589, 'koKR', 'Być może, ale nie muszę stać na świętej ziemi, by przebić Spopielaczem to twoje bezcielesne serce.', '', 0),
(32590, 'koKR', 'Serce... ostatni ślad twojego człowieczeństwa. Musiałem nie dopuścić do jego zniszczenia. Musiałem przekonać się na własne oczy. I wreszcie jestem pewien...', '', 0),
(32592, 'koKR', 'Jesteś odrobinę zbyt pewny siebie. Zwłaszcza zważywszy na to, jak skończyło się nasze ostatnie spotkanie.', '', 0),
(32595, 'koKR', 'Zostały tylko cienie przeszłości. Nie ma już czego odkupić!', '', 0),
(32616, 'koKR', 'Głowy nisko i za mną.', '', 0),
(32619, 'koKR', 'Nadchodzi. Bądźcie gotowi.', '', 0),
(32620, 'koKR', 'Coś jest nie tak... Wyczuwam mroczną obecność.', '', 0),
(32621, 'koKR', 'Król Lisz tu jest. Niech Światłość prowadzi nasze ostrza.', '', 0),
(32624, 'koKR', 'Tym razem nie zginę tak szybko!', '', 0),
(32630, 'koKR', 'Co?!', 'Co?!', 0),
(32632, 'koKR', 'Nagle dziwnie się czuję. Eee?!', 'Nagle dziwnie się czuję. Eee?!', 0),
(32633, 'koKR', 'No dobra, który żartowniś rzucił we mnie kulą?', 'No dobra, który żartowniś rzucił we mnie kulą?', 0),
(32634, 'koKR', 'NIEEEEEE!', 'NIEEEEEE!', 0),
(32636, 'koKR', 'Wszystko źle zrozumieliście. Jestem ciemiężcą!', 'Wszystko źle zrozumieliście. Jestem ciemiężcą!', 0),
(32637, 'koKR', 'To był wypadek. Wrobiono mnie. Nie upuszczajcie mnie!', 'To był wypadek. Wrobiono mnie. Nie upuszczajcie mnie!', 0),
(32687, 'koKR', 'Tirion padł! Brońcie go za cenę życia!', 'Tirion padł! Brońcie go za cenę życia!', 0),
(32695, 'koKR', '$GPrzyszedłeś:Przyszłaś; się na coś przydać?', '', 0),
(32696, 'koKR', '$GPrzyszedłeś:Przyszłaś; się na coś przydać?', '', 0),
(32727, 'koKR', 'Sekret goblińskiej inżynierii wcale nie polega na tym, żeby rzeczy nie wybuchały. Polega na tym, żeby wybuchy szły dokładnie tam, gdzie chcesz.', '', 0),
(32753, 'koKR', 'Khit\'rix Mroczny Mistrz wpełza do Valhalas od południowego wschodu!', '', 0),
(32757, 'koKR', 'Krążąc wokół Valhalas, nadciąga Sigrid Zrodzona z Lodu, żądna zemsty!', '', 0),
(32758, 'koKR', 'Od południa nadchodzi ciężkim krokiem Jatka, a jej smród ją wyprzedza!', '', 0),
(32760, 'koKR', 'Than Banahogg pojawia się na punkcie widokowym na południowym wschodzie!', '', 0),
(32761, 'koKR', 'Bez ostrzeżenia w Valhalas magicznie pojawia się książę Sandoval!', '', 0),
(32812, 'koKR', 'Masz coś do dokręcenia?', '', 0),
(32823, 'koKR', 'Przyszedł pan przemówić do ludzi?', '', 0),
(32828, 'koKR', 'Koltiro... to może zabrzmieć dziwnie, ale ciągle widzę ducha jakiegoś dzieciaka. Matthias Lehner... mówi ci coś to nazwisko?', 'Koltiro... to może zabrzmieć dziwnie, ale ciągle widzę ducha jakiegoś dzieciaka. Matthias Lehner... mówi ci coś to nazwisko?', 0),
(32830, 'koKR', 'Te wszystkie walki w końcu dają ci się we znaki, $n. Nie martw się, nie zdradzę twojego sekreciku – żeby inni nie uznali cię za szaleńca.$B$BOdpocznij trochę. Dobrze ci to zrobi.', '', 0),
(32932, 'koKR', 'Jesteś. Czy jesteś $ggotów:gotowa;? Kiedy zaczniemy, nie będzie odwrotu.', '', 0),
(32933, 'koKR', 'Jestem $ggotów:gotowa;, najwyższy lordzie.', 'Jestem $ggotów:gotowa;, najwyższy lordzie.', 0),
(32973, 'koKR', 'Jeśli cię zestrzelą i złapią, nie podawaj im prawdziwego imienia. Użyj pseudonimu.', '', 0),
(33054, 'koKR', 'Tylko szybko, $N.', '', 0),
(33074, 'koKR', 'Jak mogę ci pomóc, bracie?', 'Jak mogę ci pomóc, bracie?', 0),
(33089, 'koKR', 'Jesteś!', '', 0),
(33090, 'koKR', 'Pokaż mi to jeszcze raz, Matthiasie.', 'Pokaż mi to jeszcze raz, Matthiasie.', 0),
(33429, 'koKR', 'Czy na pewno jesteś $ggotów:gotowa; do walki na wierzchowcu?', 'Czy na pewno jesteś $ggotów:gotowa; do walki na wierzchowcu?', 0),
(33430, 'koKR', 'Jestem $ggotów:gotowa; do walki!', 'Jestem $ggotów:gotowa; do walki!', 0),
(33540, 'koKR', '', 'Teraz nasycę ten kryształ mocą Światłości, która przenika kłamstwa i podstęp.', 0),
(33541, 'koKR', '', 'Daj nam zdolność poznania prawdy. Jeśli kroczy pośród nas morderca, prowadź nas w poszukiwaniu sprawiedliwości.', 0),
(33612, 'koKR', 'Chwała Wichrogrodowi i królowi Wrynnowi!', '', 0),
(33717, 'koKR', 'Srebrny Sojusz wita cię na turnieju. Krucjata Argentu poprosiła nas o rejestrowanie i szkolenie chętnych do udziału w zawodach.', '', 0),
(33747, 'koKR', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze śmiałkiem?', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze śmiałkiem?', 0),
(33748, 'koKR', 'Byłoby nierozsądnie zakładać, że walka ze śmiałkiem to prosta sprawa. Czy na pewno jesteś $ggotów:gotowa;?', 'Byłoby nierozsądnie zakładać, że walka ze śmiałkiem to prosta sprawa. Czy na pewno jesteś $ggotów:gotowa;?', 0),
(33749, 'koKR', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze mną?', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze mną?', 0),
(33750, 'koKR', 'Przygotuj się!', 'Przygotuj się!', 0),
(33752, 'koKR', 'Gardę w górę!', 'Gardę w górę!', 0),
(33753, 'koKR', 'Szykuj się!', 'Szykuj się!', 0),
(33754, 'koKR', 'Zaczynajmy!', 'Zaczynajmy!', 0),
(33755, 'koKR', 'Przygotuj się!', 'Przygotuj się!', 0),
(33756, 'koKR', 'Gardę w górę!', 'Gardę w górę!', 0),
(33757, 'koKR', 'Szykuj się!', 'Szykuj się!', 0),
(33758, 'koKR', 'Zaczynajmy!', 'Zaczynajmy!', 0),
(33760, 'koKR', 'Zostałam pokonana. Dobra walka!', 'Zostałam pokonana. Dobra walka!', 0),
(33763, 'koKR', 'Wygląda na to, że potrzebujesz jeszcze trochę praktyki. Może innym razem.', 'Wygląda na to, że potrzebujesz jeszcze trochę praktyki. Może innym razem.', 0),
(33764, 'koKR', 'Wygląda na to, że potrzebujesz jeszcze trochę praktyki. Może innym razem.', 'Wygląda na to, że potrzebujesz jeszcze trochę praktyki. Może innym razem.', 0),
(33767, 'koKR', 'Poddaję się.', 'Poddaję się.', 0),
(33768, 'koKR', 'Wygląda na to, że nie doceniłam twoich umiejętności. Dobra robota.', 'Wygląda na to, że nie doceniłam twoich umiejętności. Dobra robota.', 0),
(33771, 'koKR', 'Zwycięstwo należy do mnie!', 'Zwycięstwo należy do mnie!', 0),
(33772, 'koKR', 'Obawiam się, że potrzebujesz więcej praktyki, żeby mnie pokonać.', 'Obawiam się, że potrzebujesz więcej praktyki, żeby mnie pokonać.', 0),
(33773, 'koKR', 'Wygrałam. Więcej szczęścia następnym razem, przyjacielu.', 'Wygrałam. Więcej szczęścia następnym razem, przyjacielu.', 0),
(33774, 'koKR', 'Poddaję się.', 'Poddaję się.', 0),
(33775, 'koKR', 'Wygląda na to, że nie doceniłam twoich umiejętności. Dobra robota.', 'Wygląda na to, że nie doceniłam twoich umiejętności. Dobra robota.', 0),
(33776, 'koKR', 'To była dobrze stoczona walka. Poddaję się.', 'To była dobrze stoczona walka. Poddaję się.', 0),
(33777, 'koKR', 'Zwycięstwo należy do mnie!', 'Zwycięstwo należy do mnie!', 0),
(33778, 'koKR', 'Obawiam się, że potrzebujesz więcej praktyki, żeby mnie pokonać.', 'Obawiam się, że potrzebujesz więcej praktyki, żeby mnie pokonać.', 0),
(33779, 'koKR', 'Wygrałam. Więcej szczęścia następnym razem, przyjacielu.', 'Wygrałam. Więcej szczęścia następnym razem, przyjacielu.', 0),
(33780, 'koKR', '', 'Chwała będzie nasza, gdy wygramy ten turniej w imieniu Srebrnej Luny.', 0),
(33784, 'koKR', 'Przybyliśmy walczyć o honor, sławę i prawo do walki z Plagą u boku braci z Krucjaty Argentu.', '', 0),
(33785, 'koKR', '', 'Król Magni oczekuje, że wygramy turniej i przyniesiemy mu chlubę. Nie zawiedziemy go.', 0),
(33786, 'koKR', 'Najlepsi z Gnomoregan przybyli, by stanąć w szranki turnieju. Trzymajcie za nas kciuki!', '', 0),
(33789, 'koKR', 'My, z Darnassus, nie możemy się doczekać rywalizacji w turnieju.', '', 0),
(33794, 'koKR', 'Gdy turniej się rozpocznie, wszyscy ujrzą triumf Porzuconych.', '', 0),
(33795, 'koKR', 'Rywalizacja będzie zacięta, ale czempioni Orgrimmaru zmiażdżą każdego, kto stanie nam na drodze.', '', 0),
(33796, 'koKR', 'Walczymy nie tylko o chwałę, lecz także po to, by przynieść cześć naszym przodkom i naszemu ludowi.', '', 0),
(33797, 'koKR', 'Mroczne Włócznie są gotowe stawić czoła rywalom i wrogowi.', '', 0),
(33798, 'koKR', 'W imieniu Słońcobójców witam cię na turnieju. Krucjata Argentu poprosiła nas, byśmy zapisywali i szkolili chętnych do udziału w zawodach.', '', 0),
(33799, 'koKR', 'Czy jesteś $ggotów:gotowa; zmierzyć się ze śmiałkiem Krucjaty Argentu?', 'Czy jesteś $ggotów:gotowa; zmierzyć się ze śmiałkiem Krucjaty Argentu?', 0),
(33800, 'koKR', 'Gdy będziesz $ggotów:gotowa; do próby na rangę śmiałka, wezwę członka Krucjaty Argentu.', 'Gdy będziesz $ggotów:gotowa; do próby na rangę śmiałka, wezwę członka Krucjaty Argentu.', 0),
(33801, 'koKR', 'To krąg, w którym czempioni ćwiczą, walcząc ze sobą nawzajem. Moim zadaniem jest wzywać rycerzy na ćwiczebne pojedynki.', '', 0),
(33802, 'koKR', 'Poproś Cavina o wezwanie Czarnego Rycerza.', 'Poproś Cavina o wezwanie Czarnego Rycerza.', 0),
(33803, 'koKR', '$n wyzywa Czarnego Rycerza na pojedynek sądowy!', '', 0),
(33804, 'koKR', 'Powodzenia, $n.', '', 0),
(33812, 'koKR', 'Rośnij, maleńki.', '', 0),
(33813, 'koKR', 'No proszę.', '', 0),
(33814, 'koKR', 'Osłoń nas przed tymi przenikliwymi wiatrami, mała sadzonko.', '', 0),
(33834, 'koKR', 'Okaż wsparcie swojemu ulubionemu czempionowi! Załóż jego barwy na następny pojedynek i pokaż, komu kibicujesz!', '', 0),
(33835, 'koKR', 'Chcesz pokazać swoją dumę bez wymachiwania rękami na grzbiecie jednej z tych bestii? Niezależnie od tego, któremu miastu kibicujesz, mam to, czego ci trzeba!', '', 0),
(33836, 'koKR', 'Hej! Zobacz te kubraki! Teraz możesz nosić barwy swojego miasta bez tabardu, który łopocze i plącze się pod nogami!', '', 0),
(33837, 'koKR', 'Ten turniej to największe wydarzenie od wieków! Kup coś, co zabierzesz do domu, rodzinie i dzieciakom na pokaz.', '', 0),
(33865, 'koKR', 'Czy na pewno jesteś $ggotów:gotowa; walczyć z czempionem?', 'Czy na pewno jesteś $ggotów:gotowa; walczyć z czempionem?', 0),
(33866, 'koKR', 'Nierozsądnie byłoby zakładać, że walka z czempionem to proste zadanie. Czy na pewno jesteś $ggotów:gotowa;?', 'Nierozsądnie byłoby zakładać, że walka z czempionem to proste zadanie. Czy na pewno jesteś $ggotów:gotowa;?', 0),
(33867, 'koKR', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze mną?', 'Czy na pewno jesteś $ggotów:gotowa; walczyć ze mną?', 0),
(33868, 'koKR', 'Zostałam pokonana. Dobra walka!', 'Zostałam pokonana. Dobra walka!', 0),
(33929, 'koKR', '', 'W imieniu Krucjaty Argentu witam cię na Turnieju Argentu.', 0),
(33930, 'koKR', 'Nikt nie zbuduje tego szybciej, taniej i lepiej niż bracia Wybuchobełtowie!', '', 0),
(33963, 'koKR', 'Witaj, $N.$B$BSzkolę pretendentów w sztuce konnej walki wręcz.', '', 0),
(33964, 'koKR', 'Pokaż mi, jak ćwiczyć na Celu do walki wręcz.', 'Pokaż mi, jak ćwiczyć na Celu do walki wręcz.', 0),
(33968, 'koKR', 'Cel do walki wręcz uczy pretendentów zarówno konnego ataku, jak i obrony.$B$BPodjedź do Celu do walki wręcz i uderz go Pchnięciem. Siła ciosu często obraca cel tak mocno, że może zranić ciebie albo twojego wierzchowca. Tu właśnie przydaje się obrona.$B$BZanim zaatakujesz cel, upewnij się, że masz co najmniej jedną warstwę Obrony, i przez całe ćwiczenie nakładaj ją i odnawiaj. W przeciwnym razie łatwo możesz wylecieć z siodła.$B$BTo samo dotyczy prawdziwej walki konnej: równoważ atak i obronę, wykonuj Pchnięcie przy każdej okazji i utrzymuj warstwy Obrony najlepiej, jak potrafisz.', '', 0),
(33975, 'koKR', 'Witaj, jak się masz?$B$B$gPrzyszedłeś:Przyszłaś; nauczyć się sztuki Szarży, $N?', '', 0),
(33976, 'koKR', 'Pokaż mi, jak ćwiczyć na Celu do szarży.', 'Pokaż mi, jak ćwiczyć na Celu do szarży.', 0),
(33977, 'koKR', 'No to do dzieła! Konna Szarża to coś więcej niż popędzenie wierzchowca do pełnego galopu i darcie się na całe gardło... choć to akurat NAJLEPSZA zabawa, hehe! Ale Cel do szarży nauczy cię subtelniejszych sztuczek.$B$BDobra Szarża to kwestia odległości i wyczucia czasu. Nie możesz być ZA blisko, bo nie nabierzesz prędkości. Ale nie możesz być też za daleko, bo wierzchowiec się zmęczy! A co do wyczucia czasu...$B$BUpewnij się, że Cel do szarży nie ma na sobie warstwy Obrony, zanim ruszysz. Jeśli ma, użyj Łamacza tarcz, żeby go odsłonić, i DOPIERO WTEDY szarżuj!$B$BZ prawdziwym przeciwnikiem tak samo: najpierw zbij mu obronę, potem Szarża!', '', 0),
(33979, 'koKR', 'No proszę. Kolejny chętny do poznania tajników Łamacza tarcz...?', '', 0),
(33980, 'koKR', 'Pokaż mi, jak ćwiczyć na Celu do walki dystansowej.', 'Pokaż mi, jak ćwiczyć na Celu do walki dystansowej.', 0),
(33981, 'koKR', 'Dystansowy atak Łamaczem tarcz łatwo opanować, ale trudno doprowadzić do mistrzostwa. Sam w sobie może wydawać się słaby, lecz w połączeniu z Pchnięciem i Szarżą Łamacz tarcz czyni z ciebie skutecznego rycerza turniejowego.$B$BZnajdź Cel do walki dystansowej. Poświęć chwilę, by poznać zasięg Łamacza tarcz... ile miejsca potrzebujesz i jak daleko możesz cisnąć kopią.$B$BA potem? No cóż. Zacznij rzucać i nie przestawaj, dopóki nie rozbijesz ostatniej warstwy Obrony i nie przebijesz odsłoniętego celu.$B$BTa taktyka dobrze ci posłuży w prawdziwej walce konnej: rozbij obronę przeciwnika... a potem go zmiażdż!', '', 0),
(34032, 'koKR', 'Użyj Obrony$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$BPotem użyj Pchnięcia na Celu do walki wręcz.$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', 'Użyj Obrony$B|TInterface\\Icons\\Ability_Warrior_ShieldMastery.blp:32|t$BPotem użyj Pchnięcia na Celu do walki wręcz.$B|TInterface\\Icons\\INV_Sword_65.blp:32|t', 0),
(34034, 'koKR', 'Użyj Łamacza tarcz na Celu do szarży.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$BGdy cel jest odsłonięty, poprawiaj Szarżą.$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', 'Użyj Łamacza tarcz na Celu do szarży.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$BGdy cel jest odsłonięty, poprawiaj Szarżą.$B|TInterface\\Icons\\Ability_Mount_Charger.blp:32|t', 0),
(34035, 'koKR', 'Użyj Łamacza tarcz na Celu do walki dystansowej.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$BPotem użyj Łamacza tarcz, gdy cel jest bezbronny.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', 'Użyj Łamacza tarcz na Celu do walki dystansowej.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$BPotem użyj Łamacza tarcz, gdy cel jest bezbronny.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t', 0),
(34089, 'koKR', 'Zanim zacznę cię uczyć, musisz dosiąść turniejowego wierzchowca.$B$BWeź do ręki kopię i znajdź turniejowego wierzchowca przed pawilonem swojej frakcji.', '', 0),
(34090, 'koKR', 'Opowiedz mi więcej o Obronie i Pchnięciu.', 'Opowiedz mi więcej o Obronie i Pchnięciu.', 0),
(34091, 'koKR', 'Opowiedz mi więcej o używaniu Łamacza tarcz.', 'Opowiedz mi więcej o używaniu Łamacza tarcz.', 0),
(34092, 'koKR', 'Opowiedz mi więcej o Szarży.', 'Opowiedz mi więcej o Szarży.', 0),
(34103, 'koKR', 'Moje rady na nic ci się nie zdadzą, jeśli nie siedzisz na turniejowym wierzchowcu.$B$BWeź do ręki kopię i bierz turniejowego wierzchowca sprzed pawilonu swojej frakcji.', '', 0),
(34104, 'koKR', 'Tylko czempioni Wichrogrodu mogą kupić to, co oferuję.', '', 0),
(34116, 'koKR', 'Nie tak szybko!$B$BTylko czempioni Żelaznej Kuźni mogą kupić to, co mam do zaoferowania.', '', 0),
(34120, 'koKR', 'Wybacz, ale tylko czempioni Gromowych Urwisk mogą kupić to, co oferuję.', '', 0),
(34122, 'koKR', '', 'Precz stąd!$B$BTylko czempioni Podmiasta mogą kupić to, co oferuję.', 0),
(34127, 'koKR', '', 'Tylko czempioni Orgrimmaru mogą kupić to, co oferuję.', 0),
(34128, 'koKR', '', 'Tylko czempioni Exodaru mogą kupić to, co oferuję.', 0),
(34131, 'koKR', '', 'Cześć!$B$BWybacz, przyjacielu, ale tylko czempioni Gnomoregan mogą kupić to, co mam.', 0),
(34134, 'koKR', 'Niestety tylko czempioni Darnassus mogą kupić to, co oferuję.', '', 0),
(34136, 'koKR', '', 'Samamba myśleć, że ty przyjść do zły kwatermistrz!$B$BTo, co ona mieć, być tylko dla czempionów z Sen\'jin...', 0),
(34139, 'koKR', 'Niestety tylko szanowni czempioni Srebrnej Luny mogą kupić to, co oferuję.', '', 0),
(34169, 'koKR', 'Zsiadaj z konia i walcz ze mną jak mężczyzna!', '', 0),
(34185, 'koKR', 'Nie zawiodę cię, panie!', '', 0),
(34192, 'koKR', 'Dziękuję wam wszystkim za przybycie na to kazanie. Cudownie widzieć tyle znajomych twarzy!', 'Dziękuję wam wszystkim za przybycie na to kazanie. Cudownie widzieć tyle znajomych twarzy!', 0),
(34193, 'koKR', 'Dziś chciałabym poruszyć temat trzech cnót Światła.', 'Dziś chciałabym poruszyć temat trzech cnót Światła.', 0),
(34194, 'koKR', 'Nastały mroczne i trudne czasy dla nas wszystkich. Armie Plagi gromadzą się na południu. Towarzysze padają na polu bitwy, by chwilę później powstać i służyć naszemu wrogowi.', 'Nastały mroczne i trudne czasy dla nas wszystkich. Armie Plagi gromadzą się na południu. Towarzysze padają na polu bitwy, by chwilę później powstać i służyć naszemu wrogowi.', 0),
(34196, 'koKR', 'Wielu z was doświadczyło zdrady zaufania.', 'Wielu z was doświadczyło zdrady zaufania.', 0),
(34197, 'koKR', 'A jednak wytrwaliście, jak musimy wszyscy. W tych czasach nikomu nie jest obca cnota wytrwałości. W obliczu rozpaczy i nienawiści wciąż pozostajemy wierni naszym przekonaniom i walczymy dalej.', 'A jednak wytrwaliście, jak musimy wszyscy. W tych czasach nikomu nie jest obca cnota wytrwałości. W obliczu rozpaczy i nienawiści wciąż pozostajemy wierni naszym przekonaniom i walczymy dalej.', 0),
(34199, 'koKR', 'Waszej wytrwałości nie sposób kwestionować... ale są też inne cnoty, nad którymi warto się zastanowić.', 'Waszej wytrwałości nie sposób kwestionować... ale są też inne cnoty, nad którymi warto się zastanowić.', 0),
(34200, 'koKR', 'Szacunek to pierwsza cnota, której uczy się tych, którzy wkraczają na ścieżkę Światła.', 'Szacunek to pierwsza cnota, której uczy się tych, którzy wkraczają na ścieżkę Światła.', 0),
(34201, 'koKR', 'Spójrzcie na drugą stronę nawy, na tych, których nazwalibyście wrogami. Mimo dzielącej was nienawiści wasi przeciwnicy mają przymioty godne szacunku. Należy uznać ich męstwo.', 'Spójrzcie na drugą stronę nawy, na tych, których nazwalibyście wrogami. Mimo dzielącej was nienawiści wasi przeciwnicy mają przymioty godne szacunku. Należy uznać ich męstwo.', 0),
(34202, 'koKR', 'Każdy z tu zgromadzonych ma swoje pojęcie o honorowej walce. Postępowanie z honorem i traktowanie przeciwnika tak, jak sami chcielibyście być traktowani, to wyraz szacunku.', 'Każdy z tu zgromadzonych ma swoje pojęcie o honorowej walce. Postępowanie z honorem i traktowanie przeciwnika tak, jak sami chcielibyście być traktowani, to wyraz szacunku.', 0),
(34203, 'koKR', 'Szanujcie przeciwnika na polu walki, czy to wasz brat, czy zaprzysięgły wróg. Bez względu na to, w co naprawdę wierzycie, taki szacunek jest uznaniem więzi...', 'Szanujcie przeciwnika na polu walki, czy to wasz brat, czy zaprzysięgły wróg. Bez względu na to, w co naprawdę wierzycie, taki szacunek jest uznaniem więzi...', 0),
(34205, 'koKR', '...a uznając te więzi, jesteście bliżej Światła.', '...a uznając te więzi, jesteście bliżej Światła.', 0),
(34206, 'koKR', 'Na ścieżce Światła jest jeszcze jeden krok: współczucie.', 'Na ścieżce Światła jest jeszcze jeden krok: współczucie.', 0),
(34207, 'koKR', 'W dzisiejszych czasach wszędzie pełno rywalizacji. Łatwo dostrzec różnice, gdziekolwiek się spojrzy.', 'W dzisiejszych czasach wszędzie pełno rywalizacji. Łatwo dostrzec różnice, gdziekolwiek się spojrzy.', 0),
(34208, 'koKR', 'Wyzwaniem jest spojrzeć poza pozory i zrozumieć, co nas łączy. Dzięki temu zrozumieniu możecie poczuć współczucie wobec strat, jakie ponieśli inni...', 'Wyzwaniem jest spojrzeć poza pozory i zrozumieć, co nas łączy. Dzięki temu zrozumieniu możecie poczuć współczucie wobec strat, jakie ponieśli inni...', 0),
(34209, 'koKR', '...nawet jeśli ofiara nosi inny sztandar.', '...nawet jeśli ofiara nosi inny sztandar.', 0),
(34210, 'koKR', 'Odczuwając i rozumiejąc współczucie zarówno wobec wroga, jak i sojusznika, umacniacie swoją więź ze światem.', 'Odczuwając i rozumiejąc współczucie zarówno wobec wroga, jak i sojusznika, umacniacie swoją więź ze światem.', 0),
(34211, 'koKR', 'Postępowanie zgodnie z tymi zasadami, tymi cnotami, pomaga uczynić świat miejscem, które wszyscy możemy docenić. Światem honoru i sprawiedliwości.', 'Postępowanie zgodnie z tymi zasadami, tymi cnotami, pomaga uczynić świat miejscem, które wszyscy możemy docenić. Światem honoru i sprawiedliwości.', 0),
(34212, 'koKR', 'Zastanówcie się nad moimi słowami, przyjaciele. W ciemności, która nas wszystkich otacza, Światło jest potrzebne bardziej niż kiedykolwiek.', 'Zastanówcie się nad moimi słowami, przyjaciele. W ciemności, która nas wszystkich otacza, Światło jest potrzebne bardziej niż kiedykolwiek.', 0),
(34216, 'koKR', 'Będę za kratą konfesjonału, gdyby ktoś chciał ze mną porozmawiać. Chętnie ukoję wszelkie wątpliwości, troski i niepewności.', 'Będę za kratą konfesjonału, gdyby ktoś chciał ze mną porozmawiać. Chętnie ukoję wszelkie wątpliwości, troski i niepewności.', 0),
(34242, 'koKR', 'Witaj na turnieju, $n.', '', 0),
(34243, 'koKR', '', 'Dobrze cię tu widzieć, $n.', 0),
(34246, 'koKR', 'Nie wiem, czy dam radę walczyć! Wszyscy są o tyle więksi!', 'Nie wiem, czy dam radę walczyć! Wszyscy są o tyle więksi!', 0),
(34247, 'koKR', 'Obliczyłem prawdopodobieństwo mojego sukcesu i jest niepokojąco niskie!', 'Obliczyłem prawdopodobieństwo mojego sukcesu i jest niepokojąco niskie!', 0),
(34248, 'koKR', 'Nie potrafię precyzyjnie przeliczyć matematyki szarży mojego turbobiegusa, trzymając jednocześnie kopię pod idealnie dobranym kątem i utrzymując tarczę dokładnie w miejscu zapewniającym maksymalną ochronę w każdej sekundzie!', 'Nie potrafię precyzyjnie przeliczyć matematyki szarży mojego turbobiegusa, trzymając jednocześnie kopię pod idealnie dobranym kątem i utrzymując tarczę dokładnie w miejscu zapewniającym maksymalną ochronę w każdej sekundzie!', 0),
(34249, 'koKR', '...a niektóre z tych wierzchowców mogą mnie stratować!', '...a niektóre z tych wierzchowców mogą mnie stratować!', 0),
(34250, 'koKR', 'Głowa do góry. Nie liczy się wzrost, lecz to, jak wykorzystujesz umiejętności, które masz.', 'Głowa do góry. Nie liczy się wzrost, lecz to, jak wykorzystujesz umiejętności, które masz.', 0),
(34251, 'koKR', 'To, czego ci brakuje we wzroście, nadrabiasz ambicją i oddaniem, maleńki. Idź ze Światłem.', 'To, czego ci brakuje we wzroście, nadrabiasz ambicją i oddaniem, maleńki. Idź ze Światłem.', 0),
(34252, 'koKR', 'Po drodze tutaj walnąłem pingwina.', 'Po drodze tutaj walnąłem pingwina.', 0),
(34253, 'koKR', 'Nie, nie naprawdę. Chciałem tylko zobaczyć twoją minę.', 'Nie, nie naprawdę. Chciałem tylko zobaczyć twoją minę.', 0),
(34254, 'koKR', 'Ojej. Czy chociaż czujesz skruchę?', 'Ojej. Czy chociaż czujesz skruchę?', 0),
(34255, 'koKR', 'Panienko, muszę ci się z czegoś wyspowiadać.', 'Panienko, muszę ci się z czegoś wyspowiadać.', 0),
(34256, 'koKR', 'Czuję... pewne żądze.', 'Czuję... pewne żądze.', 0),
(34257, 'koKR', 'Naszło mnie to z wielką siłą, kiedy słuchałem twojego kazania, i doprowadza mnie do szału!', 'Naszło mnie to z wielką siłą, kiedy słuchałem twojego kazania, i doprowadza mnie do szału!', 0),
(34258, 'koKR', '...MUSZĘ SIĘ NAPIĆ!', '...MUSZĘ SIĘ NAPIĆ!', 0),
(34259, 'koKR', 'W takim razie pij z umiarem, mój krasnoludzki przyjacielu, ale może na razie lepiej odłóż kopię i wodze. Idź ze Światłem.', 'W takim razie pij z umiarem, mój krasnoludzki przyjacielu, ale może na razie lepiej odłóż kopię i wodze. Idź ze Światłem.', 0),
(34260, 'koKR', 'Z każdym dniem moje serce jest cięższe, spowiedniczko.', 'Z każdym dniem moje serce jest cięższe, spowiedniczko.', 0),
(34261, 'koKR', 'Rozkazano mi tu przybyć, więc tu zostaję i walczę pod sztandarem Wichrogrodu. Ale wszystko, co tu robię, jest puste.', 'Rozkazano mi tu przybyć, więc tu zostaję i walczę pod sztandarem Wichrogrodu. Ale wszystko, co tu robię, jest puste.', 0),
(34262, 'koKR', 'Poza tymi granicami Plaga nie ustaje w swoim dziele i niszczy coraz więcej z tego, co zbudowaliśmy. To tam powinna toczyć się walka. To tam powinienem być.', 'Poza tymi granicami Plaga nie ustaje w swoim dziele i niszczy coraz więcej z tego, co zbudowaliśmy. To tam powinna toczyć się walka. To tam powinienem być.', 0),
(34263, 'koKR', 'Jak mogę usprawiedliwić potyczki na kopie, gdy ludzie giną bez mojej ochrony?', 'Jak mogę usprawiedliwić potyczki na kopie, gdy ludzie giną bez mojej ochrony?', 0),
(34264, 'koKR', 'Masz dobre serce i wiem, że pragniesz służyć Światłu. Ale te drobne ciosy niewiele znaczą dla wielkiej armii nieumarłych.', 'Masz dobre serce i wiem, że pragniesz służyć Światłu. Ale te drobne ciosy niewiele znaczą dla wielkiej armii nieumarłych.', 0),
(34265, 'koKR', 'Ten turniej pomaga stworzyć silną, zjednoczoną siłę, choć może nie wydawać się to oczywiste. Gdy będziemy gotowi, oczy Krucjaty i wszystkich jej czempionów zwrócą się ku Lodowej Koronie.', 'Ten turniej pomaga stworzyć silną, zjednoczoną siłę, choć może nie wydawać się to oczywiste. Gdy będziemy gotowi, oczy Krucjaty i wszystkich jej czempionów zwrócą się ku Lodowej Koronie.', 0),
(34266, 'koKR', 'Przeciwko Królowi Liszowi stanie potęga wszystkich ras i zostanie on pokonany.', 'Przeciwko Królowi Liszowi stanie potęga wszystkich ras i zostanie on pokonany.', 0),
(34267, 'koKR', 'Wiem, że nie wydaje ci się to oczywistą ścieżką, ale przybliży cię do Światła. Walcz dzielnie, bracie.', 'Wiem, że nie wydaje ci się to oczywistą ścieżką, ale przybliży cię do Światła. Walcz dzielnie, bracie.', 0),
(34269, 'koKR', 'To nie jest honorowa walka. Tęsknię za tym, by stawać do bitwy z toporem w dłoni!', 'To nie jest honorowa walka. Tęsknię za tym, by stawać do bitwy z toporem w dłoni!', 0),
(34270, 'koKR', 'To są moi wrogowie. TY byłabyś moim wrogiem w bitwie! Twój król wypowiedział wojnę mojemu ludowi!', 'To są moi wrogowie. TY byłabyś moim wrogiem w bitwie! Twój król wypowiedział wojnę mojemu ludowi!', 0),
(34271, 'koKR', 'Ale zamiast walczyć jak mój lud, jak mój lud powinien, trzymam długą, nieporęczną tyczkę i próbuję nakłonić wilka do szarży na przeciwnika bez atakowania go.', 'Ale zamiast walczyć jak mój lud, jak mój lud powinien, trzymam długą, nieporęczną tyczkę i próbuję nakłonić wilka do szarży na przeciwnika bez atakowania go.', 0),
(34272, 'koKR', 'Orkowie tak nie walczą! Obowiązek wobec wodza walczy we mnie z osobistym honorem. Nie wierzę w twoje Światło, ale skoro wyglądasz na doradczynię, wysłucham twoich słów.', 'Orkowie tak nie walczą! Obowiązek wobec wodza walczy we mnie z osobistym honorem. Nie wierzę w twoje Światło, ale skoro wyglądasz na doradczynię, wysłucham twoich słów.', 0),
(34285, 'koKR', 'Rozumiem twoją frustrację. Twój lud jest zaciekły w boju, a to nie jest to, do czego przywykłeś.', 'Rozumiem twoją frustrację. Twój lud jest zaciekły w boju, a to nie jest to, do czego przywykłeś.', 0),
(34286, 'koKR', 'Ale to inny rodzaj honorowej walki. Może trudno się do niej przystosować, ale przy twoim męstwie jestem pewna, że pokażesz wszystkim siłę swojego ludu.', 'Ale to inny rodzaj honorowej walki. Może trudno się do niej przystosować, ale przy twoim męstwie jestem pewna, że pokażesz wszystkim siłę swojego ludu.', 0),
(34287, 'koKR', 'Poza tym... topór bywa cennym narzędziem na wojnie, ale kopie też mają swoje zastosowania.', 'Poza tym... topór bywa cennym narzędziem na wojnie, ale kopie też mają swoje zastosowania.', 0),
(34289, 'koKR', 'Te walki nie mają końca. Nie wiem, ile jeszcze zdołam znieść.', 'Te walki nie mają końca. Nie wiem, ile jeszcze zdołam znieść.', 0),
(34290, 'koKR', 'Całe to pozerstwo, całe to tańczenie po arenach... wydaje się bezcelowe. Po co to wszystko?', 'Całe to pozerstwo, całe to tańczenie po arenach... wydaje się bezcelowe. Po co to wszystko?', 0),
(34291, 'koKR', 'A na dodatek hełm ZACZYNA MI NISZCZYĆ FRYZURĘ. To skandal!', 'A na dodatek hełm ZACZYNA MI NISZCZYĆ FRYZURĘ. To skandal!', 0),
(34292, 'koKR', 'Może się to wydawać bezcelowe, ale spróbuj czerpać dumę z dobrej walki. Przyjdzie czas, gdy wszystkie te ćwiczenia i zawody zostaną dobrze spożytkowane.', 'Może się to wydawać bezcelowe, ale spróbuj czerpać dumę z dobrej walki. Przyjdzie czas, gdy wszystkie te ćwiczenia i zawody zostaną dobrze spożytkowane.', 0),
(34293, 'koKR', 'A włosy masz cudowne.', 'A włosy masz cudowne.', 0),
(34377, 'koKR', 'Jak walczą jeźdźcy Krucjaty Argentu?', 'Jak walczą jeźdźcy Krucjaty Argentu?', 0),
(34378, 'koKR', 'Jeźdźcy Krucjaty Argentu cenią równowagę i precyzję, zręcznie łącząc atak z obroną.$B$BCzęsto jednak sami wystawiają się na Szarżę, próbując zwiększyć dystans.$B$BSkróć ten dystans Szarżą, zanim oni zrobią to samo, a potem rozbij ich obronę Łamaczem tarcz, gdy zawracasz do kolejnych Pchnięć.', 'Jeźdźcy Krucjaty Argentu cenią równowagę i precyzję, zręcznie łącząc atak z obroną.$B$BCzęsto jednak sami wystawiają się na Szarżę, próbując zwiększyć dystans.$B$BSkróć ten dystans Szarżą, zanim oni zrobią to samo, a potem rozbij ich obronę Łamaczem tarcz, gdy zawracasz do kolejnych Pchnięć.', 0),
(34392, 'koKR', 'Witaj w naszej małej kaplicy Światła. Proszę, usiądź. Odpocznij od bolączek tego świata.', 'Witaj w naszej małej kaplicy Światła. Proszę, usiądź. Odpocznij od bolączek tego świata.', 0),
(34395, 'koKR', 'Już dziś $gpokonałeś:pokonałaś; jednego z naszych jeźdźców, więc nie mogę przyjąć twojego wyzwania.', 'Już dziś $gpokonałeś:pokonałaś; jednego z naszych jeźdźców, więc nie mogę przyjąć twojego wyzwania.', 0),
(34400, 'koKR', '$gPrzyszedłeś:Przyszłaś; na kazanie spowiedniczki? Powodzenia w szukaniu miejsca do siedzenia...', '', 0),
(34423, 'koKR', 'To zaszczyt reprezentować Krucjatę Argentu w tym turnieju.', '', 0),
(35142, 'koKR', 'Prawdziwy krzyżowiec to ktoś więcej niż tylko bohater w walce ze złem... to wzór do naśladowania, ten, kto jednoczy innych wokół sprawy, czempion w oczach całego swojego ludu.$B$BJako wielki krzyżowiec mam obowiązek powierzać takim mężczyznom i kobietom godne zadania.', '', 0),
(35160, 'koKR', '', 'Są nagrody przeznaczone wyłącznie dla tych, którzy zdobyli tytuł krzyżowca – wysławianych w oczach Krucjaty Argentu i wszystkich sprzymierzonych z nią ludów.$B$BSam Tirion polecił mi odnajdywać takich bohaterów i nadawać im należne odznaczenia.', 0),
(35181, 'koKR', 'Zabijają więźniów! Szybko, pomóż pozostałym.', 'Zabijają więźniów! Szybko, pomóż pozostałym.', 0),
(35182, 'koKR', 'Myślałam, że nigdy nie wyjdę stąd żywa.', 'Myślałam, że nigdy nie wyjdę stąd żywa.', 0),
(35183, 'koKR', 'Myślałam, że tam zginę!', 'Myślałam, że tam zginę!', 0),
(35184, 'koKR', 'Wiedziałam, że nie powinnam była przyjeżdżać na turniej!', 'Wiedziałam, że nie powinnam była przyjeżdżać na turniej!', 0),
(35227, 'koKR', 'Śmiesz wyzywać Drottinna Hrothgara, króla mórz?', '', 0),
(35291, 'koKR', 'Nareszcie... teraz mogę odpocząć.', 'Nareszcie... teraz mogę odpocząć.', 0),
(35292, 'koKR', 'Mój koszmar... czy to już naprawdę koniec?', 'Mój koszmar... czy to już naprawdę koniec?', 0),
(35293, 'koKR', 'To było straszne... Śniło mi się, że walczę przeciwko swoim przyjaciołom.', 'To było straszne... Śniło mi się, że walczę przeciwko swoim przyjaciołom.', 0),
(35294, 'koKR', 'Nie słyszę już krzyków. Czy to koniec?', 'Nie słyszę już krzyków. Czy to koniec?', 0),
(35295, 'koKR', 'Jestem taki zmęczony. Pozwól mi odpocząć choć przez chwilę.', 'Jestem taki zmęczony. Pozwól mi odpocząć choć przez chwilę.', 0),
(35345, 'koKR', 'Dosiądź hipogryfa i przygotuj się do walki!', 'Dosiądź hipogryfa i przygotuj się do walki!', 0),
(35346, 'koKR', '<Hipogryf wygląda na podekscytowanego i gotowego do drogi!>', '', 0),
(35393, 'koKR', 'Głupcze, nie powstrzymasz kvaldirów!', '', 0),
(35790, 'koKR', 'Jeszcze chwila, a przywiązaliby mnie do jednego z tych ołtarzy i wyssali mi duszę. Wynośmy się stąd!', '', 0),
(35810, 'koKR', 'Jego Wysokość król Varian Wrynn i lady Jaina Proudmoore wylądowali na placu turniejowym! Zrobić przejście!', '', 0),
(35811, 'koKR', 'Wódz Hordy Thrall i nadrządca Garosz Piekłorycz przybyli na plac turniejowy! Oczyścić drogę do wejścia!', '', 0),
(35812, 'koKR', 'Najwyższy lord Tirion Fordring zbliża się do podium, by przemówić do zgromadzonych na placu turniejowym! Podejdźcie pod podium, by go wysłuchać!', '', 0),
(35814, 'koKR', 'Wiatr zaciekle smaga ten urwisty płaskowyż, a większość życia dawno uciekła z tego zakątka Lodowej Korony. Wystarczy jednak odrobina zachęty, by wróciło, i dlatego przemierzam te ziemie. Pewnego dnia te drzewa wyrosną wysoko ponad nas wszystkich.', '', 0),
(35815, 'koKR', 'Ja, Wilfred Bombik, zostałem zaproszony na ten uroczy turniej, by wykorzystać moją rozległą wiedzę o sztuce przywoływania. Czyż mogli wybrać lepiej?', '', 0),
(35816, 'koKR', 'Wkrótce cały świat pozna imię Wilfreda!', '', 0),
(35817, 'koKR', 'Niedługo nazwisko Bombik będzie znane w każdym domu i będzie się nim straszyć dzieci, żeby szły spać! „Uważaj, bo Bombik przywoła potężnego demona, który cię zje!”', '', 0),
(35818, 'koKR', 'Oczywiście to mnie wybrano, bym przywołał demona dla zawodników. Jestem Wilfred Bombik, mistrz przywoływania! Demony drżą na samą myśl o tym, że mogłyby ulec mej woli!', '', 0),
(35840, 'koKR', 'Magnataurowie nie są tak głupi, na jakich wyglądają. Utrzymanie Gormoka w niewoli do czasu jego walki to trudne zadanie, ale jest tak mocno spętany, że nie ma żadnego niebezpieczeństwa.', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(35841, 'koKR', 'Zajmuję się tymi stworzeniami Gormoka, bo on sam nie może. Nie do końca popieram tę rzeź, ale przynajmniej będzie miał szansę walczyć.', '', 0),
(35842, 'koKR', 'Yeti to zaciekłe, przebiegłe stworzenie, a ten jest jednym z najsilniejszych w swoim rodzaju. Utrzymujemy go w uśpieniu dzięki ziołom dodawanym do jedzenia.$b$bNie myśl jednak, że na arenie będzie ospały.', '', 0),
(35843, 'koKR', 'Od jakiegoś czasu zajmujemy się tymi czerwiami. Mam nadzieję, że będą w formie na czas walk na arenie. W końcu trzeba się zmierzyć nie z jednym, lecz z dwoma jormungarami.', '', 0),
(35844, 'koKR', 'Możemy działać w cieniu dobrego towarzystwa, ale tutaj, na froncie, nasze moce są wreszcie należycie szanowane.', 'Możemy działać w cieniu dobrego towarzystwa, ale tutaj, na froncie, nasze moce są wreszcie należycie szanowane.', 0),
(35845, 'koKR', 'Ty! Tak, ty!$b$bSpójrz na mnie i zachowaj w pamięci tę chwilę spotkania, bo wkrótce świat pozna i będzie się lękać imienia i surowego oblicza Wilfreda Bombika! Gdy dokonam mego wspaniałego przywołania, nikt nie będzie wątpił w moje zdolności!', '', 0),
(35959, 'koKR', '', 'Justycjariuszka Mariel Prawe Serce poprosiła nas, byśmy zadbali o potrzeby turnieju. Tych, którzy zasłużyli na prawo do miana czempionów i dowiedli swojej wartości w naszych oczach, prosimy o pomoc w tych obowiązkach.', 0),
(36033, 'koKR', '', 'Seneszal turnieju poprosił nas, byśmy przejęli część ciężaru prowadzenia zawodów teraz, gdy koloseum jest ukończone. Tych, którzy zasłużyli na prawo do miana czempionów i dowiedli swojej wartości w naszych oczach, prosimy o pomoc w tych obowiązkach.', 0),
(36822, 'koKR', 'Co cię tu sprowadza, $N?', '', 0),
(36824, 'koKR', 'Jestem $ggotów:gotowa; dostarczyć księgę, magistrze Hathorelu.', 'Jestem $ggotów:gotowa; dostarczyć księgę, magistrze Hathorelu.', 0),
(36825, 'koKR', 'Nigdy nie ufaj Słońcobójcom. Pilnie pracują nad tym, by podkopać naszą pozycję w oczach naszych sojuszników z Krucjaty Argentu.', '', 0),
(36830, 'koKR', 'Czy możesz odnowić moje przebranie Słońcobójców?', 'Czy możesz odnowić moje przebranie Słońcobójców?', 0),
(36832, 'koKR', 'Czy możesz odnowić moje przebranie Srebrnego Sojuszu, magistrze Hathorelu?', 'Czy możesz odnowić moje przebranie Srebrnego Sojuszu, magistrze Hathorelu?', 0),
(37211, 'koKR', '%s szykuje się do ataku!', '', 0),
(37212, 'koKR', 'Wsiadaj, już! Całe to zbocze może się w każdej chwili zawalić.', '', 0),
(37213, 'koKR', 'Szybko, wsiadaj! Nie możemy tu zwlekać! Nie wiadomo, kiedy całe to zbocze się zawali.', '', 0),
(37580, 'koKR', '$gSpóźniłeś:Spóźniłaś; się, kurierze. Nie, nie chcę słyszeć żadnych wymówek – to zadanie jest o wiele za ważne.', '', 0),
(37581, 'koKR', 'Oto księga, którą nasz przedstawiciel przywiózł ze Żmijowego Spoczynku. Zanieś ją natychmiast Myralionowi Słonecznemu Żarowi.', '', 0),
(37582, 'koKR', 'Uważaj na siebie, kurierze. Nie muszę ci przypominać, ile warta jest ta księga ani że Srebrny Sojusz nie cofnie się przed niczym, by nam ją odebrać.', '', 0),
(37620, 'koKR', 'Dobrze, że wreszcie jesteś, kurierze. Krasus powierzył nam jeden z niewielu zachowanych egzemplarzy „Pradawnych ostrzy wykutych przez smoki”.', '', 0),
(37621, 'koKR', 'Oto księga. Musisz dopilnować, by trafiła do Caladisa Jasnowłóczni w Lodowej Koronie, zanim Słońcobójcy zorientują się, co się dzieje.', '', 0),
(37622, 'koKR', 'Ruszaj szybko! Słońcobójcy nie będą tracić czasu, gdy tylko się zorientują, że mamy informacje, których szukają.', '', 0),
(37645, 'koKR', 'Quel\'Delar budzi się do życia w obecności Ostrza Mrozu!', '', 0),
(37887, 'koKR', 'Nie jesteś tu mile $gwidziany:widziana;, sługo Króla Lisza!', 'Nie jesteś tu mile $gwidziany:widziana;, sługo Króla Lisza!', 0),
(38105, 'koKR', 'Naprawdę niesamowity miecz, nie sądzisz? To nie jest broń krasnoludzkiej roboty, o nie, jest o wiele starsza.$B$BPrzedstawiciele Słońcobójców i Srebrnego Sojuszu najwyraźniej chcą dotrzeć do sedna tej zagadki. Już piszę raport dla Branna.', '', 0);
